namespace feature {
Ranges ranges(Hand const &hand, RangeContext const &ctx, int cut, void *context,
              Score score, uint64_t draw) {
  uint8_t counts[34]{};
  for (int i = 0; i < hand.size; ++i)
    ++counts[hand.tiles[i] / 4];
  int shanten = int(draw >> 34) - 1;
  uint64_t improving = draw & ((1ull << 34) - 1);
  Ranges result{};
  if (shanten < 0 || shanten > 1)
    return result;
  result.eligible = 1;
  if (shanten == 0) {
    score(context, &hand, &ctx, cut, improving, &result);
    return result;
  }
  auto next = ctx;
  next.missed_agari = 0;
  if (cut >= 0)
    next.own_discards |= 1ull << cut;
  for (int base = 0; base < 34; ++base)
    if ((improving & (1ull << base)) && ctx.unavailable[base] < 4) {
      ++counts[base];
      ++next.unavailable[base];
      uint64_t waits[34]{};
      nyanten_tenpai_discards(counts, waits);
      bool five = base == 4 || base == 13 || base == 22;
      int reds = five ? 1 - ctx.unavailable_red[base / 9] : 0;
      int copies[] = {4 - ctx.unavailable[base] - reds, reds};
      for (int is_red = 0; is_red < 2; ++is_red)
        if (copies[is_red] > 0) {
          int tile = base * 4 + (five && !is_red);
          while (std::find(hand.tiles, hand.tiles + hand.size, tile) !=
                 hand.tiles + hand.size)
            ++tile;
          auto after = hand;
          after.tiles[after.size++] = tile;
          if (is_red)
            ++next.unavailable_red[base / 9];
          bool seen[37]{};
          for (int pos = 0; pos < after.size; ++pos) {
            int discarded = after.tiles[pos], code = feature::code(discarded);
            if (seen[code] || !waits[discarded / 4])
              continue;
            seen[code] = true;
            auto ready = after;
            std::move(ready.tiles + pos + 1, ready.tiles + ready.size, ready.tiles + pos);
            --ready.size;
            Ranges value{};
            score(context, &ready, &next, discarded / 4, waits[discarded / 4], &value);
            result.merge(value);
          }
          if (is_red)
            --next.unavailable_red[base / 9];
        }
      --counts[base];
      --next.unavailable[base];
    }
  return result;
}
} // namespace feature
extern "C" void feature_ranges(feature::Hand const *hand,
                               feature::RangeContext const *ctx, int cut, void *opaque,
                               feature::Score score, feature::Ranges *out) {
  uint8_t counts[34]{};
  for (int i = 0; i < hand->size; ++i)
    ++counts[hand->tiles[i] / 4];
  *out = feature::ranges(*hand, *ctx, cut, opaque, score, nyanten_draw(counts, 1));
}

#include "features.hpp"
namespace feature {
void public_values(Meld const *melds, int size, int const *dora, int &fu, int &bonus) {
  fu = bonus = 0;
  constexpr int values[] = {0, 2, 8, 16, 8};
  for (int i = 0; i < size; ++i) {
    auto const &m = melds[i];
    int t = m.tiles[0] / 4;
    fu += values[m.kind] * (1 + (t >= 27 || t % 9 == 0 || t % 9 == 8));
    for (int j = 0; j < m.size; ++j)
      bonus += dora[m.tiles[j] / 4] + red(m.tiles[j]);
  }
}
void yaku(Meld const *melds, int size, int const *available, int round, int seat,
          uint8_t *out) {
  bool fixed[34]{};
  bool simple = true, suited = true, honors = true, terminals = true,
       terminal_honor = true, outside_all = true, closed = true;
  unsigned suits = 0;
  int sequences = 0, free = 4 - size;
  auto terminal = [](int t) { return t < 27 && (t % 9 == 0 || t % 9 == 8); };
  for (int i = 0; i < size; ++i) {
    auto const &m = melds[i];
    sequences += m.kind == 0;
    if (m.kind != 0)
      fixed[m.tiles[0] / 4] = true;
    bool outside = false;
    closed &= !m.opened;
    for (int j = 0; j < m.size; ++j) {
      int t = m.tiles[j] / 4;
      if (t < 27)
        suits |= 1u << (t / 9);
      simple &= t < 27 && !terminal(t);
      suited &= t < 27;
      honors &= t >= 27;
      terminals &= terminal(t);
      terminal_honor &= t >= 27 || terminal(t);
      outside |= t >= 27 || terminal(t);
    }
    outside_all &= outside;
  }
  auto triplet = [&](int t) { return fixed[t] || (free > 0 && available[t] >= 3); };
  std::fill_n(out, 19, 0);
  out[0] = simple;
  int dragons[] = {31, 32, 33, 27 + round, 27 + seat};
  for (int i = 0; i < 5; ++i)
    out[1 + i] = triplet(dragons[i]);
  out[6] = __builtin_popcount(suits) <= 1;
  out[7] = out[6] && suited;
  out[8] = sequences == 0;
  out[9] = size == 0;
  for (int pair = 31; pair < 34; ++pair) {
    bool valid = !fixed[pair] && available[pair] >= 2;
    int needed = 0;
    for (int t = 31; t < 34; ++t)
      if (t != pair) {
        valid &= triplet(t);
        needed += !fixed[t];
      }
    out[10] |= valid && needed <= free;
  }
  int needed = 0;
  bool valid = true;
  for (int t = 31; t < 34; ++t) {
    valid &= triplet(t);
    needed += !fixed[t];
  }
  out[11] = valid && needed <= free;
  out[12] = honors;
  out[13] = terminals;
  out[14] = terminal_honor;
  out[15] = size == 0;
  for (int t = 0; t < 34; ++t)
    if (t >= 27 || terminal(t))
      out[15] &= available[t] > 0;
  out[16] = outside_all && (sequences > 0 || free > 0);
  out[17] = out[16] && suited;
  out[18] = closed && free >= 2;
}
} // namespace feature
extern "C" void feature_yaku(feature::Meld const *melds, int size, int const *available,
                             int round, int seat, uint8_t *out) {
  feature::yaku(melds, size, available, round, seat, out);
