use packed::{FIELDS, Row};
use pyo3::{
    prelude::*,
    types::{PyBytes, PyDict},
};
fn columns<'py>(py: Python<'py>, rows: &[&Row]) -> PyResult<Bound<'py, PyDict>> {
    let output = PyDict::new(py);
    for field in FIELDS {
        let bytes = PyBytes::new_with(py, field.size * rows.len(), |bytes| {
            for (destination, row) in bytes.chunks_exact_mut(field.size).zip(rows) {
                destination.copy_from_slice(&row.bytes[field.offset..field.offset + field.size]);
            }
            Ok(())
        })?;
        output.set_item(field.name, bytes)?;
    }
    Ok(output)
}
#[pyclass]
struct FeatureReplay {
    history: history::PublicHistory,
}
#[pymethods]
impl FeatureReplay {
    #[new]
    fn new() -> Self {
        Self {
            history: history::PublicHistory::new(),
        }
    }
    fn apply(&mut self, events: &str) -> PyResult<()> {
        let events: Vec<serde_json::Value> = serde_json::from_str(events)
            .map_err(|e| pyo3::exceptions::PyValueError::new_err(e.to_string()))?;
        for event in events {
            self.history.apply(&event);
            if event["type"] == "tsumo" {
                if let Some(left) = event["tiles_left"].as_i64() {
                    self.history.live_wall = left as i32;
                }
            }
        }
        Ok(())
    }
    #[pyo3(signature=(actor,phase,east_only=false))]
    fn pack<'py>(
        &mut self,
        py: Python<'py>,
        actor: usize,
        phase: u8,
        east_only: bool,
    ) -> PyResult<Bound<'py, PyDict>> {
        let row = py.detach(|| {
            let obs = self.history.legal_observation(actor);
            let mut row = Row::new();
            features::pack(
                &mut row,
                &mut self.history,
                &obs,
                actor,
                phase,
                east_only,
            );
            row
        });
        columns(py, &[&row])
    }
}
#[pymodule]
fn _native_collection(m: &Bound<'_, PyModule>) -> PyResult<()> {
    let inputs = PyDict::new(m.py());
    for field in FIELDS {
        let spec = PyDict::new(m.py());
        spec.set_item("shape", field.shape.to_vec())?;
        spec.set_item("dtype", field.dtype.name())?;
        inputs.set_item(field.name, spec)?;
    }
    m.add("INPUTS", inputs)?;
    m.add_function(wrap_pyfunction!(scoring::score_hand, m)?)?;
    m.add_class::<FeatureReplay>()?;
    m.add_class::<collector::NativeCollector>()?;
    m.add_class::<collector::NativeRoot>()?;
    Ok(())
}

"""Create a fixed player-game selection from original Tenhou databases."""

import collections
import gzip
import hashlib
import json
import pathlib
import re
import sqlite3
import urllib.parse
import xml.etree.ElementTree
import zipfile

SAMPLING = {
    "unit": "game_id_seat",
    "rank": "historical_tenhou_dan",
    "rates": {"7": 0.5, "8": 0.75, "9+": 1.0},
    "allocation": "floor_per_year_rank_sha256_order",
    "seed": "nejimakidori-player-ranks-20260921",
    "unverified": "exclude",
}


def select(rows):
    strata = collections.defaultdict(list)
    for row in rows:
        row["seats"] = []
        for seat, dan in enumerate(row["dan"]):
            if dan is not None and dan >= 7:
                strata[(row["game_id"][:4], min(dan, 9))].append((row, seat))
    for (_, dan), players in strata.items():
        players.sort(
            key=lambda player: hashlib.sha256(
                f"{SAMPLING['seed']}:{player[0]['game_id']}:{player[1]}".encode()
            ).digest()
        )
        rate = SAMPLING["rates"][str(dan) if dan < 9 else "9+"]
        for row, seat in players[: int(len(players) * rate)]:
            row["seats"].append(seat)
    for row in rows:
        row["seats"].sort()


def run(archives, databases, output):
    if (pathlib.Path(archives) / "player_ranks.json").exists():
        raise ValueError("archives already stratified")
    root = pathlib.Path(output)
    # An existing selection is never overwritten or sampled again.
    root.mkdir(parents=True, exist_ok=False)
    rows = []
    summary = {"sampling": SAMPLING, "years": {}}
    for path in sorted(pathlib.Path(archives).glob("*.zip")):
        database = pathlib.Path(databases) / f"{path.stem}.db"
        with path.open("rb") as stream, database.open("rb") as db_stream:
            year = {
                "archive_sha256": hashlib.file_digest(
                    stream, "sha256"
                ).hexdigest(),
                "database_sha256": hashlib.file_digest(
                    db_stream, "sha256"
                ).hexdigest(),
                "database": str(database.resolve()),
            }
        with zipfile.ZipFile(path) as archive:
            members = {
                pathlib.Path(member).stem: member
                for member in archive.namelist()
                if member.endswith(".mjson")
            }
            year["games"] = len(members)
            matched = set()
            connection = sqlite3.connect(
                f"file:{database.resolve()}?mode=ro", uri=True
            )
            try:
                for game_id, payload in connection.execute(
                    "SELECT id, log FROM logs WHERE log IS NOT NULL"
                ):
                    if game_id not in members:
                        continue
                    player = xml.etree.ElementTree.fromstring(
                        re.search(
                            rb"<UN\s[^>]+/>", gzip.decompress(payload)
                        ).group()
                    ).attrib
                    names = [
                        urllib.parse.unquote(player[f"n{seat}"])
                        for seat in range(4)
                    ]
                    raw = archive.read(members[game_id])
                    if raw.startswith(b"\x1f\x8b"):
                        raw = gzip.decompress(raw)
                    start = json.loads(raw.split(b"\n", 1)[0])
                    if names != start["names"]:
                        raise ValueError(f"seat names mismatch: {game_id}")
                    ranks = list(map(int, player["dan"].split(",")))
                    if len(ranks) != 4 or any(
                        rank < 0 or rank > 20 for rank in ranks
                    ):
                        raise ValueError(f"invalid ranks: {game_id} {ranks}")
                    rows.append(
                        {
                            "game_id": game_id,
                            # Tenhou codes 10..19 = 1..10 dan; 20 = Tenhoui.
                            "dan": [rank - 9 for rank in ranks],
                            "rating": list(
                                map(float, player["rate"].split(","))
                            ),
                        }
                    )
                    matched.add(game_id)
            finally:
                connection.close()
            year["verified_games"] = len(matched)
            year["missing_games"] = len(members) - len(matched)
            rows.extend(
                {"game_id": game_id, "dan": [], "rating": []}
                for game_id in sorted(members.keys() - matched)
            )
        summary["years"][path.stem] = year
        print(json.dumps({path.stem: year}), flush=True)
    select(rows)
    for year, counts in summary["years"].items():
        games = [row for row in rows if row["game_id"].startswith(year)]
        counts["retained_games"] = sum(bool(row["seats"]) for row in games)
        counts["rank_counts"] = dict(
            collections.Counter(dan for row in games for dan in row["dan"])
        )
        counts["retained_rank_counts"] = dict(
            collections.Counter(
                row["dan"][seat] for row in games for seat in row["seats"]
            )
        )
    lookup = {row["game_id"]: row for row in rows}
    for path in sorted(pathlib.Path(archives).glob("*.zip")):
        with zipfile.ZipFile(path) as source, zipfile.ZipFile(
            root / path.name,
            "w",
            compression=zipfile.ZIP_DEFLATED,
            compresslevel=1,
        ) as target:
            for member in source.namelist():
                raw = source.read(member)
                if raw.startswith(b"\x1f\x8b"):
                    raw = gzip.decompress(raw)
                first, rest = raw.split(b"\n", 1)
                start = json.loads(first)
                if "player_ranks" in start:
                    raise ValueError(f"already stratified: {path} {member}")
                row = lookup[pathlib.Path(member).stem]
                start["player_ranks"] = {
                    "dan": row["dan"],
                    "rating": row["rating"],
                    "retained_seats": row["seats"],
                }
                target.writestr(
                    member,
                    json.dumps(start, ensure_ascii=False).encode()
                    + b"\n"
                    + rest,
                )
        with (root / path.name).open("rb") as stream:
            summary["years"][path.stem]["merged_sha256"] = hashlib.file_digest(
                stream, "sha256"
            ).hexdigest()
    (root / "player_ranks.json").write_text(json.dumps(summary, indent=2))
    return summary

"""Single numeric TFRecord contract for training and inference."""

import hashlib
import json
import math
import pathlib

import numpy

from log_dataset import _native_collection

LABELS = {
    "ron_payments": {"shape": [3, 37], "dtype": "int32"},
    "ron_legal": {"shape": [3, 37], "dtype": "int8"},
    "win_action": {"shape": [], "dtype": "int8"},
    "candidate_yaku_affinity": {"shape": [96, 3], "dtype": "float16"},
    "opponent_shanten": {"shape": [3], "dtype": "int8"},
    "opponent_ukeire": {"shape": [3, 34], "dtype": "int8"},
    "opponent_hand_counts": {"shape": [3, 37], "dtype": "int8"},
    "terminal_payment": {"shape": [4, 4, 4], "dtype": "int32"},
    "round_completion_yaku": {"shape": [4, 2, 23], "dtype": "int8"},
    "round_completion_score": {"shape": [4, 2], "dtype": "int16"},
    "discard_action": {"shape": [], "dtype": "int8"},
    "continuation_discard": {"shape": [], "dtype": "int8"},
    "riichi_action": {"shape": [], "dtype": "int8"},
    "response_action": {"shape": [], "dtype": "int8"},
    "chi_pattern": {"shape": [], "dtype": "int8"},
    "kan_action": {"shape": [], "dtype": "int8"},
}


PACKING = {
    "feature/last_tedashi_tile": (1, 0),
    "feature/river_pre_tsumogiri": (1, 0),
    "feature/river_pre_tedashi_relation": (2, 0),
    "feature/river_pre_tedashi_gap": (5, 0),
    "feature/river_pre_current_dora_multiplicity": (3, 0),
    "feature/river_pre_dora_multiplicity_at_discard": (3, 0),
    "feature/river_post_tsumogiri": (1, 0),
    "feature/river_post_tedashi_relation": (2, 0),
    "feature/river_post_tedashi_gap": (5, 0),
    "feature/river_post_current_dora_multiplicity": (3, 0),
    "feature/river_post_dora_multiplicity_at_discard": (3, 0),
    "feature/self_yaku_possibility": (1, 0),
    "feature/open_opponent_yaku_possibility": (1, 0),
    "feature/opponent_called_tile_count": (5, 0),
    "feature/opponent_discard_count": (6, 0),
    "feature/riichi_push_count": (7, 0),
    "feature/genbutsu_to_seat": (1, 0),
    "feature/passed_unchanged_to_seat": (1, 0),
    "feature/blocker_counts": (2, 0),
    "feature/sotogawa_earliest_turn_to_seat": (3, 0),
    "feature/chi_call_yaku_possibility": (1, 0),
    "feature/pon_call_yaku_possibility": (1, 0),
    "feature/kan_yaku_possibility": (1, 0),
    "feature/discard_action_yaku_possibility": (1, 0),
    "label/opponent_ukeire": (2, 1),
    "label/round_completion_yaku": (2, 1),
}

FIELDS = {
    prefix + "/" + name: definition
    for prefix, fields in (
        ("feature", _native_collection.INPUTS),
        ("label", LABELS),
    )
    for name, definition in fields.items()
}


def game_partition(game_id):
    """Keep original games in the same corpus and rollout holdout bucket."""
    return int.from_bytes(hashlib.sha256(game_id.encode()).digest()[:4]) % 10


def encode(name, value):
    value = numpy.asarray(value)
    if name in PACKING:
        width, offset = PACKING[name]
        values = value.reshape(-1).astype(numpy.int64) + offset
        bits = ((values[:, None] >> numpy.arange(width)) & 1).reshape(-1)
        raw = numpy.packbits(
            bits.astype(numpy.uint8), bitorder="little"
        ).tobytes()
    else:
        raw = value.tobytes()
    return raw.rstrip(b"\0")


def serialize_observation(observation):
    import tensorflow as tf

    example = tf.train.Example()
    for prefix, values, definitions in (
        ("feature", observation.features, _native_collection.INPUTS),
        ("label", vars(observation), LABELS),
    ):
        for name, definition in definitions.items():
            example.features.feature[
                prefix + "/" + name
            ].bytes_list.value.append(
                encode(
                    prefix + "/" + name,
                    numpy.asarray(
                        values[name], dtype=definition["dtype"]
                    ).reshape(definition["shape"]),
                )
            )
    for name in ("game_id", "kyoku_id"):
        example.features.feature["meta/" + name].bytes_list.value.append(
            getattr(observation, name).encode()
        )
    for name in ("decision_index", "actor"):
        example.features.feature["meta/" + name].int64_list.value.append(
            int(getattr(observation, name))
        )
    return example.SerializeToString()


def parse_batch(examples):
    import tensorflow as tf

    parsed = tf.io.parse_example(
        examples,
        {name: tf.io.FixedLenFeature([], tf.string) for name in FIELDS},
    )
    return decode_batch(parsed)


def decode_batch(parsed):
    """Decode shared numeric fields from one parsed Example batch."""
    import tensorflow as tf

    decoded = {}
    for name, definition in FIELDS.items():
        size = math.prod(definition["shape"])
        dtype = tf.as_dtype(definition["dtype"])
        if name in PACKING:
            width, offset = PACKING[name]
            bit = numpy.arange(size) * width
            raw = tf.io.decode_raw(
                parsed[name], tf.uint8, fixed_length=(size * width + 7) // 8
            )
            if 8 % width == 0:
                words = tf.gather(raw, bit // 8, axis=1)
            else:
                # Read at most two bytes per value, including crossings.
                raw = tf.pad(tf.cast(raw, tf.uint16), [[0, 0], [0, 1]])
                words = tf.bitwise.bitwise_or(
                    tf.gather(raw, bit // 8, axis=1),
                    tf.bitwise.left_shift(
                        tf.gather(raw, bit // 8 + 1, axis=1), 8
                    ),
                )
            values = (
                tf.cast(
                    tf.bitwise.bitwise_and(
                        tf.bitwise.right_shift(
                            words, tf.constant(bit % 8, words.dtype)
                        ),
                        (1 << width) - 1,
                    ),
                    tf.int32,
                )
                - offset
            )
            values = tf.cast(values, dtype)
        else:
            values = tf.io.decode_raw(
                parsed[name],
                tf.uint16 if dtype == tf.float16 else dtype,
                fixed_length=size * dtype.size,
            )
            if dtype == tf.float16:
                values = tf.bitcast(values, tf.float16)
        decoded[name] = tf.reshape(values, [-1, *definition["shape"]])
    inputs = {
        name: decoded["feature/" + name] for name in _native_collection.INPUTS
    }
    labels = {name: decoded["label/" + name] for name in LABELS}
    labels.update(
        {
            "win_decision_logits": labels["win_action"],
            "discard_policy_logits": labels["discard_action"],
            "riichi_policy_logits": tf.where(
                labels["riichi_action"] >= 0,
                tf.cast(labels["riichi_action"], tf.int32) * 37
                + tf.cast(labels["continuation_discard"], tf.int32),
                -1,
            ),
            "response_policy_logits": tf.where(
                labels["response_action"] == 0,
                0,
                tf.where(
                    labels["response_action"] == 1,
                    1
                    + tf.cast(labels["chi_pattern"], tf.int32) * 37
                    + tf.cast(labels["continuation_discard"], tf.int32),
                    tf.where(
                        labels["response_action"] == 2,
                        112 + tf.cast(labels["continuation_discard"], tf.int32),
                        tf.where(labels["response_action"] == 3, 149, -1),
                    ),
                ),
            ),
            "kan_action_logits": labels["kan_action"],
        }
    )
    return inputs, labels


def validate_summary(data):
    summary = json.loads(
        (pathlib.Path(data) / "dataset_summary.json").read_text()
    )
    for name, expected in {
        "input_schema": _native_collection.INPUTS,
        "label_schema": LABELS,
    }.items():
        if name not in summary or summary[name] != expected:
            raise ValueError(f"dataset {name} requires regeneration")

"""Incremental MJAI state and ordered decision-time training observations."""

import dataclasses
import inspect
import json

import numpy
import riichienv

from log_dataset import records, shanten
from model import actions

CALL_TYPES = {"chi", "pon", "daiminkan"}
OBSERVATION_FIELDS = tuple(
    name
    for name in inspect.signature(riichienv.Observation).parameters
    if name not in {"legal_actions", "hands", "drawn_tile"}
)

Observation = dataclasses.make_dataclass(
    "Observation",
    [
        (name, object, dataclasses.field(default=None))
        for name in (
            "game_id",
            "kyoku_id",
            "decision_index",
            "actor",
            "features",
            *records.LABELS,
        )
    ],
)


def recorded_win_choices(state, index, next_index):
    event = state.events[index]
    if event["type"] not in {"tsumo", "dahai", "kakan", "ankan"}:
        return {}
    while next_index < len(state.events) and state.events[next_index][
        "type"
    ] in {"dora", "reach_accepted"}:
        next_index += 1
    if next_index == len(state.events):
        return {}
    winners = {}
    end = next_index
    while end < len(state.events) and state.events[end]["type"] == "hora":
        winners[state.events[end]["actor"]] = end
        end += 1
    if not winners and state.events[next_index]["type"] not in {
        "tsumo",
        "dahai",
        "reach",
        "chi",
        "pon",
        "daiminkan",
        "ankan",
        "kakan",
    }:
        return {}
    choices = {}
    for actor in ((event["actor"],) if event["type"] == "tsumo" else range(4)):
        if not any(
            action.action_type in actions.WIN_ACTIONS
            for action in state.legal_observation(actor).legal_actions()
        ):
            continue
        if actor in winners:
            choices[actor] = (1, winners[actor])
        elif not winners:
            choices[actor] = (0, index)
    return choices


class Replay:
    def __init__(self, game_id, events):
        self.game_id = game_id
        self.events = events
        self.native_env = riichienv.RiichiEnv(
            rule=riichienv.GameRule.default_tenhou()
        )
        self.history = []
        self.event_index = -1
        self.decision_index = 0
        self.pending_discard = None
        self.observation_cache = {}
        self.feature_replay = None
        self.feature_cursor = 0

    @classmethod
    def from_start(cls, game_id, event):
        state = cls(game_id, [])
        state.apply(event)
        return state

    @property
    def melds(self):
        return self.native_env.melds

    def public_tiles(self):
        return (
            list(self.dora_markers)
            + [row["pai"] for river in self.rivers for row in river]
            + [
                tile
                for melds in self.meld_events
                for meld in melds
                for tile in meld["consumed"]
            ]
            + [
                meld["upgrade_tile"]
                for melds in self.meld_events
                for meld in melds
                if meld["type"] == "kakan"
            ]
        )

    def concealed_counts(self, actor):
        return numpy.bincount(
            [tile // 4 for tile in self.native_env.hands[actor] if tile < 136],
            minlength=34,
        )

    def missed_agari(self, actor):
        if self.native_env.missed_agari_doujun[actor]:
            return True
        waits = riichienv.HandEvaluator(
            self.native_env.hands[actor], self.melds[actor]
        ).get_waits()
        for index in range(len(self.history) - 1, -1, -1):
            event = self.history[index]
            if event.get("actor") == actor and (
                event["type"] == "reach_accepted"
                or (
                    not self.accepted[actor]
                    and event["type"]
                    in {"tsumo", "chi", "pon", "daiminkan", "ankan", "kakan"}
                )
            ):
                break
            if (
                event["type"] == "dahai"
                and event["actor"] != actor
                and (
                    self.pending_discard is None
                    or index != self.pending_discard["event_index"]
                )
                and shanten.base_id(event["pai"]) in waits
            ):
                return True
        return False

    def legal_observation(self, actor):
        from log_dataset import features

        if actor in self.observation_cache:
            return self.observation_cache[actor]
        original = self.native_env.get_observation(actor)
        hand = []
        for tile in original.hand:
            physical = tile // 4 * 4
            if tile not in (16, 52, 88) and physical in (16, 52, 88):
                physical += 1
            while physical in hand:
                physical += 1
            hand.append(physical)
        drawn = None
        if self.draws[actor] is not None and self.draws[actor] != "?":
            code = shanten.mjai_tile_code(self.draws[actor])
            drawn = next(
                tile
                for tile in reversed(hand)
                if features.native_tile_code(tile) == code
            )
        legal = []
        for action in original.legal_actions():
            if action.action_type == riichienv.ActionType.DISCARD:
                for tile in hand:
                    if features.native_tile_code(
                        tile
                    ) == features.native_tile_code(action.tile):
                        if self.accepted[actor] and tile != drawn:
                            continue
                        if not any(
                            item.action_type == action.action_type
                            and item.tile == tile
                            for item in legal
                        ):
                            legal.append(
                                riichienv.Action(
                                    type=action.action_type,
                                    tile=tile,
                                    actor=actor,
                                )
                            )
            else:
                legal.append(action)
        values = {name: getattr(original, name) for name in OBSERVATION_FIELDS}
        values.update(
            hands=[
                hand if seat == actor else original.hands[seat]
                for seat in range(4)
            ],
            legal_actions=legal,
            drawn_tile=drawn,
        )
        values["events"] = [json.dumps(event) for event in original.events]
        self.observation_cache[actor] = riichienv.Observation(**values)
        return self.observation_cache[actor]

    def apply(self, event):
        self.observation_cache.clear()
        self.event_index += 1
        self.history.append(event)
        kind = event["type"]
        if kind == "start_kyoku":
            self.start = event
            self.kyoku_id = (
                f"{event['bakaze']}{event['kyoku']}-{event['honba']}"
            )
            self.history = [event]
            self.feature_replay = None
            self.feature_cursor = 0
            self.rivers = [[] for _ in range(4)]
            self.meld_events = [[] for _ in range(4)]
            self.declared = [False] * 4
            self.accepted = [False] * 4
            self.ippatsu = [False] * 4
            self.draws = [None] * 4
            self.live_wall = 70
            self.pending_discard = None
            self.last_origin = [0] * 4
            self.rinshan_actor = None
            self.dora_markers = [event["dora_marker"]]
        elif kind == "tsumo":
            self.live_wall -= 1
            self.draws[event["actor"]] = event["pai"]
            self.last_origin[event["actor"]] = 1
            if self.pending_discard:
                self.pending_discard["resolution"] = 1
            self.pending_discard = None
        elif kind == "dahai":
            actor = event["actor"]
            if self.pending_discard:
                self.pending_discard["resolution"] = 1
            record = {
                **event,
                "event_index": len(self.history) - 1,
                "live_wall": self.live_wall,
                "own_turns": [len(river) for river in self.rivers],
                "origin": self.last_origin[actor],
                "riichi": self.declared[actor] and not self.accepted[actor],
                "resolution": 0,
                "caller": None,
                "dora_markers": list(self.dora_markers),
            }
            self.rivers[actor].append(record)
            self.pending_discard = record
            self.draws[actor] = None
            self.rinshan_actor = None
            if self.accepted[actor]:
                self.ippatsu[actor] = False
        elif kind == "reach":
            self.declared[event["actor"]] = True
        elif kind == "reach_accepted":
            self.accepted[event["actor"]] = True
            self.ippatsu[event["actor"]] = True
        elif kind in CALL_TYPES | {"ankan", "kakan"}:
            self.ippatsu = [False] * 4
            if self.pending_discard and kind in CALL_TYPES:
                self.pending_discard["resolution"] = {
                    "chi": 2,
                    "pon": 3,
                    "daiminkan": 4,
                }[kind]
                self.pending_discard["caller"] = event["actor"]
            self.pending_discard = None
            self.draws[event["actor"]] = None
            self.last_origin[event["actor"]] = kind
            if kind in {"ankan", "kakan", "daiminkan"}:
                self.rinshan_actor = event["actor"]
            if kind == "kakan":
                for meld in self.meld_events[event["actor"]]:
                    if meld["type"] == "pon" and shanten.base_id(
                        meld["pai"]
                    ) == shanten.base_id(event["pai"]):
                        meld["upgrade_index"] = len(self.history) - 1
                        meld["upgrade_tile"] = event["pai"]
                        meld["type"] = "kakan"
            else:
                self.meld_events[event["actor"]].append(
                    {**event, "event_index": len(self.history) - 1}
                )
        elif kind == "dora":
            self.dora_markers.append(event["dora_marker"])
        self.native_env.apply_event(event)
        if kind == "tsumo":
            self.native_env.is_rinshan_flag = (
                self.rinshan_actor == event["actor"]
            )
        elif kind == "dahai":
            self.native_env.is_rinshan_flag = False

    def replay_events(self):
        index = 0
        while index < len(self.events):
            event = self.events[index]
            self.apply(event)
            if event["type"] == "tsumo":
                while self.events[index + 1]["type"] == "dora":
                    index += 1
                    self.apply(self.events[index])
            self.event_index = index
            yield index, event
            index += 1

    def decisions(self):
        from log_dataset import features

        for index, event in self.replay_events():
            requests = []
            next_index = index + 1
            while (
                next_index < len(self.events)
                and self.events[next_index]["type"] == "reach_accepted"
            ):
                next_index += 1
            win_choices = (
                recorded_win_choices(self, index, next_index)
                if next_index < len(self.events)
                else {}
            )
            requests.extend((actor, "WIN") for actor in win_choices)
            if event["type"] in {
                "tsumo",
                "chi",
                "pon",
                "reach",
            } and self.events[next_index]["type"] not in {"hora", "ryukyoku"}:
                actor = event["actor"]
                legal = self.legal_observation(actor).legal_actions()
                types = {action.action_type for action in legal}
                if (
                    riichienv.ActionType.ANKAN in types
                    or riichienv.ActionType.KAKAN in types
                ):
                    requests.append((actor, "KAN"))
                    if self.events[next_index]["type"] in {"ankan", "kakan"}:
                        types = set()
                if riichienv.ActionType.RIICHI in types:
                    requests.append((actor, "RIICHI"))
                    if self.events[next_index]["type"] != "reach":
                        requests.append((actor, "DISCARD"))
                elif riichienv.ActionType.DISCARD in types:
                    requests.append((actor, "DISCARD"))
            elif (
                event["type"] == "dahai"
                and self.events[next_index]["type"] != "hora"
            ):
                # Other seats' intentions are censored by an accepted
                # call; a losing claim must not be labeled as a pass.
                for actor in (
                    (self.events[next_index]["actor"],)
                    if self.events[next_index]["type"] in CALL_TYPES
                    else range(4)
                ):
                    legal = self.legal_observation(actor).legal_actions()
                    if any(
                        action.action_type
                        in {
                            riichienv.ActionType.CHI,
                            riichienv.ActionType.PON,
                            riichienv.ActionType.DAIMINKAN,
                        }
                        for action in legal
                    ):
                        requests.append((actor, "RESPONSE"))
            for actor, phase in requests:
                next_event = self.events[next_index]
                if (
                    phase == "RESPONSE"
                    and next_event["type"] in {"chi", "pon"}
                    and next_event["actor"] == actor
                    and not features.preferred_recorded_call(
                        next_event["type"],
                        next_event["consumed"],
                        self.legal_observation(actor).legal_actions(),
                    )
                ):
                    continue
                yield index, actor, phase, next_index, win_choices
                self.decision_index += 1

    def policy_decisions(self):
        """Replay policy choices without computing features or labels."""
        from log_dataset import features
        from model import actions

        for index, actor, phase, next_index, win_choices in self.decisions():
            legal_observation = self.legal_observation(actor)
            if (
                actions.forced_policy_action(
                    self, actor, legal_observation.legal_actions()
                )
                is not None
            ):
                continue
            if (
                phase == "DISCARD"
                and features.single_legal_action(
                    [
                        action
                        for action in legal_observation.legal_actions()
                        if action.action_type == riichienv.ActionType.DISCARD
                    ],
                    legal_observation.drawn_tile,
                )
                is not None
            ):
                continue
            yield index, actor, phase, next_index, win_choices

    def recorded_action(self, observation, *, phase, next_index, win_choices):
        """Attach the observed action without computing hindsight targets."""
        from log_dataset import features

        actor = observation.actor
        next_event = self.events[next_index]
        if phase == "WIN":
            observation.win_action = win_choices[actor][0]
        elif phase == "DISCARD" and next_event["type"] == "dahai":
            if (
                not self.accepted[actor]
                and observation.features["discard_action_legal"].sum() > 1
            ):
                observation.discard_action = shanten.mjai_tile_code(
                    next_event["pai"]
                )
        elif phase == "RIICHI":
            declaration = next_event["type"] == "reach"
            cut = self.events[next_index + 1] if declaration else next_event
            observation.riichi_action = int(declaration)
            observation.continuation_discard = shanten.mjai_tile_code(
                cut["pai"]
            )
        elif phase == "RESPONSE":
            observation.response_action = 0
            if (
                next_event["type"] in CALL_TYPES
                and next_event["actor"] == actor
            ):
                observation.response_action = {
                    "chi": 1,
                    "pon": 2,
                    "daiminkan": 3,
                }[next_event["type"]]
                if next_event["type"] == "chi":
                    observation.chi_pattern = features.chii_pattern(
                        next_event["pai"], next_event["consumed"]
                    )
                if next_event["type"] != "daiminkan":
                    observation.continuation_discard = shanten.mjai_tile_code(
                        self.events[next_index + 1]["pai"]
                    )
        elif phase == "KAN":
            observation.kan_action = 0
            if next_event["type"] in {"ankan", "kakan"}:
                observation.kan_action = 1 + shanten.base_id(
                    next_event["consumed"][0]
                    if next_event["type"] == "ankan"
                    else next_event["pai"]
                )

    def observations(self, feature_provider=None, *, actors=(0, 1, 2, 3)):
        from log_dataset import features, training_targets

        if feature_provider is None:
            feature_provider = features.pack
        self.targets = training_targets.round_targets(
            Replay.from_start(self.game_id, self.events[0]), self.events
        )
        for (
            index,
            actor,
            phase,
            next_index,
            win_choices,
        ) in self.policy_decisions():
            if actor not in actors:
                continue
            packed = feature_provider(state=self, actor=actor, phase=phase)
            observation = Observation(
                game_id=self.game_id,
                kyoku_id=self.kyoku_id,
                decision_index=self.decision_index,
                actor=actor,
                features=packed,
            )
            for name, definition in records.LABELS.items():
                setattr(
                    observation,
                    name,
                    numpy.full(definition["shape"], -1, definition["dtype"]),
                )
            self.recorded_action(
                observation=observation,
                phase=phase,
                next_index=next_index,
                win_choices=win_choices,
            )
            training_targets.attach(observation, self, index)
            for name, value in training_targets.ron_labels(
                self, actor, phase
            ).items():
                setattr(observation, name, value)
            yield observation

"""Read cached browser rounds as MJAI events and decision-time state."""

from log_dataset import replay


def tile_name(tile):
    if tile == "?":
        return tile
    if not isinstance(tile, str) or len(tile) != 2 or tile[1] not in "mpsz":
        raise ValueError("Invalid tile: " + str(tile))
    if tile[1] == "z":
        return ("E", "S", "W", "N", "P", "F", "C")[int(tile[0]) - 1]
    return "5" + tile[1] + "r" if tile[0] == "0" else tile


def round_events(round_data):
    if len(round_data["hands"]) != 4 or len(round_data["scores"]) != 4:
        raise ValueError("A round requires four players.")
    if not 1 <= round_data["kyoku"] <= 4:
        raise ValueError("Invalid round number.")
    events = [
        {
            "type": "start_kyoku",
            "bakaze": ("E", "S", "W", "N")[round_data["prevailingWind"]],
            "kyoku": round_data["kyoku"],
            "honba": round_data["honba"],
            "kyotaku": round_data["riichiSticks"],
            "oya": round_data["kyoku"] - 1,
            "scores": round_data["scores"],
            "dora_marker": tile_name(round_data["doraIndicators"][0]),
            "tehais": [
                [tile_name(tile) for tile in hand]
                for hand in round_data["hands"]
            ],
        }
    ]
    cursors = []
    dora_count = len(round_data["doraIndicators"])
    accepted = set()
    last_discard = None
    for event in round_data["events"]:
        if event.get("liqi") and event["liqi"]["seat"] not in accepted:
            events.append(
                {"type": "reach_accepted", "actor": event["liqi"]["seat"]}
            )
            accepted.add(event["liqi"]["seat"])
        cursors.append(len(events))
        if event["type"] == "draw":
            events.append(
                {
                    "type": "tsumo",
                    "actor": event["seat"],
                    "pai": tile_name(event["tile"]),
                }
            )
        elif event["type"] == "discard":
            if event["riichi"]:
                events.append({"type": "reach", "actor": event["seat"]})
            last_discard = event["seat"]
            events.append(
                {
                    "type": "dahai",
                    "actor": event["seat"],
                    "pai": tile_name(event["tile"]),
                    "tsumogiri": event["tsumogiri"],
                }
            )
        elif event["type"] == "call":
            called = next(
                index
                for index, seat in enumerate(event["froms"])
                if seat != event["seat"]
            )
            events.append(
                {
                    "type": (
                        "chi"
                        if event["callType"] == "chii"
                        else event["callType"]
                    ),
                    "actor": event["seat"],
                    "target": event["froms"][called],
                    "pai": tile_name(event["tiles"][called]),
                    "consumed": [
                        tile_name(tile)
                        for index, tile in enumerate(event["tiles"])
                        if index != called
                    ],
                }
            )
        elif event["type"] == "kan":
            last_discard = event["seat"]
            converted = {
                "type": event["callType"],
                "actor": event["seat"],
                "consumed": [tile_name(tile) for tile in event["tiles"]],
            }
            if event["callType"] == "kakan":
                converted["pai"] = converted["consumed"].pop()
            events.append(converted)
        elif event["type"] == "agari":
            for index, winner in enumerate(event["hules"]):
                events.append(
                    {
                        "type": "hora",
                        "actor": winner["seat"],
                        "target": (
                            winner["seat"] if winner["zimo"] else last_discard
                        ),
                        "deltas": event["deltas"] if index == 0 else [0] * 4,
                    }
                )
        elif event["type"] == "ryuukyoku":
            events.append({"type": "ryukyoku", "deltas": event["deltas"]})
        else:
            raise ValueError("Unsupported round event: " + event["type"])
        for tile in event.get("doras", [])[dora_count:]:
            events.append({"type": "dora", "dora_marker": tile_name(tile)})
            dora_count += 1
    return events, cursors


def reconstruct(round_data, cursor):
    try:
        events, cursors = round_events(round_data)
    except (KeyError, TypeError, IndexError, StopIteration) as error:
        raise ValueError("Invalid round structure: " + str(error)) from error
    if type(cursor) is not int or not 0 <= cursor <= len(cursors):
        raise ValueError("Event cursor is outside this hand.")
    state = replay.Replay.from_start("browser", events[0])
    stop = cursors[cursor] if cursor < len(cursors) else len(events)
    for event in events[1:stop]:
        state.apply(event)
    return state, events

"""Own-hand witnesses for fixed-continuation discard-order comparisons."""

import types

import numpy
import riichienv

from log_dataset import _native_collection, features, replay, scoring, shanten


def preserves_completion(steps, final_counts, late_cut):
    """Can the first discard and final discard exchange their order?

    Steps contain physical-code counts before each own discard,
    its cut, legal cuts and resulting shanten. final_counts is the hand
    before the last discard. The caller excludes intervening calls/kans
    and accepted own riichi, and checks endpoint ron exposures and legal
    live winning opportunities. Counts come from valid recorded hands.

    Require a continuously retained unique late tile and no worse
    intermediate shanten. The final concealed
    hand is identical. This does not predict opponents' responses or
    assert that the recorded draws survive the changed earlier discard.
    """
    packed = numpy.array(
        [[*step["counts"], step["cut"], step["distance"]] for step in steps],
        dtype=numpy.int8,
    )
    return shanten.native().nyanten_preserves_completion(
        packed.ctypes.data,
        len(steps),
        bytes(map(int, final_counts)),
        late_cut,
        sum(1 << int(code) for code in set(steps[0]["legal"])),
    )


def ron_exposure(state, actor, codes):
    """Binary legal ron evidence, independent of payment magnitude."""
    result = dict.fromkeys(codes, 0)
    for opponent in range(4):
        if opponent == actor:
            continue
        hand = state.legal_observation(opponent).hand
        if len(hand) % 3 != 1:
            continue
        waits = riichienv.HandEvaluator(hand, state.melds[opponent]).get_waits()
        if state.missed_agari(opponent) or set(waits) & {
            shanten.base_id(row["pai"]) for row in state.rivers[opponent]
        }:
            continue
        for code in codes:
            base = shanten.base_id(code)
            if base not in waits:
                continue
            physical = next(
                tile
                for tile in range(base * 4, base * 4 + 4)
                if tile not in hand
            )
            result[code] += int(
                _native_collection.score_hand(
                    types.SimpleNamespace(
                        tiles=hand + [physical],
                        melds=state.melds[opponent],
                        agari_tile=physical,
                        dora_indicators=[],
                    ),
                    conditions=riichienv.Conditions(
                        riichi=state.accepted[opponent],
                        houtei=state.live_wall == 0,
                        player_wind=(
                            riichienv.Wind.East,
                            riichienv.Wind.South,
                            riichienv.Wind.West,
                            riichienv.Wind.North,
                        )[(opponent - state.start["oya"]) % 4],
                        round_wind="ESWN".index(state.start["bakaze"]),
                    ),
                    ura=[],
                ).is_win
            )
    return result


def verified_exchange(game_id, events, actor, early, late):
    """Replay both orders: legal, safe early, same live winning opportunity."""
    states = [replay.Replay.from_start(game_id, events[0]) for _ in range(2)]
    risks = []
    for index, event in enumerate(events[1 : late + 1], 1):
        for alternate, state in enumerate(states):
            actual = event
            if alternate and index in (early, late):
                code = shanten.mjai_tile_code(
                    events[late if index == early else early]["pai"]
                )
                if code not in {
                    features.native_tile_code(action.tile)
                    for action in state.legal_observation(actor).legal_actions()
                    if action.action_type == riichienv.ActionType.DISCARD
                }:
                    return False
                actual = {
                    **event,
                    "pai": shanten.TILE_NAMES[code],
                    "tsumogiri": False,
                }
            state.apply(actual)
        if index in (early, late):
            risks.append(
                [
                    sum(
                        any(
                            action.action_type == riichienv.ActionType.RON
                            for action in state.native_env.get_observation(
                                opponent
                            ).legal_actions()
                        )
                        for opponent in range(4)
                        if opponent != actor
                    )
                    for state in states
                ]
            )
    if risks[0] != [0, 0] or 3 in risks[1]:
        return False
    if bool(risks[1][0]) == bool(risks[1][1]):
        return False
    for seat in range(4):
        assert sorted(
            features.native_tile_code(tile)
            for tile in states[0].native_env.hands[seat]
        ) == sorted(
            features.native_tile_code(tile)
            for tile in states[1].native_env.hands[seat]
        )
    assert sorted(row["pai"] for row in states[0].rivers[actor]) == sorted(
        row["pai"] for row in states[1].rivers[actor]
    )
    summaries = []
    for state in states:
        hand = state.legal_observation(actor).hand
        visible = state.public_tiles()
        summaries.append(
            scoring.score_waits(
                hand,
                state.melds[actor],
                {
                    "own_discards": [
                        shanten.base_id(row["pai"])
                        for row in state.rivers[actor]
                    ],
                    "missed_agari": state.missed_agari(actor),
                    "unavailable_counts": state.concealed_counts(actor)
                    + numpy.bincount(
                        [shanten.base_id(tile) for tile in visible],
                        minlength=34,
                    ),
                    "unavailable_red": [
                        hand.count(tile) + visible.count(name)
                        for tile, name in zip(
                            (16, 52, 88), ("5mr", "5pr", "5sr")
                        )
                    ],
                    "dora_indicators": state.legal_observation(
                        actor
                    ).dora_indicators,
                    "player_wind": (actor - state.start["oya"]) % 4,
                    "round_wind": "ESWN".index(state.start["bakaze"]),
                },
            )[0]
        )
    scenario = 2 if states[0].declared[actor] else 0
    return bool(
        numpy.array_equal(*summaries)
        and states[0].live_wall > 0
        and summaries[0][scenario : scenario + 2, 1].max() > 0
    )


def round_pairs(game_id, events):
    """Sparse preferred/other early cuts, normalized per first-tenpai event.

    Future hands are labels only. The recorded continuation is conditional
    evidence, not an estimate of counterfactual full-game value.
    """
    state = replay.Replay.from_start(game_id, events[0])
    history = [[] for _ in range(4)]
    seen_ready = [False] * 4
    pairs = {}
    for index, event in enumerate(events[1:], 1):
        if event["type"] in {"chi", "pon", "daiminkan", "ankan", "kakan"}:
            history = [[] for _ in range(4)]
        if event["type"] == "reach_accepted":
            history[event["actor"]] = []
        if event["type"] == "dahai":
            actor = event["actor"]
            cut = shanten.mjai_tile_code(event["pai"])
            native = state.legal_observation(actor)
            counts = numpy.bincount(
                [features.native_tile_code(tile) for tile in native.hand],
                minlength=37,
            )
            after = counts - numpy.eye(37, dtype=int)[cut]
            distance = shanten.calculate_shanten(
                after[:34] + after[34:] @ numpy.eye(34, dtype=int)[[4, 13, 22]]
            )
            first_ready = distance == 0 and not seen_ready[actor]
            seen_ready[actor] |= distance == 0
            if not state.accepted[actor]:
                legal = sorted(
                    {
                        features.native_tile_code(action.tile)
                        for action in native.legal_actions()
                        if action.action_type == riichienv.ActionType.DISCARD
                    }
                )
                danger = ron_exposure(
                    state,
                    actor,
                    sorted(set(legal) | {row["cut"] for row in history[actor]}),
                )
                endpoint = {}
                if first_ready:
                    for earlier_ix, row in enumerate(history[actor]):
                        if (
                            cut not in row["legal"]
                            or row["danger"][cut]
                            or row["danger"][row["cut"]]
                            or 3 in (danger[cut], danger[row["cut"]])
                            or bool(danger[cut]) == bool(danger[row["cut"]])
                            or not preserves_completion(
                                history[actor][earlier_ix:], counts, cut
                            )
                        ):
                            continue
                        if verified_exchange(
                            game_id=game_id,
                            events=events,
                            actor=actor,
                            early=row["index"],
                            late=index,
                        ):
                            endpoint[row["index"]] = (
                                [cut, row["cut"]]
                                if danger[cut]
                                else [row["cut"], cut]
                            )
                    for early, pair in endpoint.items():
                        pairs[early] = (pair, 1 / len(endpoint))
                if not seen_ready[actor]:
                    history[actor].append(
                        {
                            "index": index,
                            "counts": counts,
                            "cut": cut,
                            "legal": legal,
                            "distance": distance,
                            "danger": danger,
                        }
                    )
        state.apply(event)
    return pairs

