def serialize(observation, target):
    example = tf.train.Example.FromString(
        records.serialize_observation(observation)
    )
    example.features.feature["critic/partition"].int64_list.value[:] = [
        records.game_partition(observation.game_id)
    ]
    order = (observation.actor + numpy.arange(4)) % 4
    cells = numpy.asarray(scoring.CELLS[:24])
    numpy.testing.assert_array_equal(
        observation.terminal_payment[:2],
        target["payment"][:2, order][:, :, order],
    )
    for name in AUXILIARY:
        value = target[name][:, order][:, :, order][
            cells[:, 0], cells[:, 1], cells[:, 2]
        ]
        example.features.feature["critic/" + name].bytes_list.value[:] = [
            value.astype("int16").tobytes()
        ]
    return example.SerializeToString()


def parse_batch(raw):
    parsed = tf.io.parse_example(
        raw,
        {
            **{
                name: tf.io.FixedLenFeature([], tf.string)
                for name in records.FIELDS
            },
            "critic/score": tf.io.FixedLenFeature([], tf.string),
            "critic/bonus": tf.io.FixedLenFeature([], tf.string),
        },
    )
    features, labels = records.decode_batch(parsed)
    auxiliary = {
        name: tf.cast(
            tf.reshape(
                tf.io.decode_raw(
                    parsed["critic/" + name],
                    tf.int16,
                ),
                [-1, *shape],
            ),
            tf.int32,
        )
        for name, shape in AUXILIARY.items()
    }
    cells = numpy.asarray(scoring.CELLS)
    payments = tf.gather(
        tf.reshape(labels["terminal_payment"], [-1, 64]),
        numpy.ravel_multi_index(cells.T, (4, 4, 4)),
        axis=1,
    )
    public = joint_settlement.public_inputs(features)
    auxiliary.update(
        {
            **critic.public_inputs(features),
            **public,
            **joint_settlement.payment_labels(payments, public),
        }
    )
    return features, labels, auxiliary


class PackedBatch:
    """Transfer one buffer per dtype, then restore the existing input tree."""

    def __init__(self, inputs):
        self.structure = tf.nest.map_structure(
            lambda value: tf.TensorSpec(value.shape[1:], value.dtype), inputs
        )
        self.specs = tf.nest.flatten(self.structure)
        self.widths = [spec.shape.num_elements() for spec in self.specs]
        self.groups = {
            dtype: [
                index
                for index, spec in enumerate(self.specs)
                if spec.dtype.name == dtype
            ]
            for dtype in sorted({spec.dtype.name for spec in self.specs})
        }

    def pack(self, inputs):
        values = tf.nest.flatten(inputs)
        batch = tf.shape(values[0])[0]
        packed = {}
        for dtype, indices in self.groups.items():
            parts = []
            for index in indices:
                width = self.widths[index]
                value = tf.reshape(values[index], (batch, width))
                if dtype in ("bool", "int8", "int16", "int32"):
                    slots = 4 // self.specs[index].dtype.size
                    if dtype == "bool":
                        value = tf.cast(value, tf.uint8)
                    if slots > 1:
                        value = tf.reshape(
                            tf.pad(value, ((0, 0), (0, (-width) % slots))),
                            (batch, -1, slots),
                        )
                    value = tf.bitcast(value, tf.float32)
                parts.append(value)
            packed[dtype] = tf.concat(parts, axis=1)
        return packed

    def pack_numpy(self, inputs):
        """Pack CPU arrays without constructing a tensor for every field."""
        values = tf.nest.flatten(inputs)
        batch = values[0].shape[0]
        packed = {}
        for dtype, indices in self.groups.items():
            slots = (
                4 // self.specs[indices[0]].dtype.size
                if dtype in ("bool", "int8", "int16", "int32")
                else 1
            )
            widths = [
                (self.widths[index] + slots - 1) // slots for index in indices
            ]
            packed[dtype] = numpy.zeros(
                (batch, sum(widths)),
                (
                    "float32"
                    if dtype in ("bool", "int8", "int16", "int32")
                    else dtype
                ),
            )
            offset = 0
            for index, width in zip(indices, widths):
                packed[dtype][:, offset : offset + width].view(dtype)[
                    :, : self.widths[index]
                ] = values[index].reshape(batch, self.widths[index])
                offset += width
        return packed

    def unpack(self, inputs):
        values = [None] * len(self.specs)
        for dtype, indices in self.groups.items():
            # Narrow integer/bool SplitV kernels run on the host. Transfer
            # bit patterns in float32 buffers so splitting stays on device.
            slots = (
                4 // self.specs[indices[0]].dtype.size
                if dtype in ("bool", "int8", "int16", "int32")
                else 1
            )
            parts = tf.split(
                inputs[dtype],
                [
                    (self.widths[index] + slots - 1) // slots
                    for index in indices
                ],
                axis=1,
            )
            for index, value in zip(indices, parts):
                if dtype in ("bool", "int8", "int16", "int32"):
                    value = tf.bitcast(
                        value, tf.uint8 if dtype == "bool" else dtype
                    )
                    value = tf.reshape(value, (tf.shape(value)[0], -1))
                    # Aligned fields have no padding to trim.
                    if self.widths[index] % slots:
                        value = value[:, : self.widths[index]]
                    if dtype == "bool":
                        value = tf.cast(value, tf.bool)
                values[index] = tf.reshape(
                    value, (-1, *self.specs[index].shape)
                )
        return tf.nest.pack_sequence_as(self.structure, values)


def process_shard(task):
    index, root, games = task
    path = pathlib.Path(root) / f"train-{index:05d}.tfrecord.gz"
    validation_path = pathlib.Path(root) / f"validation-{index:05d}.tfrecord.gz"
    summary_path = path.with_suffix(".json")
    if summary_path.exists():
        summary = json.loads(summary_path.read_text())
        if (
            path.stat().st_size != summary["bytes"]
            or validation_path.stat().st_size != summary["validation_bytes"]
        ):
            raise ValueError(f"Incomplete dataset shard: {path}")
        return summary
    if shutil.disk_usage(root).free < 15 * 1024**3:
        raise OSError("Corpus rebuild requires at least 15 GiB free space")
    validation_count = 0
    counts = numpy.zeros(10, numpy.int64)
    with contextlib.ExitStack() as stack:
        source_archives = {
            path: archives.open_archive(path)
            for path in {game.archive for game in games}
        }
        writer = stack.enter_context(
            tf.io.TFRecordWriter(str(path) + ".partial", options="GZIP")
        )
        validation_writer = stack.enter_context(
            tf.io.TFRecordWriter(
                str(validation_path) + ".partial", options="GZIP"
            )
        )
        for game in games:
            raw = source_archives[game.archive].read(game.member)
            if raw.startswith(b"\x1f\x8b"):
                raw = gzip.decompress(raw)
            events = [json.loads(line) for line in raw.splitlines()]
            seats = events[0]["player_ranks"]["retained_seats"]
            if not seats:
                continue
            targets = scoring.round_labels(events)
            partition = records.game_partition(game.game_id)
            for round_events in afk.retained_hands(events):
                state = replay.Replay(game.game_id, round_events)
                for observation in state.observations(actors=seats):
                    raw = serialize(observation, targets[observation.kyoku_id])
                    writer.write(raw)
                    if partition == VALIDATION_SAMPLE["partition"] and (
                        int.from_bytes(
                            hashlib.sha256(
                                (
                                    f"validation-941:{observation.game_id}:"
                                    f"{observation.kyoku_id}:"
                                    f"{observation.decision_index}:"
                                    f"{observation.actor}"
                                ).encode()
                            ).digest()[:8]
                        )
                        % VALIDATION_SAMPLE["decision_hash_modulus"]
                        == 0
                    ):
                        validation_writer.write(raw)
                        validation_count += 1
                    counts[partition] += 1
    pathlib.Path(str(path) + ".partial").replace(path)
    pathlib.Path(str(validation_path) + ".partial").replace(validation_path)
    summary = {
        "path": path.name,
        "validation_path": validation_path.name,
        "validation_count": validation_count,
        "validation_bytes": validation_path.stat().st_size,
        "games": len(games),
        "counts": counts.tolist(),
        "bytes": path.stat().st_size,
    }
    write_json(summary_path, summary)
    return summary


def dataset(root, partition, batch_size):
    """Read one complete natural partition, retaining its final partial batch."""
    summary = json.loads(
        (pathlib.Path(root) / "dataset_summary.json").read_text()
    )
    assert summary["critic_scoring_states"] == [
        list(s) for s in payment_scoring.SCORES
    ]
    assert summary["critic_auxiliary"] == AUXILIARY
    assert summary["critic_bonus_han"] == list(scoring.BONUS_HAN)
    records.validate_summary(root)
    assert summary["validation_sample"] == VALIDATION_SAMPLE
    paths = [
        str(
            pathlib.Path(root)
            / row["validation_path" if partition == "validation" else "path"]
        )
        for row in summary["shard_manifest"]
    ]
    stream = tf.data.Dataset.from_tensor_slices(paths)
    stream = stream.interleave(
        lambda path: tf.data.TFRecordDataset(path, compression_type="GZIP"),
        cycle_length=min(8, len(paths)),
        block_length=1,
        num_parallel_calls=min(8, len(paths)),
        deterministic=True,
    )

    def select(raw):
        partitions = tf.io.parse_example(
            raw, {"critic/partition": tf.io.FixedLenFeature([], tf.int64)}
        )["critic/partition"]
        selected = partitions < 7 if partition == "train" else partitions == 7
        return tf.boolean_mask(raw, selected)

    stream = stream.batch(1024).map(select, num_parallel_calls=2).unbatch()
    options = tf.data.Options()
    options.threading.private_threadpool_size = 12
    return stream.batch(batch_size).with_options(options).prefetch(2)


def write_json(path, value):
    temporary = path.with_name(path.name + ".partial")
    temporary.write_text(json.dumps(value, indent=2) + "\n")
    temporary.replace(path)


def run(args):
    root = pathlib.Path(args.output)
    root.mkdir(parents=True, exist_ok=True)
    with (root / "build.lock").open("a") as lock:
        fcntl.flock(lock, fcntl.LOCK_EX | fcntl.LOCK_NB)
        games, ranks = archives.games(args.archives, args.extra_archives)
        excluded = {
            row["game_id"]
            for row in json.loads(pathlib.Path(args.reserve).read_text())[
                "games"
            ]
        }
        games = [game for game in games if game.game_id not in excluded]
        if not games:
            raise ValueError(
                "No eligible training games after reserve exclusion"
            )
        if args.limit_games and args.limit_games < len(games):
            games = [
                games[index]
                for index in numpy.linspace(
                    0, len(games) - 1, args.limit_games, dtype=int
                )
            ]
        plan = {
            "archives": str(pathlib.Path(args.archives).resolve()),
            "games": len(games),
            "excluded_reserve_games": sorted(excluded),
            "critic_auxiliary": AUXILIARY,
            "critic_bonus_han": list(scoring.BONUS_HAN),
            "validation_sample": VALIDATION_SAMPLE,
            "critic_scoring_states": [list(s) for s in payment_scoring.SCORES],
            "limit_games": args.limit_games,
            "player_ranks": ranks,
            "input_schema": _native_collection.INPUTS,
            "label_schema": records.LABELS,
        }
        if (root / "build-plan.json").exists():
            if json.loads((root / "build-plan.json").read_text()) != plan:
                raise ValueError("Dataset inputs changed; use a fresh output")
        write_json(root / "build-plan.json", plan)
        (root / "games.jsonl").write_text(
            "".join(
                json.dumps(
                    {
                        "game_id": game.game_id,
                        "archive": str(game.archive),
                        "member": game.member,
                    }
                )
                + "\n"
                for game in games
            )
        )
        tasks = [
            (index, str(root), tuple(games[start : start + 32]))
            for index, start in enumerate(range(0, len(games), 32))
        ]
        shanten.native()
        writer = tf.summary.create_file_writer(str(root / "tensorboard"))
        started = time.monotonic()
        results = []
        with concurrent.futures.ProcessPoolExecutor(
            max_workers=args.workers,
            mp_context=multiprocessing.get_context("spawn"),
        ) as pool:
            for row in pool.map(process_shard, tasks):
                results.append(row)
                status = {
                    "stage": "building",
                    "shards": len(results),
                    "total_shards": len(tasks),
                    "rows": sum(sum(r["counts"]) for r in results),
                    "elapsed_seconds": time.monotonic() - started,
                }
                write_json(root / "status.json", status)
                with writer.as_default():
                    for name in ("shards", "rows", "elapsed_seconds"):
                        tf.summary.scalar(
                            "rebuild/" + name, status[name], step=len(results)
                        )
                writer.flush()
                print(status, flush=True)
        write_json(
            root / "dataset_summary.json",
            {
                **plan,
                "shard_manifest": results,
                "partition_counts": numpy.sum(
                    [row["counts"] for row in results], axis=0
                ).tolist(),
                "validation_examples": sum(
                    row["validation_count"] for row in results
                ),
                "examples": sum(sum(row["counts"]) for row in results),
            },
        )
        write_json(root / "status.json", {**status, "stage": "complete"})

"""Complete-round labels separated from decision-time visible inputs."""

import types

import numpy
import riichienv

from log_dataset import (
    _native_collection,
    features,
    scoring,
    shanten,
)
from model import outcomes, payment_scoring


def ron_labels(state, actor, phase):
    """Known ron and abortive-draw payments for one decision."""
    payments = numpy.full((3, 37), -1, numpy.int32)
    legal_ron = numpy.full((3, 37), -1, numpy.int8)
    if phase in ("DISCARD", "RIICHI", "RESPONSE", "KAN"):
        cuts = {
            features.native_tile_code(action.tile): action.tile
            for action in state.legal_observation(actor).legal_actions()
            if action.action_type == riichienv.ActionType.DISCARD
        }
        kans = {}
        if phase == "KAN":
            kans = {
                action.tile // 4: action
                for action in state.legal_observation(actor).legal_actions()
                if action.action_type
                in (riichienv.ActionType.ANKAN, riichienv.ActionType.KAKAN)
            }
            cuts = {code: action.tile for code, action in kans.items()}
        if phase == "RESPONSE":
            for action in features.prefer_red_calls(
                state.legal_observation(actor).legal_actions()
            ):
                if action.action_type not in (
                    riichienv.ActionType.CHI,
                    riichienv.ActionType.PON,
                ):
                    continue
                env = state.native_env.clone()
                env.apply_event(
                    {
                        **features.action_event(action),
                        "actor": actor,
                        "target": state.pending_discard["actor"],
                    }
                )
                cuts.update(
                    {
                        features.native_tile_code(cut.tile): cut.tile
                        for cut in env.get_observation(actor).legal_actions()
                        if cut.action_type == riichienv.ActionType.DISCARD
                    }
                )
        payments[:, list(cuts)] = 0
        legal_ron[:, list(cuts)] = 0
        ura = next(
            (
                event["ura_markers"]
                for event in state.events
                if event["type"] == "hora" and event["ura_markers"]
            ),
            [],
        )
        for relative in range(3):
            opponent = (actor + relative + 1) % 4
            hand = state.legal_observation(opponent).hand
            if len(hand) % 3 != 1:
                continue
            waits = riichienv.HandEvaluator(
                hand, state.melds[opponent]
            ).get_waits()
            if (
                not waits
                or state.missed_agari(opponent)
                or (
                    phase == "RESPONSE"
                    and state.pending_discard["actor"] != opponent
                    and shanten.base_id(state.pending_discard["pai"]) in waits
                )
                or set(waits)
                & {
                    shanten.base_id(row["pai"])
                    for row in state.rivers[opponent]
                }
            ):
                continue
            for code, tile in cuts.items():
                if tile // 4 not in waits:
                    continue
                if (
                    phase == "KAN"
                    and kans[code].action_type == riichienv.ActionType.ANKAN
                    and (
                        state.melds[opponent]
                        or len({t // 4 for t in hand + [tile]}) != 13
                        or any(
                            t // 4 < 27 and t // 4 % 9 not in (0, 8)
                            for t in hand + [tile]
                        )
                    )
                ):
                    continue
                riichi = (
                    state.declared[opponent]
                    if phase == "RESPONSE"
                    else state.accepted[opponent]
                )
                score = _native_collection.score_hand(
                    types.SimpleNamespace(
                        tiles=hand + [tile],
                        melds=state.melds[opponent],
                        agari_tile=tile,
                        dora_indicators=state.legal_observation(
                            opponent
                        ).dora_indicators,
                    ),
                    conditions=riichienv.Conditions(
                        riichi=riichi,
                        double_riichi=(
                            riichi
                            and state.rivers[opponent][0]["riichi"]
                            and not any(
                                event["type"]
                                in {"chi", "pon", "daiminkan", "ankan", "kakan"}
                                for event in state.history[
                                    : state.rivers[opponent][0]["event_index"]
                                ]
                            )
                        ),
                        ippatsu=state.ippatsu[opponent] and phase != "RESPONSE",
                        houtei=state.live_wall == 0 and phase != "KAN",
                        chankan=phase == "KAN",
                        player_wind=(
                            riichienv.Wind.East,
                            riichienv.Wind.South,
                            riichienv.Wind.West,
                            riichienv.Wind.North,
                        )[(opponent - state.start["oya"]) % 4],
                        round_wind="ESWN".index(state.start["bakaze"]),
                    ),
                    ura=(
                        [
                            shanten.base_id(marker) * 4
                            for marker in ura[: len(state.dora_markers)]
                        ]
                        if riichi
                        else []
                    ),
                )
                if score.is_win:
                    legal_ron[relative, code] = 1
                    payments[relative, code] = (
                        -1
                        if (
                            (
                                riichi
                                and not score.yakuman
                                and len(ura) < len(state.dora_markers)
                            )
                            or state.native_env.pao[opponent]
                        )
                        else score.ron_agari + 300 * state.start["honba"]
                    )
        payments[:, (payments > 0).sum(axis=0) == 3] = -1
    return {"ron_payments": payments, "ron_legal": legal_ron}


def round_targets(state, events):
    length = len(events)
    ready = numpy.zeros((length, 4), bool)
    completion = numpy.full((length, 4, 2, len(scoring.NAMES)), -1, numpy.int8)
    completion_score = numpy.full((length, 4, 2), -1, numpy.int16)
    for index, event in enumerate(events):
        if index:
            state.apply(event)
        for actor in range(4):
            counts = state.concealed_counts(actor)
            if counts.sum() % 3 != 1:
                continue
            ready[index, actor] = shanten.calculate_shanten(counts) == 0
            if not ready[index, actor]:
                continue
            observation = state.legal_observation(actor)
            visible = state.public_tiles()
            _, waits = scoring.score_waits(
                observation.hand,
                state.melds[actor],
                {
                    "own_discards": [
                        shanten.base_id(row["pai"])
                        for row in state.rivers[actor]
                    ],
                    "missed_agari": state.missed_agari(actor),
                    "unavailable_counts": counts
                    + numpy.bincount(
                        [shanten.base_id(tile) for tile in visible],
                        minlength=34,
                    ),
                    "unavailable_red": [
                        observation.hand.count(tile) + visible.count(name)
                        for tile, name in zip(
                            (16, 52, 88), ("5mr", "5pr", "5sr")
                        )
                    ],
                    "dora_indicators": observation.dora_indicators,
                    "player_wind": (actor - state.start["oya"]) % 4,
                    "round_wind": "ESWN".index(state.start["bakaze"]),
                },
            )
            # Yaku and value are one scorer witness, selected by points.
            # Ordinary ron/tsumo use the actual declaration and known dora,
            # with no hypothetical ura, ippatsu or special-event bonuses.
            for mode in range(2):
                candidates = [
                    wait["values"][2 * int(state.declared[actor]) + mode]
                    for wait in waits
                    if wait["unseen"] > 0
                    and wait["values"][2 * int(state.declared[actor]) + mode][
                        "legal"
                    ]
                ]
                if candidates:
                    best = max(candidates, key=lambda value: value["points"])
                    completion[index, actor, mode] = best["yaku"]
                    completion_score[index, actor, mode] = (
                        payment_scoring.score_class(
                            best["han"],
                            best["fu"],
                            best["yakuman"],
                        )
                    )
        if event["type"] == "hora":
            ready[index, event["actor"]] = True
    # Forecast the next recorded tenpai shape, never a maximum over future
    # shapes. A tenpai with no legal completion stays unknown for that mode.
    for index in range(length - 2, -1, -1):
        missing = ~ready[index]
        completion[index, missing] = completion[index + 1, missing]
        completion_score[index, missing] = completion_score[index + 1, missing]
    return {
        "completion": completion,
        "completion_score": completion_score,
        "payments": outcomes.terminal_payments(events),
    }


def candidate_yaku_affinity(packed):
    """Action-specific visible route labels, not realized future yaku."""
    result = numpy.full((96, 3), -1, numpy.float16)
    for hand_ix in numpy.flatnonzero(packed["candidate_hand_valid"]):
        melds = []
        for tile, kind in numpy.argwhere(
            packed["candidate_melds"][hand_ix, :, :5] > 0
        ):
            for _ in range(packed["candidate_melds"][hand_ix, tile, kind]):
                melds.append(
                    riichienv.Meld(
                        (
                            riichienv.MeldType.Chi,
                            riichienv.MeldType.Pon,
                            riichienv.MeldType.Daiminkan,
                            riichienv.MeldType.Ankan,
                            riichienv.MeldType.Kakan,
                        )[kind],
                        (
                            [int(tile + offset) * 4 for offset in range(3)]
                            if kind == 0
                            else [
                                int(tile) * 4 + copy
                                for copy in range(3 if kind == 1 else 4)
                            ]
                        ),
                        bool(kind != 3),
                    )
                )
        removed = numpy.flatnonzero(
            packed["candidate_hand_counts"][0]
            != packed["candidate_hand_counts"][hand_ix]
        )
        shared_discard = len(removed) == 1 and (
            packed["candidate_hand_counts"][0, removed[0]]
            - packed["candidate_hand_counts"][hand_ix, removed[0]]
            == 1
        )
        # Search each discard from the common parent so its first draw/cut
        # nodes reuse the already-computed ukeire neighborhood. Routes and
        # their separate search budgets are identical to the post-cut hand.
        result[hand_ix] = scoring.hand_yaku_fractions(
            counts=packed["candidate_hand_counts"][
                0 if shared_discard else hand_ix
            ],
            unavailable=packed["known_unavailable_counts"],
            melds=melds,
            player_wind=int(packed["seat_wind"][0]),
            round_wind=int(packed["prevailing_wind"]),
            cuts=removed if shared_discard else None,
            names=("tanyao", "honitsu", "chanta"),
        )
    return result


def attach_beliefs(observation, state):
    """Decision-time hidden hands are labels, never public model features."""
    observation.opponent_shanten = numpy.full(3, -1, numpy.int8)
    observation.opponent_ukeire = numpy.full((3, 34), -1, numpy.int8)
    observation.opponent_hand_counts = numpy.zeros((3, 37), numpy.int8)
    for relative, seat in enumerate(
        (observation.actor + offset) % 4 for offset in range(1, 4)
    ):
        hand = state.legal_observation(seat).hand
        for tile in hand + [
            tile for meld in state.melds[seat] for tile in meld.tiles
        ]:
            observation.opponent_hand_counts[
                relative, features.native_tile_code(tile)
            ] += 1
        if len(hand) % 3 == 1:
            distance, improving, _ = shanten.improving(
                state.concealed_counts(seat)
            )
            observation.opponent_shanten[relative] = min(3, distance)
            observation.opponent_ukeire[relative] = 0
            observation.opponent_ukeire[relative, improving] = 1


def attach(observation, state, index):
    actor = observation.actor
    order = [(actor + offset) % 4 for offset in range(4)]
    observation.candidate_yaku_affinity = candidate_yaku_affinity(
        observation.features
    )
    observation.terminal_payment = outcomes.relative_payments(
        state.targets["payments"], actor, state.accepted
    )
    attach_beliefs(observation, state)
    observation.round_completion_yaku = state.targets["completion"][
        index, order
    ]
    observation.round_completion_score = state.targets["completion_score"][
        index, order
    ]

"""Legal actions, physical-copy selection and model action indexing."""

import numpy
import riichienv

from log_dataset import features
from model import outcomes

TRAIN_POLICY_HEADS = (
    "discard_policy_logits",
    "riichi_policy_logits",
    "response_policy_logits",
    "kan_action_logits",
    "win_decision_logits",
)

# All actor outputs use float32; only their shapes vary.
ACTOR_OUTPUTS = {
    "win_decision_logits": [2],
    "opponent_shanten_logits": [3, 4],
    "opponent_ukeire_by_shanten_logits": [3, 4, 34],
    "opponent_ukeire_logits": [3, 34],
    "opponent_wait_logits": [3, 34],
    "opponent_hand_count_logits": [3, 37, 5],
    "round_completion_yaku_logits": [4, 2, 23],
    "round_completion_score_logits": [4, 2, len(outcomes.SCORE_STATES)],
    "discard_policy_logits": [37],
    "riichi_policy_logits": [74],
    "response_policy_logits": [150],
    "riichi_action_logits": [2],
    "response_action_logits": [4],
    "chi_pattern_logits": [3],
    "kan_action_logits": [35],
}


# Public serving tensors; other actor outputs remain internal training/context.
SERVING_ACTOR_OUTPUTS = {
    name: ACTOR_OUTPUTS[name]
    for name in (
        *TRAIN_POLICY_HEADS,
        "opponent_shanten_logits",
        "riichi_action_logits",
        "response_action_logits",
        "chi_pattern_logits",
    )
}


KAN_ACTIONS = {riichienv.ActionType.ANKAN, riichienv.ActionType.KAKAN}
WIN_ACTIONS = {riichienv.ActionType.RON, riichienv.ActionType.TSUMO}


def phase_for_actions(legal_actions):
    kinds = {action.action_type for action in legal_actions}
    if kinds & WIN_ACTIONS:
        return "WIN"
    if kinds & KAN_ACTIONS:
        return "KAN"
    if riichienv.ActionType.RIICHI in kinds:
        return "RIICHI"
    if riichienv.ActionType.DISCARD in kinds:
        return "DISCARD"
    return "RESPONSE"


def forced_policy_action(state, actor, legal_actions):
    # Kyuushu remains automatic; optional wins belong to the policy.
    for action in legal_actions:
        if action.action_type == riichienv.ActionType.KYUSHU_KYUHAI:
            return action
    if len(legal_actions) == 1:
        return legal_actions[0]
    selected = features.single_legal_action(
        legal_actions, state.legal_observation(actor).drawn_tile
    )
    if (
        selected is not None
        and selected.action_type == riichienv.ActionType.DISCARD
    ):
        return select_discard(
            legal_actions,
            features.native_tile_code(selected.tile),
            state.legal_observation(actor).drawn_tile,
        )
    return selected


def policy_request(state, actor, observation, east_only=False):
    legal = observation.legal_actions()
    phase = phase_for_actions(legal)
    packed = features.pack(
        state=state, actor=actor, phase=phase, east_only=east_only
    )
    return phase, {
        "features": packed,
        "actor": actor,
        "legal_actions": legal,
        "drawn_tile": observation.drawn_tile,
        "phase": phase,
    }


def continue_request(request):
    declined = WIN_ACTIONS if request["phase"] == "WIN" else KAN_ACTIONS
    legal = [
        action
        for action in request["legal_actions"]
        if action.action_type not in declined
    ]
    phase = phase_for_actions(legal)
    return {
        **request,
        "legal_actions": legal,
        "phase": phase,
        "features": {
            **request["features"],
            "decision_phase": numpy.array(features.PHASES[phase], numpy.int8),
            "win_kind": numpy.array(0, numpy.int8),
        },
    }


def select_discard(legal_actions, discard_action, drawn_tile):
    candidates = [
        action
        for action in legal_actions
        if action.action_type == riichienv.ActionType.DISCARD
        and features.native_tile_code(action.tile) == discard_action
    ]
    # Balance drawn/held origins when both are legal for this tile class.
    origins = [
        copies
        for drawn in (False, True)
        if (
            copies := [
                action
                for action in candidates
                if (action.tile == drawn_tile) == drawn
            ]
        )
    ]
    copies = origins[numpy.random.randint(len(origins))]
    return copies[numpy.random.randint(len(copies))]


def policy_candidates(request):
    if request["phase"] == "WIN":
        return (
            [("win_decision_logits", 0, None, {})]
            if any(
                action.action_type not in WIN_ACTIONS
                for action in request["legal_actions"]
            )
            else []
        ) + [
            (
                "win_decision_logits",
                1,
                next(
                    action
                    for action in request["legal_actions"]
                    if action.action_type in WIN_ACTIONS
                ),
                {},
            ),
        ]
    if request["phase"] == "DISCARD":
        return [
            (
                "discard_policy_logits",
                code,
                select_discard(
                    request["legal_actions"], code, request["drawn_tile"]
                ),
                {},
            )
            for code in numpy.flatnonzero(
                request["features"]["discard_action_legal"]
            )
        ]
    result = []
    if request["phase"] == "RIICHI":
        for code in numpy.flatnonzero(
            request["features"]["discard_action_legal"]
        ):
            action = select_discard(
                request["legal_actions"], code, request["drawn_tile"]
            )
            result.append(
                (
                    "riichi_policy_logits",
                    int(code),
                    action,
                    {"discard_action": int(code)},
                )
            )
            if request["features"]["riichi_discard_legal_mask"][code]:
                declaration = next(
                    value
                    for value in request["legal_actions"]
                    if value.action_type == riichienv.ActionType.RIICHI
                )
                result.append(
                    (
                        "riichi_policy_logits",
                        37 + int(code),
                        declaration,
                        {"discard_action": int(code)},
                    )
                )
    elif request["phase"] == "RESPONSE":
        for action in features.prefer_red_calls(request["legal_actions"]):
            if action.action_type == riichienv.ActionType.PASS:
                result.append(("response_policy_logits", 0, action, {}))
            elif action.action_type == riichienv.ActionType.DAIMINKAN:
                result.append(("response_policy_logits", 149, action, {}))
            elif action.action_type in (
                riichienv.ActionType.CHI,
                riichienv.ActionType.PON,
            ):
                chii = action.action_type == riichienv.ActionType.CHI
                option = (
                    features.chii_pattern(action.tile, action.consume_tiles)
                    if chii
                    else 0
                )
                for cut in numpy.flatnonzero(
                    request["features"][
                        "chi_discard_legal" if chii else "pon_discard_legal"
                    ][option]
                ):
                    result.append(
                        (
                            "response_policy_logits",
                            (1 if chii else 112) + option * 37 + int(cut),
                            action,
                            {
                                "discard_action": int(cut),
                                "continuation_discard": int(cut),
                            },
                        )
                    )
    else:
        result.append(("kan_action_logits", 0, None, {}))
        for action in request["legal_actions"]:
            if action.action_type in KAN_ACTIONS:
                result.append(
                    ("kan_action_logits", 1 + action.tile // 4, action, {})
                )
    return list({(row[0], row[1]): row for row in result}.values())


def opening_temperature(state, actor):
    return max(0.0, 1.5 - 0.5 * len(state.rivers[actor]))


def select_policy_action(request, outputs, batch_index, temperature=0.0):
    candidates = policy_candidates(request)
    if not candidates:
        return None, {"candidate_count": 0, "probability": 1.0}
    # A decision's candidates all use the head chosen by policy_candidates.
    scores = numpy.asarray(outputs[candidates[0][0]])[
        batch_index, [code for _, code, _, _ in candidates]
    ]
    weights = numpy.exp(scores - scores.max())
    probability = weights / weights.sum()
    if temperature > 0:
        weights = numpy.exp((scores - scores.max()) / temperature)
        selected = int(
            numpy.random.choice(len(candidates), p=weights / weights.sum())
        )
        return candidates[selected][2], {
            **candidates[selected][3],
            "candidate_count": len(candidates),
            "probability": float(probability[selected]),
        }
    # Select the immediate decision by its marginal mass before choosing
    # its continuation. Otherwise several good discards split a call's vote.
    groups = []
    if request["phase"] == "RIICHI":
        groups = [numpy.array([code // 37 for _, code, _, _ in candidates])]
    elif request["phase"] == "RESPONSE":
        groups = [
            numpy.array(
                [
                    (
                        0
                        if code == 0
                        else 1 if code < 112 else 2 if code < 149 else 3
                    )
                    for _, code, _, _ in candidates
                ]
            ),
            numpy.array(
                [
                    0 if code == 0 else (code - 1) // 37 + 1
                    for _, code, _, _ in candidates
                ]
            ),
        ]
    eligible = numpy.ones(len(candidates), dtype=bool)
    for group in groups:
        totals = numpy.bincount(group, weights=probability * eligible)
        branch = numpy.random.choice(numpy.flatnonzero(totals == totals.max()))
        eligible &= group == branch
    selected = int(
        numpy.random.choice(
            numpy.flatnonzero(
                eligible & (probability == probability[eligible].max())
            )
        )
    )
    return candidates[selected][2], {
        **candidates[selected][3],
        "candidate_count": len(candidates),
        "probability": float(probability[selected]),
    }


def legal_choices(inputs):
    import tensorflow as tf

    discard = tf.cast(inputs["discard_action_legal"], tf.bool)
    declaration = tf.cast(inputs["riichi_discard_legal_mask"], tf.bool)
    return {
        "win_decision_logits": tf.stack(
            [
                tf.ones_like(inputs["win_kind"], dtype=tf.bool),
                inputs["win_kind"] > 0,
            ],
            axis=-1,
        ),
        "discard_policy_logits": discard,
        "riichi_policy_logits": tf.concat([discard, discard & declaration], 1),
        "response_policy_logits": tf.concat(
            [
                tf.cast(inputs["response_legal_mask"][:, :1], tf.bool),
                tf.reshape(
                    tf.cast(inputs["chi_discard_legal"], tf.bool), (-1, 111)
                ),
                tf.reshape(
                    tf.cast(inputs["pon_discard_legal"], tf.bool), (-1, 37)
                ),
                tf.cast(inputs["response_legal_mask"][:, 3:], tf.bool),
            ],
            axis=1,
        ),
        "kan_action_logits": tf.cast(inputs["kan_legal_mask"], tf.bool),
    }


def guaranteed_safe_tiles(inputs):
    """Publicly proven ron safety, by opponent and base tile."""
    import tensorflow as tf

    exhausted = inputs["known_unavailable_counts"] == 4
    # The offered honor itself cannot rule out a kokushi wait for that honor.
    kokushi_blocked = (
        tf.reduce_sum(
            tf.cast(
                tf.gather(
                    exhausted,
                    [0, 8, 9, 17, 18, 26, 27, 28, 29, 30, 31, 32, 33],
                    axis=1,
                ),
                tf.int32,
            ),
            axis=1,
        )
        >= 2
    )
    return (inputs["genbutsu_to_seat"][:, 1:] > 0) | (
        exhausted[:, None, :]
        & (tf.range(34)[None, None, :] >= 27)
        & (
            kokushi_blocked[:, None, None]
            | tf.reduce_any(
                inputs["meld_valid"][:, 1:] > 0, axis=-1, keepdims=True
            )
        )
    )


def candidate_hand_indices(inputs):
    """Map the shared 295 action slots to their post-action hand banks."""
    import tensorflow as tf

    discard = inputs["discard_candidate_hand"]
    batch = tf.shape(discard)[0]
    return tf.concat(
        [
            discard,
            discard,
            discard,
            tf.zeros((batch, 1), discard.dtype),
            tf.reshape(inputs["chi_candidate_hand"], (-1, 111)),
            tf.reshape(inputs["pon_candidate_hand"], (-1, 37)),
            tf.zeros((batch, 1), discard.dtype),
            inputs["kan_candidate_hand"],
        ],
        axis=1,
    )


def discard_decisions(inputs, selected):
    """Actions ending in a discard, including chii/pon then discard."""
    import tensorflow as tf

    phase = tf.gather(inputs["decision_phase"], selected[:, 0])
    return (
        ((phase == 0) & (selected[:, 1] < 37))
        | ((phase == 3) & (selected[:, 1] >= 37) & (selected[:, 1] < 111))
        | ((phase == 1) & (selected[:, 1] >= 112) & (selected[:, 1] < 260))
    )

"""Policy heads, action priors and final candidate scoring."""

import math

import tensorflow as tf

from model import actions, beliefs, encoder, losses, payment_scoring


@tf.keras.utils.register_keras_serializable(package="nejimakidori")
class PolicyMask(tf.keras.layers.Layer):
    def __init__(self, head, **kwargs):
        super().__init__(**kwargs)
        self.head = head

    def get_config(self):
        return {**super().get_config(), "head": self.head}

    def call(self, values):
        logits, inputs = values
        mask = actions.legal_choices(inputs)[self.head]
        if self.head in ("discard_policy_logits", "riichi_policy_logits"):
            branches = []
            for start in range(
                0, 74 if self.head == "riichi_policy_logits" else 37, 37
            ):
                branch = logits[:, start : start + 37]
                legal = mask[:, start : start + 37]
                branch = tf.where(
                    (
                        (inputs["opponent_discard_count"][:, 0] == 0)
                        & (inputs["dealer_relative_seat"] == 0)
                    )[:, None],
                    opening_discard_symmetry(branch, inputs, legal),
                    branch,
                )
                if start == 0:
                    branch = tf.where(
                        (inputs["live_wall_count"] == 0)[:, None],
                        late_noten_safety(branch, inputs, legal),
                        branch,
                    )
                branches.append(branch)
            logits = tf.concat(branches, axis=-1)
        return tf.where(
            tf.reduce_any(mask, -1, keepdims=True),
            tf.where(mask, logits, -1e4),
            tf.zeros_like(logits),
        )


@tf.keras.utils.register_keras_serializable(package="nejimakidori")
class PolicyPrior(tf.keras.layers.Layer):
    def __init__(self, head, **kwargs):
        super().__init__(**kwargs)
        self.head = head

    def get_config(self):
        return {**super().get_config(), "head": self.head}

    def call(self, values):
        logits, inputs = values
        mask = actions.legal_choices(inputs)[self.head]
        raw = tf.where(mask, logits, -1e4)
        if self.head == "discard_policy_logits":
            logits = opening_discard_symmetry(
                opening_discard_efficiency(logits, inputs, mask),
                inputs,
                mask,
            )
        elif self.head == "riichi_policy_logits":
            logits = tf.concat(
                [
                    opening_discard_symmetry(
                        opening_discard_efficiency(
                            logits[:, start : start + 37],
                            inputs,
                            mask[:, :37],
                        ),
                        inputs,
                        mask[:, start : start + 37],
                    )
                    for start in (0, 37)
                ],
                axis=-1,
            )
        if self.head == "discard_policy_logits":
            logits = late_noten_safety(logits, inputs, mask)
        elif self.head == "riichi_policy_logits":
            # Only the dama branch can contain noten choices.
            logits = tf.concat(
                [
                    late_noten_safety(logits[:, :37], inputs, mask[:, :37]),
                    logits[:, 37:],
                ],
                axis=-1,
            )
        target = tf.stop_gradient(
            tf.nn.log_softmax(tf.where(mask, logits, -1e4))
        )
        return tf.reduce_sum(
            tf.exp(target) * (target - tf.nn.log_softmax(raw)), axis=-1
        )


@tf.keras.utils.register_keras_serializable(package="nejimakidori")
class PolicySummaries(tf.keras.layers.Layer):
    def call(self, outputs):
        riichi = tf.reshape(outputs["riichi_policy_logits"], (-1, 2, 37))
        response = outputs["response_policy_logits"]
        chii = tf.reshape(response[:, 1:112], (-1, 3, 37))
        pon = tf.reshape(response[:, 112:149], (-1, 1, 37))
        return {
            **beliefs.opponent_summaries(outputs),
            "riichi_action_logits": tf.reduce_logsumexp(riichi, -1),
            "response_action_logits": tf.stack(
                [
                    response[:, 0],
                    tf.reduce_logsumexp(chii, (1, 2)),
                    tf.reduce_logsumexp(pon, (1, 2)),
                    response[:, 149],
                ],
                axis=-1,
            ),
            "chi_pattern_logits": tf.reduce_logsumexp(chii, -1),
        }


def build_policy_heads(inputs, hidden, candidates, selected, context):
    """Named auxiliary predictions followed by one action policy."""
    route = tf.keras.layers.Dense(3, dtype="float32", name="route_affinity")(
        candidates
    )
    raw_route = route
    route = RouteMask(dtype="float32")([route, inputs, selected])
    ron = tf.keras.layers.Dense(3, dtype="float32", name="candidate_ron")(
        candidates
    )
    outputs = {
        "route_affinity_logits": route,
        "route_constraint_loss": losses.ConstraintLoss(
            binary=True, dtype="float32"
        )([raw_route, route, selected[:, 0]]),
        "candidate_ron_logits": ron,
    }
    final = FinalCandidates()(
        [
            tf.keras.layers.Concatenate()(
                [
                    candidates,
                    tf.keras.layers.Activation("sigmoid")(route),
                    ron,
                ]
            ),
            context,
            selected,
        ]
    )
    final = tf.keras.layers.Dense(256, activation="gelu", name="final_pass")(
        final
    )
    final = tf.keras.layers.LayerNormalization(
        center=False,
        scale=False,
        epsilon=1e-5,
        dtype="float32",
        name="final_pass_normalized",
    )(final)
    # Uncomputed actions are constant padding, not learned illegal logits.
    # Only the legal candidate scores participate in policy training.
    final = UnpackCandidates()(
        [
            tf.keras.layers.Dense(1, dtype="float32", name="final_scores")(
                final
            ),
            selected,
            hidden,
        ]
    )[:, :, 0]
    for name, values in (
        ("discard_policy_logits", final[:, :37]),
        ("riichi_policy_logits", final[:, 37:111]),
        (
            "response_policy_logits",
            ResponseKan(dtype="float32")([final, inputs]),
        ),
        ("kan_action_logits", final[:, 260:295]),
    ):
        outputs[name] = PolicyMask(name, name=name, dtype="float32")(
            [values, inputs]
        )
        outputs[name + "_prior_loss"] = PolicyPrior(
            name, name=name + "_prior_loss", dtype="float32"
        )([values, inputs])
    return outputs


def build_board_heads(inputs, hidden, belief_probability):
    win = tf.keras.layers.Dense(2, dtype="float32", name="win_decision_logits")(
        hidden
    )
    outputs = {
        "win_decision_logits": PolicyMask(
            "win_decision_logits", name="win_legality", dtype="float32"
        )([win, inputs]),
    }
    outputs["win_decision_logits_prior_loss"] = PolicyPrior(
        "win_decision_logits", dtype="float32"
    )([outputs["win_decision_logits"], inputs])
    context_probability = [
        belief_probability[name] for name in beliefs.BELIEF_HEADS
    ]
    for name in (
        "round_completion_yaku_logits",
        "round_completion_score_logits",
    ):
        values = tf.keras.layers.Dense(
            math.prod(actions.ACTOR_OUTPUTS[name]), dtype="float32"
        )(hidden)
        values = tf.keras.layers.Reshape(
            actions.ACTOR_OUTPUTS[name], dtype="float32"
        )(values)
        raw = values
        if name == "round_completion_yaku_logits":
            values = payment_scoring.CompletionMask(dtype="float32")(
                [values, inputs]
            )
            context_probability.append(
                tf.keras.layers.Activation("sigmoid")(values)
            )
        else:
            values = payment_scoring.CompletionScoreMask(dtype="float32")(
                [values, inputs]
            )
            values = payment_scoring.CompletionScoreCoupling(dtype="float32")(
                [values, outputs["round_completion_yaku_logits"], inputs]
            )
            context_probability.append(tf.keras.layers.Softmax()(values))
        outputs[name + "_constraint_loss"] = losses.ConstraintLoss(
            binary=name == "round_completion_yaku_logits", dtype="float32"
        )([raw, values])
        outputs[name] = values
    # Completion probabilities carry the same constraints into the policy.
    # Other heads retain their established representation.
    context = tf.keras.layers.Dense(128, activation="gelu")(
        tf.keras.layers.Concatenate()(
            [hidden, encoder.numeric_features(context_probability)]
        )
    )
    context = tf.keras.layers.Concatenate()([hidden, context])
    return outputs, context


def late_noten_safety(logits, inputs, legal):
    """Mix in uniform proven-safe discards; fully override at exhaustion."""
    safe = legal & tf.gather(
        tf.reduce_all(actions.guaranteed_safe_tiles(inputs), axis=1),
        list(range(34)) + [4, 13, 22],
        axis=1,
    )
    # With an all-terminal/honor river, discarding a middle tile can forfeit
    # nagashi mangan. The feature contract does not record own called rivers,
    # so conservatively retain that possibility rather than infer it away.
    middle = tf.constant([i for i in range(27) if 0 < i % 9 < 8])
    nagashi_possible = ~tf.reduce_any(
        tf.gather(inputs["genbutsu_to_seat"][:, 0] > 0, middle, axis=1), axis=1
    )
    terminal_or_honor = tf.constant(
        [i >= 27 or i % 9 in (0, 8) for i in range(34)] + [False] * 3
    )
    safe &= ~nagashi_possible[:, None] | terminal_or_honor[None]
    active = tf.reduce_any(safe, axis=-1) & ~tf.reduce_any(
        legal & (inputs["discard_action_all_shanten"] <= 1), axis=-1
    )
    strength = tf.where(
        active,
        1
        - tf.square(
            tf.clip_by_value(
                tf.cast(inputs["live_wall_count"], tf.float32) / 8, 0, 1
            )
        ),
        0.0,
    )[:, None]
    total = tf.reduce_logsumexp(
        tf.where(legal, logits, -1e4), axis=-1, keepdims=True
    )
    uniform = total - tf.math.log(
        tf.maximum(
            1.0,
            tf.reduce_sum(tf.cast(safe, tf.float32), axis=-1, keepdims=True),
        )
    )
    target = tf.where(safe, uniform, -1e4)
    mixed = tf.reduce_logsumexp(
        tf.stack(
            [
                logits + tf.math.log(tf.maximum(1 - strength, 1e-30)),
                target + tf.math.log(tf.maximum(strength, 1e-30)),
            ],
            axis=-1,
        ),
        axis=-1,
    )
    return tf.where(
        strength == 0, logits, tf.where(strength == 1, target, mixed)
    )


def opening_discard_efficiency(logits, inputs, legal):
    """Bounded efficiency bias, gone after five discards by any opponent."""
    score = -tf.cast(
        inputs["discard_action_all_shanten"], tf.float32
    ) + 0.35 * tf.math.log1p(
        tf.cast(inputs["discard_action_all_ukeire_count"], tf.float32)
    ) / math.log(
        137.0
    )
    strength = tf.maximum(
        0.0,
        1.0
        - tf.reduce_max(
            tf.cast(inputs["opponent_discard_count"][:, 1:], tf.float32),
            axis=-1,
            keepdims=True,
        )
        / 5.0,
    )
    bias = tf.clip_by_value(
        score
        - tf.reduce_max(tf.where(legal, score, -1e4), axis=-1, keepdims=True),
        -1.5,
        0.0,
    )
    return logits + tf.where(legal, strength * bias, 0.0)


def opening_discard_symmetry(logits, inputs, legal):
    """Exact dealer first-cut pooling; otherwise fade with opponent discards."""
    counts = inputs["candidate_hand_counts"][:, 0]
    suited = tf.reshape(counts[:, :27], (-1, 3, 9))
    non_dora = ~tf.reduce_any(
        tf.reshape(inputs["dora_multiplicity"][:, :27] > 0, (-1, 3, 9)),
        axis=-1,
    )
    terminals = tf.reshape(
        tf.stack(
            [
                non_dora
                & (suited[:, :, 0] == 1)
                & tf.reduce_all(suited[:, :, 1:5] == 0, -1),
                non_dora
                & (suited[:, :, 8] == 1)
                & tf.reduce_all(suited[:, :, 4:8] == 0, -1),
            ],
            axis=-1,
        ),
        (-1, 6),
    )
    floating = (
        tf.linalg.matmul(
            tf.cast(terminals, tf.float32),
            tf.one_hot([0, 8, 9, 17, 18, 26], 37),
        )
        > 0
    ) & legal
    symmetric = (
        non_dora
        & (suited[:, :, 0] == 1)
        & tf.reduce_all(suited == tf.reverse(suited, axis=[-1]), axis=-1)
        & tf.reduce_all(suited[:, :, 1:3] == 0, axis=-1)
        & ~tf.reduce_any(floating, axis=-1, keepdims=True)
    )
    winds = tf.constant([[0, 1, 2, 3]], dtype=tf.int8)
    groups = (
        tf.concat(
            [
                floating[:, None, :],
                tf.pad(
                    (counts[:, 31:34] == 1)
                    & (inputs["dora_multiplicity"][:, 31:34] == 0),
                    [[0, 0], [31, 3]],
                )[:, None, :],
                tf.pad(
                    (counts[:, 27:31] == 1)
                    & (inputs["dora_multiplicity"][:, 27:31] == 0)
                    & (winds != inputs["seat_wind"][:, 0, None])
                    & (winds != inputs["seat_wind"][:, 1, None])
                    & (winds != inputs["prevailing_wind"][:, None]),
                    [[0, 0], [27, 6]],
                )[:, None, :],
                symmetric[:, :, None]
                & tf.cast(
                    tf.one_hot([0, 9, 18], 37) + tf.one_hot([8, 17, 26], 37),
                    tf.bool,
                )[None],
            ],
            axis=1,
        )
        & legal[:, None, :]
    )
    strength = tf.where(
        (inputs["opponent_discard_count"][:, 0] == 0)
        & (inputs["dealer_relative_seat"] == 0),
        1.0,
        tf.clip_by_value(
            1.0
            - tf.reduce_sum(
                tf.cast(inputs["opponent_discard_count"][:, 1:], tf.float32),
                axis=-1,
            )
            / 6.0,
            0.0,
            5.0 / 6.0,
        ),
    )
    # Log-space arithmetic preserves tiny probabilities and group mass.
    group_mean = tf.reduce_logsumexp(
        tf.where(groups, logits[:, None, :], -1e9), axis=-1
    ) - tf.math.log(
        tf.maximum(1.0, tf.reduce_sum(tf.cast(groups, tf.float32), axis=-1))
    )
    pooled = tf.reduce_sum(
        tf.where(groups, group_mean[:, :, None], 0.0), axis=1
    )
    mixed = tf.reduce_logsumexp(
        tf.stack(
            [
                logits + tf.math.log(1.0 - strength[:, None]),
                pooled + tf.math.log(strength[:, None]),
            ],
            axis=-1,
        ),
        axis=-1,
    )
    return tf.where(
        tf.reduce_any(groups, axis=1) & (strength[:, None] > 0), mixed, logits
    )


@tf.keras.utils.register_keras_serializable(package="nejimakidori")
class FinalCandidates(tf.keras.layers.Layer):
    def call(self, values):
        candidates, context, selected = values
        return tf.concat(
            [candidates, tf.gather(context, selected[:, 0])],
            axis=-1,
        )


@tf.keras.utils.register_keras_serializable(package="nejimakidori")
class ResponseKan(tf.keras.layers.Layer):
    def call(self, values):
        scores, inputs = values
        # A response kan refers to the triggering discard's base tile.
        return tf.concat(
            [
                scores[:, 111:260],
                tf.gather(
                    scores[:, 261:295],
                    tf.cast(inputs["trigger_tile_id"], tf.int32),
                    batch_dims=1,
                )[:, None],
            ],
            axis=-1,
        )


def policy_loss(labels, logits, mean=losses.mean_valid):
    nll = tf.add_n(
        [
            tf.nn.sparse_softmax_cross_entropy_with_logits(
                labels=tf.maximum(tf.cast(labels[name], tf.int32), 0),
                logits=tf.cast(logits[name], tf.float32),
            )
            * tf.cast(labels[name] >= 0, tf.float32)
            for name in actions.TRAIN_POLICY_HEADS
        ]
    )
    return mean(
        nll,
        tf.reduce_any(
            tf.stack(
                [labels[name] >= 0 for name in actions.TRAIN_POLICY_HEADS]
            ),
            axis=0,
        ),
    )


def distribution(outputs, heads, legal):
    """Normalize over the exact native candidates used by the collector."""
    logits = tf.stack(
        [
            tf.pad(outputs[name], [[0, 0], [0, 150 - outputs[name].shape[-1]]])
            for name in actions.TRAIN_POLICY_HEADS
        ],
        axis=1,
    )
    logits = tf.gather(logits, heads, batch_dims=1)
    return tf.nn.log_softmax(tf.where(legal, logits, -1e9), axis=-1)


def greedy_choices(log_probability, heads):
    """Marginal branch selection on device, with lowest-index tie breaks."""
    chosen = tf.argmax(log_probability, axis=1, output_type=tf.int32)
    for head, levels in (
        (1, ((37, 37),)),
        (2, ((1, 111, 37, 1), (1, 37, 37, 37, 37, 1))),
    ):
        scores = log_probability[:, : sum(levels[0])]
        for sizes in levels:
            branch = tf.argmax(
                tf.stack(
                    [
                        tf.reduce_logsumexp(part, axis=1)
                        for part in tf.split(scores, sizes, axis=1)
                    ],
                    axis=1,
                ),
                axis=1,
                output_type=tf.int32,
            )
            scores = tf.where(
                tf.repeat(tf.range(len(sizes)), sizes)[None] == branch[:, None],
                scores,
                -float("inf"),
            )
        chosen = tf.where(
            heads == head,
            tf.argmax(scores, axis=1, output_type=tf.int32),
            chosen,
        )
    return chosen


def offline_loss_terms(inputs, outputs, mean=losses.mean_valid):
    metrics = {}
    metrics["policy_loss"] = policy_loss(inputs[1], outputs, mean=mean)
    metrics["policy_prior_loss"] = mean(
        tf.add_n(
            [
                outputs[name + "_prior_loss"]
                * tf.cast(inputs[1][name] >= 0, tf.float32)
                for name in actions.TRAIN_POLICY_HEADS
            ]
        ),
        tf.reduce_any(
            tf.stack(
                [inputs[1][name] >= 0 for name in actions.TRAIN_POLICY_HEADS]
            ),
            axis=0,
        ),
    )
    metrics["completion_yaku_loss"] = mean(
        tf.nn.sigmoid_cross_entropy_with_logits(
            labels=tf.maximum(
                tf.cast(inputs[1]["round_completion_yaku"], tf.float32), 0
            ),
            logits=outputs["round_completion_yaku_logits"],
        ),
        inputs[1]["round_completion_yaku"] >= 0,
    )
    metrics["completion_score_loss"] = mean(
        tf.nn.sparse_softmax_cross_entropy_with_logits(
            labels=tf.maximum(
                tf.cast(inputs[1]["round_completion_score"], tf.int32), 0
            ),
            logits=outputs["round_completion_score_logits"],
        ),
        inputs[1]["round_completion_score"] >= 0,
    )
    return metrics


@tf.keras.utils.register_keras_serializable(package="nejimakidori")
class UnpackCandidates(tf.keras.layers.Layer):
    def call(self, values):
        packed, selected, board = values
        return tf.scatter_nd(
            selected,
            packed,
            (tf.shape(board)[0], 295, packed.shape[-1]),
        )


class RouteMask(tf.keras.layers.Layer):
    def call(self, values):
        logits, inputs, selected = values
        hands = tf.stack(
            [
                selected[:, 0],
                tf.cast(
                    tf.gather_nd(
                        actions.candidate_hand_indices(inputs),
                        selected,
                    ),
                    tf.int32,
                ),
            ],
            axis=1,
        )
        allowed = payment_scoring.support(
            tf.gather_nd(tf.cast(inputs["candidate_melds"], tf.float32), hands)
        )
        # Outside routes include sequence-free honroutou/chinroutou.
        return tf.where(
            tf.stack(
                [
                    allowed[..., 1],
                    allowed[..., 18],
                    allowed[..., 10] | allowed[..., 11],
                ],
                axis=-1,
            ),
            logits,
            -1e9,
        )


def ron_risk_labels(labels, selected, structure):
    """Legal discard ron, including unknown amounts but excluding triple ron."""
    legal = tf.gather_nd(
        tf.transpose(labels["ron_legal"], [0, 2, 1]),
        tf.stack(
            [
                selected[:, 0],
                tf.minimum(tf.cast(structure[:, -1], tf.int32), 36),
            ],
            axis=1,
        ),
    )
    risk = legal == 1
    return risk & ~tf.reduce_all(risk, axis=1)[:, None]


def auxiliary_loss_terms(inputs, outputs, mean=losses.mean_valid):
    features, labels, _ = inputs
    selected = outputs["selected"]
    hand_indices = actions.candidate_hand_indices(features)
    affinity = tf.cast(
        tf.gather_nd(
            labels["candidate_yaku_affinity"],
            tf.stack(
                [
                    selected[:, 0],
                    tf.cast(tf.gather_nd(hand_indices, selected), tf.int32),
                ],
                axis=1,
            ),
        ),
        tf.float32,
    )
    terms = {
        "route_affinity_loss": losses.candidate_mean(
            tf.nn.sigmoid_cross_entropy_with_logits(
                labels=tf.maximum(affinity, 0.0),
                logits=outputs["route_affinity_logits"],
            ),
            affinity >= 0,
            selected[:, 0],
            mean=mean,
        ),
    }
    risk = ron_risk_labels(labels, selected, outputs["structure"])
    terms["candidate_ron_loss"] = losses.candidate_mean(
        tf.nn.sigmoid_cross_entropy_with_logits(
            labels=tf.cast(risk, tf.float32),
            logits=outputs["candidate_ron_logits"],
        ),
        tf.broadcast_to(
            actions.discard_decisions(features, selected)[:, None],
            tf.shape(risk),
        ),
        selected[:, 0],
        mean=mean,
    )
    return terms

"""Shared board, hand and river representations."""

import math

import tensorflow as tf

from log_dataset import _native_collection
from model import actions

HAND_BATCH_BUCKET = 512
# Deterministic scoring constraints bypass learned projections.
SCORING_INPUTS = frozenset(
    {
        "public_fu",
        "public_bonus",
        "candidate_public_fu",
        "candidate_public_bonus",
    }
)
BOARD_INPUTS = {
    name: spec
    for name, spec in _native_collection.INPUTS.items()
    if name not in SCORING_INPUTS
    and not name.startswith("river_")
    and name
    not in {
        "candidate_hand_counts",
        "candidate_hand_red",
        "candidate_melds",
        "candidate_hand_valid",
        "discard_candidate_hand",
        "chi_candidate_hand",
        "pon_candidate_hand",
        "kan_candidate_hand",
    }
}


@tf.keras.utils.register_keras_serializable(package="nejimakidori")
class BoardProjection(tf.keras.layers.Layer):
    """Shared score/yaku axes with distinct, ordered action slots."""

    def __init__(self, **kwargs):
        super().__init__(**kwargs)
        groups = {}
        offset = 1408
        for name, spec in BOARD_INPUTS.items():
            size = math.prod(spec["shape"])
            if name.endswith(("yaku_possibility",)):
                groups.setdefault(spec["shape"][-1], []).extend(
                    range(offset, offset + size)
                )
            offset += size
        selected = {index for indices in groups.values() for index in indices}
        self.retained = [
            index for index in range(offset) if index not in selected
        ]
        self.indices = list(groups.values())
        self.widths = list(groups)
        self.bases = [
            tf.keras.layers.Dense(
                max(4, width // 2), use_bias=False, dtype=self.dtype_policy
            )
            for width in self.widths
        ]
        self.project = tf.keras.layers.Dense(
            512, activation="gelu", dtype=self.dtype_policy
        )

    def build(self, input_shape):
        for width, basis in zip(self.widths, self.bases):
            basis.build((None, width))
        self.project.build(
            (
                None,
                len(self.retained)
                + sum(
                    len(indices) // width * basis.units
                    for width, indices, basis in zip(
                        self.widths, self.indices, self.bases
                    )
                ),
            )
        )
        super().build(input_shape)

    def call(self, values):
        encoded = [tf.gather(values, self.retained, axis=-1)]
        for width, indices, basis in zip(self.widths, self.indices, self.bases):
            encoded.append(
                tf.reshape(
                    basis(
                        tf.reshape(
                            tf.gather(values, indices, axis=-1),
                            (-1, len(indices) // width, width),
                        )
                    ),
                    (-1, len(indices) // width * basis.units),
                )
            )
        return self.project(tf.concat(encoded, -1))


def numeric_features(values):
    """Flatten numeric fields and compress magnitudes in float32."""
    return tf.keras.ops.arcsinh(
        tf.keras.ops.concatenate(
            [
                tf.keras.ops.reshape(
                    tf.keras.ops.cast(value, "float32"),
                    (-1, math.prod(value.shape[1:])),
                )
                for value in values
            ],
            axis=-1,
        )
    )


@tf.keras.utils.register_keras_serializable(package="nejimakidori")
class SuitResidual(tf.keras.layers.Layer):
    def __init__(self, dilation, **kwargs):
        super().__init__(**kwargs)
        self.dilation = dilation
        self.first = tf.keras.layers.Conv1D(
            filters=128,
            kernel_size=3,
            padding="same",
            dilation_rate=dilation,
            dtype=self.dtype_policy,
            activation="gelu",
        )
        self.second = tf.keras.layers.Conv1D(
            filters=128,
            kernel_size=3,
            padding="same",
            dilation_rate=dilation,
            dtype=self.dtype_policy,
        )
        self.normalization = tf.keras.layers.LayerNormalization(
            dtype=self.dtype_policy
        )

    def build(self, input_shape):
        self.first.build(input_shape)
        self.second.build((*input_shape[:-1], 128))
        self.normalization.build((*input_shape[:-1], 128))
        super().build(input_shape)

    def call(self, values):
        return tf.nn.gelu(
            self.normalization(values + self.second(self.first(values)))
        )

    def get_config(self):
        return {**super().get_config(), "dilation": self.dilation}


@tf.keras.utils.register_keras_serializable(package="nejimakidori")
class HandBank(tf.keras.layers.Layer):
    """Encode occupied candidate hands with shared, suit-local convolutions."""

    def __init__(self, **kwargs):
        super().__init__(**kwargs)
        self.board_fields = tuple(
            name
            for name in _native_collection.INPUTS
            if not name.startswith(
                ("candidate_", "discard_", "chi_", "pon_", "kan_")
            )
            and name not in ("river_pre_tile_id", "river_post_tile_id")
            and name not in SCORING_INPUTS
        )
        self.board_projection = tf.keras.layers.Dense(
            128, use_bias=False, dtype=self.dtype_policy
        )
        self.embedding = tf.keras.layers.Embedding(
            34, 16, dtype=self.dtype_policy
        )
        self.tiles = tf.keras.layers.Dense(
            128,
            activation=None,
            dtype=self.dtype_policy,
        )
        self.suits = [
            SuitResidual(dilation, dtype=self.dtype_policy)
            for dilation in (1, 2, 4)
        ]
        self.honors = tf.keras.layers.Dense(
            128, activation="gelu", dtype=self.dtype_policy
        )
        self.projection = tf.keras.layers.Dense(
            512, activation="gelu", dtype=self.dtype_policy
        )
        self.normalization = tf.keras.layers.LayerNormalization(
            dtype=self.dtype_policy
        )

    def build(self, input_shape):
        self.embedding.build((34,))
        self.tiles.build((None, 34, 47))
        self.board_projection.build(
            (
                None,
                6 * 32 * 34
                + sum(
                    math.prod(_native_collection.INPUTS[name]["shape"])
                    for name in self.board_fields
                ),
            )
        )
        for block in self.suits:
            block.build((None, 9, 128))
        self.honors.build((None, 7, 128))
        self.projection.build((None, 34 * 128))
        self.normalization.build((None, 512))
        super().build(input_shape)

    def call(self, inputs):
        selected = tf.where(inputs["candidate_hand_valid"] > 0)
        # GatherNd has no int8 GPU kernel. Cast before selecting so the
        # full candidate bank does not take a round trip through the host.
        counts = tf.gather_nd(
            tf.cast(inputs["candidate_hand_counts"], tf.int32), selected
        )
        red = tf.linalg.matmul(
            tf.gather_nd(
                tf.cast(inputs["candidate_hand_red"], self.compute_dtype),
                selected,
            ),
            tf.one_hot([4, 13, 22], 34, dtype=self.compute_dtype),
        )
        melds = tf.gather_nd(
            tf.cast(inputs["candidate_melds"], tf.int32), selected
        )
        # Exact raw keys include suit identity: tile embeddings differ by suit.
        # Only the integer deduplication runs on CPU; encodings stay on device.
        with tf.device("/CPU:0"):
            keys = tf.reshape(
                tf.concat(
                    [
                        tf.cast(counts[:, :27, None], tf.int32),
                        tf.cast(red[:, :27, None], tf.int32),
                        tf.cast(melds[:, :27], tf.int32),
                    ],
                    axis=-1,
                ),
                (-1, 72),
            )
            keys = tf.concat(
                [keys, tf.tile(tf.range(3), [tf.shape(counts)[0]])[:, None]],
                axis=-1,
            )
            # Board-conditioned suits can only share within one board.
            keys = tf.concat(
                [
                    keys,
                    tf.repeat(tf.cast(selected[:, 0], tf.int32), 3)[:, None],
                ],
                axis=-1,
            )
            unique, inverse = tf.raw_ops.UniqueV2(x=keys, axis=[0])
            first = tf.math.unsorted_segment_min(
                tf.range(tf.shape(keys)[0]), inverse, tf.shape(unique)[0]
            )
        values = tf.concat(
            [
                tf.one_hot(
                    tf.cast(counts, tf.int32), 5, dtype=self.compute_dtype
                ),
                red[..., None],
                tf.cast(melds, self.compute_dtype),
                tf.broadcast_to(
                    self.embedding(tf.range(34))[None],
                    (tf.shape(counts)[0], 34, 16),
                ),
            ],
            axis=-1,
        )
        values = tf.concat(
            [
                values,
                tf.gather(
                    tf.cast(
                        tf.math.asinh(
                            tf.concat(
                                [
                                    tf.cast(inputs[name][..., None], tf.float32)
                                    for name in (
                                        "dora_multiplicity",
                                        "known_unavailable_counts",
                                    )
                                ]
                                + [
                                    tf.cast(
                                        inputs["blocker_counts"],
                                        tf.float32,
                                    ),
                                    *[
                                        tf.transpose(
                                            tf.cast(inputs[name], tf.float32),
                                            (0, 2, 1),
                                        )
                                        for name in (
                                            "genbutsu_to_seat",
                                            "passed_unchanged_to_seat",
                                            "sotogawa_earliest_turn_to_seat",
                                        )
                                    ],
                                ],
                                axis=-1,
                            )
                        ),
                        self.compute_dtype,
                    ),
                    selected[:, 0],
                ),
            ],
            axis=-1,
        )
        # Keep convolution batch shapes stable as occupied hand counts vary.
        # Small inference requests use smaller buckets to limit padding cost.
        size = tf.shape(counts)[0]
        multiple = tf.where(size > 128, HAND_BATCH_BUCKET, 16)
        values = tf.pad(values, ((0, (-size) % multiple), (0, 0), (0, 0)))
        values = self.tiles(values)
        # Sum of affine maps is one joint affine map before the first
        # nonlinearity. No hand representation is compressed beforehand.
        board = self.board_projection(
            tf.concat(
                [
                    tf.reshape(
                        tf.one_hot(
                            tf.cast(
                                tf.stack(
                                    [
                                        inputs["river_pre_tile_id"],
                                        inputs["river_post_tile_id"],
                                    ],
                                    axis=2,
                                ),
                                tf.int32,
                            ),
                            34,
                        )
                        * tf.cast(
                            tf.stack(
                                [
                                    inputs["river_pre_valid"],
                                    inputs["river_post_valid"],
                                ],
                                axis=2,
                            )[..., None],
                            tf.float32,
                        ),
                        (-1, 6 * 32 * 34),
                    ),
                    numeric_features(
                        [inputs[name] for name in self.board_fields]
                    ),
                ],
                axis=-1,
            )
        )
        values = tf.nn.gelu(
            values
            + tf.pad(
                tf.gather(board, selected[:, 0])[:, None],
                ((0, (-size) % multiple), (0, 0), (0, 0)),
            )
        )
        suits = tf.gather(tf.reshape(values[:size, :27], (-1, 9, 128)), first)
        suit_size = tf.shape(suits)[0]
        # Coarser suit padding reduces compiled convolution shape variants.
        suit_multiple = tf.where(suit_size > 128, 4096, 16)
        suits = tf.pad(
            suits, ((0, (-suit_size) % suit_multiple), (0, 0), (0, 0))
        )
        for block in self.suits:
            suits = block(suits)
        # A leading batch axis makes Gather's gradient dense, so repeated
        # suits sum in float32 before the cast back to the compute dtype.
        suits = tf.reshape(
            tf.cast(
                tf.gather(tf.cast(suits, tf.float32)[None], inverse, axis=1)[0],
                suits.dtype,
            ),
            (-1, 27, 128),
        )
        suits = tf.pad(suits, ((0, (-size) % multiple), (0, 0), (0, 0)))
        values = tf.concat([suits, self.honors(values[:, 27:])], axis=1)
        values = self.normalization(
            self.projection(tf.reshape(values, (-1, 34 * 128)))
        )
        return tf.scatter_nd(
            selected,
            values[:size],
            tf.cast(
                (tf.shape(inputs["candidate_hand_valid"])[0], 96, 512), tf.int64
            ),
        )


@tf.keras.utils.register_keras_serializable(package="nejimakidori")
class RiverEncoding(tf.keras.layers.Layer):
    """Encode separately padded pre/post-riichi rivers with shared weights."""

    def __init__(self, **kwargs):
        super().__init__(**kwargs)
        self.fields = tuple(
            name.removeprefix("river_pre_")
            for name in _native_collection.INPUTS
            if name.startswith("river_pre_")
            and name not in ("river_pre_tile_id", "river_pre_valid")
        )
        self.embedding = tf.keras.layers.Embedding(
            34, 16, dtype=self.dtype_policy
        )
        self.tokens = tf.keras.layers.Dense(
            64, activation="gelu", dtype=self.dtype_policy
        )
        self.convolutions = [
            tf.keras.layers.Conv1D(
                filters=64,
                kernel_size=3,
                padding="same",
                dilation_rate=dilation,
                dtype=self.dtype_policy,
            )
            for dilation in (1, 2, 4)
        ]
        self.normalizations = [
            tf.keras.layers.LayerNormalization(dtype=self.dtype_policy)
            for _ in self.convolutions
        ]
        self.projection = tf.keras.layers.Dense(
            64, activation="gelu", dtype=self.dtype_policy
        )

    def build(self, input_shape):
        self.embedding.build(input_shape["river_pre_tile_id"])
        self.tokens.build((None, 32, 16 + len(self.fields)))
        for convolution, normalization in zip(
            self.convolutions, self.normalizations
        ):
            convolution.build((None, 32, 64))
            normalization.build((None, 32, 64))
        self.projection.build((None, 33 * 64))
        super().build(input_shape)

    def call(self, inputs):
        return self.encode(
            {
                name: value
                for name, value in inputs.items()
                if name.startswith(("river_pre_", "river_post_"))
            }
        )

    def encode(self, inputs):
        rivers = {
            name: tf.stack(
                [inputs["river_pre_" + name], inputs["river_post_" + name]],
                axis=2,
            )
            for name in ("tile_id", "valid", *self.fields)
        }
        mask = tf.reshape(
            tf.cast(rivers["valid"], self.compute_dtype), (-1, 32, 1)
        )
        metadata = tf.stack(
            [tf.cast(rivers[name], tf.float32) for name in self.fields], -1
        )
        values = tf.reshape(
            tf.concat(
                [
                    self.embedding(rivers["tile_id"]),
                    tf.cast(tf.math.asinh(metadata), self.compute_dtype),
                ],
                axis=-1,
            ),
            (-1, 32, 16 + len(self.fields)),
        )
        values = self.tokens(values) * mask
        # All positions are already observed. Mask every block so padding
        # cannot feed activations back into the observed river boundary.
        for convolution, normalization in zip(
            self.convolutions, self.normalizations
        ):
            values = (
                tf.nn.gelu(normalization(values + convolution(values))) * mask
            )
        # Shared summaries retain each opponent's pre/post-riichi history.
        # Empty rivers remain identical regardless of their storage slot.
        local = tf.concat(
            [
                tf.math.divide_no_nan(
                    tf.reduce_sum(values, axis=1),
                    tf.reduce_sum(mask, axis=1),
                ),
                tf.where(
                    tf.reduce_any(mask > 0, axis=1),
                    tf.reduce_max(tf.where(mask > 0, values, -1e4), axis=1),
                    tf.zeros_like(values[:, 0]),
                ),
            ],
            axis=-1,
        )
        occupied = tf.reduce_any(mask > 0, axis=1)
        maximum = tf.where(
            occupied,
            tf.reduce_max(tf.where(mask > 0, values, -1e4), axis=1),
            tf.zeros_like(values[:, 0]),
        )
        encoded = self.projection(
            tf.concat([tf.reshape(values, (-1, 32 * 64)), maximum], axis=-1)
        ) * tf.cast(occupied, self.compute_dtype)
        return (
            tf.reshape(encoded, (-1, 384)),
            tf.reshape(local, (-1, 3, 256)),
        )


def projected_draws(inputs, selected):
    """Ordinary draw counts and last drawer if this action takes effect."""
    remaining = tf.cast(
        tf.gather(inputs["live_wall_count"], selected[:, 0]), tf.int32
    ) - tf.cast(selected[:, 1] >= 261, tf.int32)
    source = tf.where(
        (tf.gather(inputs["decision_phase"], selected[:, 0]) == 1)
        & (selected[:, 1] == 111),
        tf.cast(tf.gather(inputs["trigger_source"], selected[:, 0]), tf.int32),
        0,
    )
    return tf.stack(
        [
            tf.cast(
                (
                    remaining[:, None]
                    + 3
                    - (tf.range(4)[None] - source[:, None] - 1) % 4
                )
                // 4,
                tf.float32,
            ),
            tf.one_hot((source + remaining) % 4, 4)
            * tf.cast(remaining > 0, tf.float32)[:, None],
        ],
        axis=-1,
    )


def last_draw_context(inputs, selected):
    """Current last-tile flags and projected seats without further calls.

    Seat projections describe ordinary live-wall draws, excluding rinshan.
    A kan consumes one live-wall tile for its replacement draw. A response
    pass continues after the discarder; our chii/pon continues after us.
    """
    wall = tf.cast(
        tf.gather(inputs["live_wall_count"], selected[:, 0]), tf.int32
    )
    response = tf.gather(inputs["decision_phase"], selected[:, 0]) == 1
    source = tf.cast(
        tf.gather(inputs["trigger_source"], selected[:, 0]), tf.int32
    )
    return tf.concat(
        [
            tf.cast(
                tf.stack(
                    [
                        (wall == 0)
                        & (
                            tf.gather(
                                inputs["current_draw_valid"], selected[:, 0]
                            )
                            > 0
                        )
                        & (
                            tf.gather(inputs["rinshan_state"], selected[:, 0])
                            == 0
                        ),
                        (wall == 0) & response,
                    ],
                    axis=-1,
                ),
                tf.float32,
            ),
            tf.one_hot((tf.where(response, source, 0) + wall) % 4, 4)
            * tf.cast(wall > 0, tf.float32)[:, None],
            projected_draws(inputs, selected)[..., 1],
        ],
        axis=-1,
    )


@tf.keras.utils.register_keras_serializable(package="nejimakidori")
class DecisionCandidates(tf.keras.layers.Layer):
    """295 choices: discard 37, riichi 74, response 149, kan 35."""

    def __init__(self, **kwargs):
        super().__init__(**{**kwargs, "autocast": False})
        self.context = tf.keras.layers.Dense(
            192, activation="gelu", dtype=self.dtype_policy
        )
        self.projection = tf.keras.layers.Dense(
            384, activation="gelu", dtype=self.dtype_policy
        )

    def build(self, input_shape):
        self.context.build(input_shape[2])
        self.projection.build((None, input_shape[1][-1] + 260))
        super().build(input_shape)

    def call(self, values):
        inputs, bank, board = values
        batch = tf.shape(board)[0]
        indices = actions.candidate_hand_indices(inputs)
        cuts = tf.broadcast_to(tf.range(37)[None], (batch, 37))
        tiles = tf.concat(
            [
                cuts,
                cuts,
                cuts,
                tf.fill((batch, 1), 37),
                tf.broadcast_to(tf.tile(tf.range(37), [4])[None], (batch, 148)),
                tf.fill((batch, 1), 37),
                tf.broadcast_to(tf.range(34)[None], (batch, 34)),
            ],
            axis=1,
        )
        discard_values = tf.concat(
            [
                tf.cast(
                    inputs["discard_action_all_shanten"][..., None], tf.float32
                ),
                tf.cast(
                    inputs["discard_action_all_ukeire_count"][..., None],
                    tf.float32,
                ),
            ],
            axis=-1,
        )
        calls = []
        for kind, count in (("chi", 111), ("pon", 37)):
            calls.append(
                tf.concat(
                    [
                        tf.cast(
                            tf.reshape(
                                inputs[kind + "_discard_shanten"],
                                (-1, count, 1),
                            ),
                            tf.float32,
                        ),
                        tf.cast(
                            tf.reshape(
                                inputs[kind + "_discard_ukeire_count"],
                                (-1, count, 1),
                            ),
                            tf.float32,
                        ),
                    ],
                    axis=-1,
                )
            )
        structural = tf.concat(
            [
                discard_values,
                discard_values,
                discard_values,
                tf.zeros((batch, 1, 2)),
                *calls,
                tf.zeros((batch, 35, 2)),
            ],
            axis=1,
        )
        # Flags distinguish declaration, call kind and call option.
        flags = tf.constant(
            [[0, 0, 0]] * 37
            + [[1, declare, 0] for declare in range(2) for _ in range(37)]
            + [[2, 0, 0]]
            + [[3, 0, option] for option in range(3) for _ in range(37)]
            + [[4, 0, option] for option in range(1) for _ in range(37)]
            + [[6, 0, 0]]
            + [[5, 0, 0]] * 34,
            dtype=tf.float32,
        )
        structural = tf.concat(
            [
                structural,
                tf.reshape(inputs["action_win_value_range"], (batch, 295, 8)),
                tf.cast(
                    tf.reshape(
                        inputs["action_win_value_valid"], (batch, 295, 4)
                    ),
                    tf.float32,
                ),
                tf.cast(inputs["action_value_eligible"][..., None], tf.float32),
                tf.cast(inputs["action_open_yaku_restricted"], tf.float32),
            ],
            axis=-1,
        )
        masks = actions.legal_choices(inputs)
        selected = tf.cast(
            tf.where(
                tf.concat(
                    [
                        masks["discard_policy_logits"],
                        masks["riichi_policy_logits"],
                        masks["response_policy_logits"][:, :149],
                        masks["kan_action_logits"],
                    ],
                    axis=1,
                )
            ),
            tf.int32,
        )
        return (
            self.projection(
                tf.concat(
                    [
                        tf.cast(value, self.compute_dtype)
                        for value in [
                            tf.gather_nd(
                                bank,
                                tf.stack(
                                    [
                                        selected[:, 0],
                                        tf.cast(
                                            tf.gather_nd(indices, selected),
                                            tf.int32,
                                        ),
                                    ],
                                    axis=1,
                                ),
                            ),
                            tf.one_hot(tf.gather_nd(tiles, selected), 38),
                            tf.math.asinh(tf.gather_nd(structural, selected)),
                            tf.gather(flags, selected[:, 1]),
                            last_draw_context(inputs, selected),
                            tf.gather(self.context(board), selected[:, 0]),
                        ]
                    ],
                    axis=-1,
                )
            ),
            selected,
            tf.concat(
                [
                    tf.gather_nd(structural, selected),
                    tf.cast(tf.gather_nd(tiles, selected), tf.float32)[:, None],
                ],
                axis=-1,
            ),
        )


def encode_inputs():
    inputs = {
        name: tf.keras.Input(
            shape=definition["shape"], dtype=definition["dtype"], name=name
        )
        for name, definition in _native_collection.INPUTS.items()
    }
    bank = HandBank(name="hand_bank")(inputs)
    rivers, critic_rivers = RiverEncoding(name="river_encoder")(inputs)
    encoded = [
        bank[:, 0],
        tf.keras.layers.GlobalAveragePooling1D()(bank),
        rivers,
        numeric_features([inputs[name] for name in BOARD_INPUTS]),
    ]
    hidden = BoardProjection(name="board_projection")(
        tf.keras.layers.Concatenate()(encoded)
    )
    for block in range(4):
        residual = tf.keras.layers.LayerNormalization(
            name=f"board_block_{block}_norm"
        )(hidden)
        residual = tf.keras.layers.Dense(
            1536, activation="gelu", name=f"board_block_{block}_expand"
        )(residual)
        residual = tf.keras.layers.Dense(
            512, name=f"board_block_{block}_contract"
        )(residual)
        hidden = tf.keras.layers.Add(name=f"board_block_{block}_add")(
            [hidden, residual]
        )
    hidden = tf.keras.layers.Dense(512, activation="gelu", name="board_state")(
        hidden
    )
    hidden = tf.keras.layers.LayerNormalization(
        center=False,
        scale=False,
        epsilon=1e-5,
        dtype="float32",
        name="board_state_normalized",
    )(hidden)
    candidates, selected, structure = DecisionCandidates(
        name="decision_candidates"
    )([inputs, bank, hidden])
    candidates = tf.keras.layers.LayerNormalization(
        center=False,
        scale=False,
        epsilon=1e-5,
        dtype="float32",
        name="candidate_state_normalized",
    )(candidates)
    return inputs, hidden, candidates, selected, structure, critic_rivers

"""Export the joint actor, board heads and action payment critic."""

import argparse
import hashlib
import json
import pathlib
import shutil

import numpy
import tensorflow as tf

from log_dataset import _native_collection, scoring, training_data
from model import actions, critic, joint_settlement
from model import network as joint_network
from model import outcomes


class ServingModel(tf.Module):
    def __init__(self, network):
        super().__init__()
        # Track weights without exporting Keras' training-only call signatures.
        self.network = self._no_dependency(network)
        self.parameters = [variable.value for variable in network.variables]

    @tf.function
    def policy(self, **features):
        outputs = self.network.actor(features, training=False)
        return {name: outputs[name] for name in actions.TRAIN_POLICY_HEADS}

    @tf.function
    def serve(self, **features):
        chunk_size = 4
        outputs = self.network.actor(features, training=False)
        encoded, state = self.network.candidate_context(features, outputs)
        active = critic.active_candidates(features, encoded["selected"])
        selected = tf.boolean_mask(encoded["selected"], active)
        state = tf.boolean_mask(state, active)
        public = joint_settlement.public_inputs(features)
        candidate_public = critic.public_inputs(features, selected)
        probability = tf.TensorArray(
            tf.float32,
            size=0,
            dynamic_size=True,
            element_shape=[
                None,
                len(scoring.CELLS),
                len(outcomes.PAYMENT_VALUES) + 4,
            ],
        )
        review_outcomes = tf.TensorArray(
            tf.float32, size=0, dynamic_size=True, element_shape=[None, 7]
        )
        final_ranks = tf.TensorArray(
            tf.float32, size=0, dynamic_size=True, element_shape=[None, 4]
        )
        points = tf.TensorArray(
            tf.float32, size=0, dynamic_size=True, element_shape=[None, 4]
        )
        settlement = tf.TensorArray(
            tf.float32, size=0, dynamic_size=True, element_shape=[None, 2, 5]
        )
        for begin in tf.range(0, tf.shape(selected)[0], chunk_size):
            rows = selected[begin : begin + chunk_size, 0]
            inputs = {
                "state": state[begin : begin + chunk_size],
                **{
                    name: tf.gather(value, rows)
                    for name, value in public.items()
                },
            }
            inputs.update(
                {
                    name: value[begin : begin + chunk_size]
                    for name, value in candidate_public.items()
                }
            )
            forecast = self.network.critic.joint_distributions(inputs)
            _, final_probability = joint_settlement.continuation_forecast(
                scores=forecast["joint_scores"],
                ranks=forecast["joint_ranks"],
                support=forecast["joint_support"],
                dealer=inputs["dealer"],
                hand_number=inputs["hand_number"],
                pot=inputs["pot"],
            )
            # Mutually exclusive endings from the actor's perspective.
            categories = tf.constant(
                [
                    (
                        6
                        if kind == 3 or (kind == 0 and mask.bit_count() == 3)
                        else (
                            2
                            if kind == 2 and draw & 1
                            else (
                                3
                                if kind == 2
                                else (
                                    1
                                    if mask & 1
                                    else (
                                        0
                                        if kind == 0 and payer == 0
                                        else 4 if kind == 1 else 5
                                    )
                                )
                            )
                        )
                    )
                    for kind, payer, mask, draw in joint_settlement.EVENTS
                ]
            )
            review_outcomes = review_outcomes.write(
                begin // chunk_size,
                tf.einsum(
                    "ns,nsc->nc",
                    tf.reduce_sum(forecast["joint_probability"], axis=-1),
                    tf.one_hot(
                        tf.gather(
                            categories, forecast["joint_support"][..., 5]
                        ),
                        7,
                    ),
                ),
            )
            probability = probability.write(
                begin // chunk_size, forecast["payment_probability"]
            )
            final_ranks = final_ranks.write(
                begin // chunk_size,
                joint_settlement.expectation(
                    forecast["joint_probability"], final_probability
                ),
            )
            points = points.write(
                begin // chunk_size,
                joint_settlement.expectation(
                    forecast["joint_probability"],
                    forecast["joint_scores"] - inputs["scores"][:, None, None],
                ),
            )
            settlement = settlement.write(
                begin // chunk_size,
                tf.stack(joint_settlement.settlement_moments(forecast), axis=1),
            )
        probability = probability.concat()
        weights = tf.gather_nd(
            critic.candidate_probabilities(features, outputs), selected
        )
        count = tf.shape(features["decision_phase"])[0]
        tf.debugging.assert_near(
            tf.math.unsorted_segment_sum(weights, selected[:, 0], count),
            tf.ones(count),
            atol=1e-5,
        )
        mixture = tf.math.unsorted_segment_sum(
            probability * weights[:, None, None], selected[:, 0], count
        )
        moments = tf.math.unsorted_segment_sum(
            settlement.concat() * weights[:, None, None], selected[:, 0], count
        )
        return {
            **{name: outputs[name] for name in actions.SERVING_ACTOR_OUTPUTS},
            "payment_values": joint_settlement.payment_values(public),
            "final_placement_probabilities": tf.math.unsorted_segment_sum(
                final_ranks.concat() * weights[:, None], selected[:, 0], count
            ),
            "review_outcome_probabilities": tf.math.unsorted_segment_sum(
                review_outcomes.concat() * weights[:, None],
                selected[:, 0],
                count,
            ),
            "settlement_mean": moments[:, 0],
            "settlement_variance": tf.maximum(
                moments[:, 1] - moments[:, 0] ** 2, 0
            ),
            "critic_expected_points": points.concat(),
            "terminal_payment_probabilities": tf.einsum(
                "ncv,ctpr->ntprv",
                mixture,
                tf.constant(
                    numpy.eye(64, dtype=numpy.float32)[
                        numpy.ravel_multi_index(
                            numpy.array(scoring.CELLS).T, (4, 4, 4)
                        )
                    ].reshape(-1, 4, 4, 4)
                ),
            )
            + tf.cast(~tf.constant(outcomes.PAYMENT_CELLS), tf.float32)[
                None, ..., None
            ]
            * tf.one_hot(1, len(outcomes.PAYMENT_VALUES) + 4),
            "critic_action_indices": selected,
        }


def build_network(inputs):
    """Build every actor and critic variable before strict weight loading."""
    network = joint_network.JointPolicyPayment()
    outputs = network.actor(inputs, training=False)
    encoded, state = network.candidate_context(inputs, outputs)
    network.critic.joint_distributions(
        {
            **{
                name: tf.gather(value, encoded["selected"][:1, 0])
                for name, value in joint_settlement.public_inputs(
                    inputs
                ).items()
            },
            "state": state[:1],
            **critic.public_inputs(inputs, encoded["selected"][:1]),
        }
    )
    network.built = True
    return network


def load_network(weights, inputs):
    network = build_network(inputs)
    network.load_weights(weights)
    network.compile_training()
    return network


def run(args):
    from training import frozen_policy, self_play

    for device in tf.config.list_physical_devices("GPU"):
        tf.config.experimental.set_memory_growth(device, True)
    if args.data is None:
        inputs = self_play.initial_features(args.self_play_seed)
    else:
        inputs = training_data.parse_batch(
            next(
                iter(
                    training_data.dataset(
                        root=args.data,
                        partition="train",
                        batch_size=8,
                    )
                )
            )
        )[0]
    network = load_network(args.weights, inputs)
    module = ServingModel(network)
    signature = module.serve.get_concrete_function(
        **{
            name: tf.TensorSpec(
                [None, *definition["shape"]], definition["dtype"], name=name
            )
            for name, definition in _native_collection.INPUTS.items()
        }
    )
    root = pathlib.Path(args.output)
    pending = root.with_name(root.name + ".pending")
    if pending.exists():
        shutil.rmtree(pending)
    pending.mkdir(parents=True)
    tf.saved_model.save(
        module,
        str(pending / "saved_model"),
        signatures={
            "serving_default": signature,
            "policy": module.policy.get_concrete_function(
                **signature.structured_input_signature[1]
            ),
        },
    )
    loaded = tf.saved_model.load(str(pending / "saved_model"))
    actual = loaded.signatures["serving_default"](**inputs)
    expected = module.serve(**inputs)
    policy = loaded.signatures["policy"](**inputs)
    for name, value in policy.items():
        numpy.testing.assert_allclose(value, actual[name], rtol=1e-5, atol=1e-5)
    errors = {}
    for name in expected:
        numpy.testing.assert_allclose(
            actual[name], expected[name], rtol=1e-5, atol=1e-5
        )
        errors[name] = float(
            tf.reduce_max(tf.abs(actual[name] - expected[name]))
        )
    for name in (
        "terminal_payment_probabilities",
        "review_outcome_probabilities",
        "final_placement_probabilities",
    ):
        numpy.testing.assert_allclose(
            tf.reduce_sum(actual[name], -1), 1, rtol=1e-4, atol=1e-5
        )
    for value in actual.values():
        assert numpy.isfinite(value.numpy()).all()
    with pathlib.Path(args.weights).open("rb") as stream:
        weight_hash = hashlib.file_digest(stream, "sha256").hexdigest()
    (pending / "export-verification.json").write_text(
        json.dumps(
            {
                "passed": True,
                "weights": str(args.weights),
                "weight_sha256": weight_hash,
                "data": str(args.data),
                "output_max_errors": errors,
                "critic_candidates": int(
                    tf.shape(actual["critic_action_indices"])[0]
                ),
                "payment_forecast": "active_policy_mixture_honba_free",
                "policy_signature_matches_full_export": True,
            },
            indent=2,
        )
        + "\n"
    )

    for name in ("model", "training", "log_dataset"):
        frozen_policy.freeze_source(
            pathlib.Path(__file__).parents[1] / name,
            pending / "source" / name,
        )
    shutil.copy2(
        pathlib.Path(__file__).parents[1] / "requirements.txt",
        pending / "source/requirements.txt",
    )
    pending.rename(root)


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--weights", required=True)
    source = parser.add_mutually_exclusive_group(required=True)
    source.add_argument("--data")
    source.add_argument("--self-play-seed", type=int)
    parser.add_argument("--output", required=True)
    run(parser.parse_args())


if __name__ == "__main__":
    main()

"""Validated SavedModel inference shared by HTTP and local callers."""

import dataclasses
import hashlib
import pathlib
import time

import numpy
import tensorflow as tf

from log_dataset import _native_collection, scoring, shanten
from model import actions, outcomes


@dataclasses.dataclass
class Inference:
    predictions: list
    latency_ms: float
    metadata: dict
    outputs: dict

    def as_dict(self):
        return {
            "predictions": self.predictions,
            "latency_ms": self.latency_ms,
            "metadata": self.metadata,
        }


class Predictor:
    max_batch_size = 256

    def __init__(self, saved_model):
        self.model_path = pathlib.Path(saved_model)
        self.module = tf.saved_model.load(str(saved_model))
        self.function = self.module.signatures["serving_default"]
        self.input_specs = {
            name: (tuple(value["shape"]), value["dtype"])
            for name, value in _native_collection.INPUTS.items()
        }
        signature = self.function.structured_input_signature[1]
        if signature.keys() != self.input_specs.keys() or any(
            spec.shape.as_list() != [None, *self.input_specs[name][0]]
            or spec.dtype != tf.as_dtype(self.input_specs[name][1])
            for name, spec in signature.items()
        ):
            raise ValueError("SavedModel inputs do not match feature producer")
        self.output_specs = self.function.structured_outputs
        expected = {
            **actions.SERVING_ACTOR_OUTPUTS,
            "terminal_payment_probabilities": [
                4,
                4,
                4,
                len(outcomes.PAYMENT_VALUES) + 4,
            ],
            "payment_values": [len(outcomes.PAYMENT_VALUES) + 4],
            "final_placement_probabilities": [4],
            "review_outcome_probabilities": [7],
            "settlement_mean": [5],
            "settlement_variance": [5],
            "critic_expected_points": [4],
            "critic_action_indices": [2],
        }
        if self.output_specs.keys() != expected.keys():
            raise ValueError("SavedModel must include joint actor and critic")
        for name, shape in expected.items():
            dtype = tf.int32 if name == "critic_action_indices" else tf.float32
            if (
                self.output_specs[name].shape.as_list() != [None, *shape]
                or self.output_specs[name].dtype != dtype
            ):
                raise ValueError(f"Incorrect serving output contract: {name}")
        digest = hashlib.sha256()
        for path in sorted(self.model_path.rglob("*")):
            if path.is_file():
                digest.update(str(path.relative_to(self.model_path)).encode())
                with path.open("rb") as source:
                    while block := source.read(1024 * 1024):
                        digest.update(block)
        self.metadata = {
            "revision": digest.hexdigest(),
            "model_contract": "joint_policy_payment_critic",
            "payment_forecast": "active_policy_mixture_honba_free",
            "payment_events": "coexisting_ron_claims_tsumo_exhaustive_abort",
            "bank_payment": "accepted_deposits_and_priority_pot_award",
            "critic_action_ranges": {
                "discard": [0, 37],
                "riichi": [37, 111],
                "response_without_daiminkan": [111, 260],
                "kan": [260, 295],
            },
            "daiminkan_action": "261 + trigger_tile_id",
            "payment_types": list(outcomes.PAYMENT_TYPES),
            "tile_names": list(shanten.TILE_NAMES),
            "completion_yaku_names": list(scoring.NAMES),
            "completion_modes": ["ron", "tsumo"],
            "completion_score_states": list(outcomes.SCORE_STATES),
            "opponent_tile_target": "structural_ukeire_by_shanten",
            "opponent_shanten_classes": [0, 1, 2, "3+"],
            "opponent_wait_target": "joint_tenpai_and_structural_wait",
        }

    def tensors(self, instances):
        if (
            not isinstance(instances, list)
            or not 1 <= len(instances) <= self.max_batch_size
        ):
            raise ValueError(
                f"instances must contain 1 to {self.max_batch_size} "
                "feature objects"
            )
        for instance in instances:
            if (
                not isinstance(instance, dict)
                or instance.keys() != self.input_specs.keys()
            ):
                raise ValueError("feature keys do not match model contract")
            for name, (shape, dtype) in self.input_specs.items():
                if numpy.asarray(instance[name]).shape != shape:
                    raise ValueError(
                        f"incorrect shape for {name}: expected {shape}"
                    )
            if int(instance["decision_phase"]) not in (0, 1, 2, 3, 4):
                raise ValueError("Inference requires a discretionary decision")
        return {
            name: tf.convert_to_tensor(
                [row[name] for row in instances], dtype=dtype
            )
            for name, (_, dtype) in self.input_specs.items()
        }

    def predict(self, **features):
        return self.function(**features)

    def infer(self, instances):
        start = time.perf_counter()
        outputs = self.predict(**self.tensors(instances))
        probabilities = {}
        for name, logits in outputs.items():
            if not name.endswith("logits"):
                continue
            probabilities[name.replace("logits", "probabilities")] = (
                tf.nn.softmax(logits, -1).numpy()
            )
        probabilities["terminal_payment_probabilities"] = outputs[
            "terminal_payment_probabilities"
        ].numpy()
        probabilities["final_placement_probabilities"] = outputs[
            "final_placement_probabilities"
        ].numpy()
        probabilities["review_outcome_probabilities"] = outputs[
            "review_outcome_probabilities"
        ].numpy()
        payment_values = outputs["payment_values"].numpy()
        action_points = outputs["critic_expected_points"].numpy()
        selected = outputs["critic_action_indices"].numpy()
        settlement_mean = outputs["settlement_mean"].numpy()
        settlement_variance = outputs["settlement_variance"].numpy()
        predictions = []
        for index in range(len(instances)):
            row = {
                name: values[index].tolist()
                for name, values in probabilities.items()
            }
            row["action_values"] = [
                {
                    "action": int(selected[action, 1]),
                    "expected_points": action_points[action].tolist(),
                }
                for action in numpy.flatnonzero(selected[:, 0] == index)
            ]
            row["structured_outcome"] = {
                "format": "typed_payments",
                "conditioning": "active_policy_mixture",
                "honba_included": False,
                "types": list(outcomes.PAYMENT_TYPES),
                "probabilities": row["terminal_payment_probabilities"],
                "values": payment_values[index].tolist(),
                "settlement_mean": settlement_mean[index].tolist(),
                "settlement_stddev": numpy.sqrt(
                    settlement_variance[index]
                ).tolist(),
                "uncertainty": "joint hand settlement",
            }
            predictions.append(row)
        return Inference(
            predictions,
            (time.perf_counter() - start) * 1000,
            self.metadata,
            outputs,
        )

"""Masked loss reductions shared across components and replicas."""

import tensorflow as tf


def constraint_divergence(raw, constrained, binary=False):
    """Teach raw predictions the projection, without moving its target."""
    constrained = tf.stop_gradient(tf.cast(constrained, tf.float32))
    raw = tf.cast(raw, tf.float32)
    if binary:
        target = tf.sigmoid(constrained)
        divergence = tf.nn.sigmoid_cross_entropy_with_logits(
            labels=target, logits=raw
        ) - tf.nn.sigmoid_cross_entropy_with_logits(
            labels=target, logits=constrained
        )
        return tf.reduce_mean(divergence, -1)
    target = tf.nn.log_softmax(constrained)
    return tf.reduce_sum(tf.exp(target) * (target - tf.nn.log_softmax(raw)), -1)


@tf.keras.utils.register_keras_serializable(package="nejimakidori")
class ConstraintLoss(tf.keras.layers.Layer):
    def __init__(self, binary=False, **kwargs):
        super().__init__(**kwargs)
        self.binary = binary

    def get_config(self):
        return {**super().get_config(), "binary": self.binary}

    def call(self, values):
        penalty = constraint_divergence(*values[:2], binary=self.binary)
        penalty = tf.reduce_mean(
            penalty, axis=tuple(range(1, penalty.shape.rank))
        )
        if len(values) == 3:
            # Sparse candidate outputs contribute equal mass per decision.
            return tf.math.divide_no_nan(
                tf.math.segment_sum(penalty, values[2]),
                tf.math.segment_sum(tf.ones_like(penalty), values[2]),
            )
        return penalty


def masked_totals(loss, mask, weight=None):
    mask = tf.cast(mask, tf.float32)
    if weight is not None:
        mask *= tf.cast(weight, tf.float32)
    return tf.stack(
        [tf.reduce_sum(tf.cast(loss, tf.float32) * mask), tf.reduce_sum(mask)]
    )


def mean_valid(loss, mask, weight=None):
    numerator, denominator = tf.unstack(masked_totals(loss, mask, weight))
    replica = tf.distribute.get_replica_context()
    if replica is not None:
        numerator = replica.all_reduce(tf.distribute.ReduceOp.SUM, numerator)
        denominator = replica.all_reduce(
            tf.distribute.ReduceOp.SUM, denominator
        )
    return tf.math.divide_no_nan(numerator, denominator)


def candidate_mean(loss, mask, rows, mean=mean_valid):
    """Equal decision mass over valid candidate/head entries.

    Rows are the sorted decision IDs returned by DecisionCandidates. Unknown
    candidates contribute neither loss nor normalization mass.
    """
    mask = tf.cast(mask, tf.float32)
    totals = tf.math.segment_sum(
        tf.stack(
            [
                tf.reduce_sum(tf.cast(loss, tf.float32) * mask, axis=-1),
                tf.reduce_sum(mask, axis=-1),
            ],
            axis=-1,
        ),
        rows,
    )
    return mean(
        tf.math.divide_no_nan(totals[:, 0], totals[:, 1]), totals[:, 1] > 0
    )


def packed_means(statistics):
    """Reduce masked statistics using TensorFlow's distributed autodiff."""
    replica = tf.distribute.get_replica_context()
    if replica is not None:
        statistics = replica.all_reduce(tf.distribute.ReduceOp.SUM, statistics)
    return tf.math.divide_no_nan(statistics[:, 0], statistics[:, 1])


def classification(labels, logits, weight=None, mean=mean_valid):
    labels = tf.cast(labels, tf.int32)
    return mean(
        tf.nn.sparse_softmax_cross_entropy_with_logits(
            labels=tf.maximum(labels, 0), logits=tf.cast(logits, tf.float32)
        ),
        labels >= 0,
        weight,
    )

"""Assembly of the shared actor, beliefs and payment critic."""

import tensorflow as tf

from model import actor as actor_layers
from model import beliefs, critic, encoder, joint_settlement, payment_scoring


class JointPolicyPayment(tf.keras.Model):
    """Shared policy, beliefs, auxiliaries and payment critic."""

    def __init__(self):
        super().__init__(autocast=False)
        tf.keras.mixed_precision.set_global_policy("mixed_bfloat16")
        inputs, board, candidates, selected, structure, critic_rivers = (
            encoder.encode_inputs()
        )
        self.beliefs = beliefs.OpponentBeliefs(
            encoder=tf.keras.Model(
                inputs, board, name="belief_encoder", autocast=False
            ),
        )
        belief_logits = self.beliefs(inputs, hidden=board)
        belief_probability = beliefs.Probabilities(dtype="float32")(
            belief_logits
        )
        encoded = {
            "candidate": candidates,
            "board": board,
            "selected": selected,
            "structure": structure,
            "critic_rivers": critic_rivers,
            **belief_logits,
            "belief_context": tf.keras.layers.Concatenate(dtype="float32")(
                [
                    tf.keras.layers.Flatten(dtype="float32")(
                        belief_probability[name]
                    )
                    for name in beliefs.BELIEF_HEADS
                ]
            ),
        }
        tf.keras.mixed_precision.set_global_policy("float32")
        self.context = critic.HandContext(dtype="float32")
        self.public = critic.PublicContext(dtype="float32")
        self.player_context = critic.PlayerContext(dtype="float32")
        self.critic = critic.PaymentCritic(
            belief_offset=candidates.shape[-1],
            player_width=self.player_context(
                [inputs, critic_rivers, selected]
            ).shape[-1],
        )

        outputs, context = actor_layers.build_board_heads(
            inputs=inputs,
            hidden=board,
            belief_probability=belief_probability,
        )
        outputs.update(
            actor_layers.build_policy_heads(
                inputs=inputs,
                hidden=encoded["board"],
                candidates=encoded["candidate"],
                selected=encoded["selected"],
                context=context,
            )
        )
        outputs.update(
            actor_layers.PolicySummaries(dtype="float32")(
                {**outputs, **belief_logits}
            )
        )
        outputs["constraint_loss"] = tf.keras.layers.Add(dtype="float32")(
            [
                encoded["belief_constraint_loss"],
                outputs["route_constraint_loss"],
                outputs["round_completion_yaku_logits_constraint_loss"],
                outputs["round_completion_score_logits_constraint_loss"],
            ]
        )
        # Auxiliary heads have visible-route and hindsight targets.
        # Only predictions enter the actor; labels stay in the trainer.
        self.actor = tf.keras.Model(inputs, {**outputs, **encoded})
        # Rollout encoding and serving use the same yaku-conditioned critic.
        self.encoder = tf.keras.Model(
            inputs,
            {
                **encoded,
                "route_affinity_logits": outputs["route_affinity_logits"],
                "round_completion_yaku_logits": outputs[
                    "round_completion_yaku_logits"
                ],
                "round_completion_score_logits": outputs[
                    "round_completion_score_logits"
                ],
            },
        )

    def compile_training(self):
        """Call after initialization so tracing binds live Keras variables."""
        self.critic.distributions = tf.function(
            self.critic.distributions, jit_compile=True
        )
        self.critic.joint_distributions = tf.function(
            self.critic.joint_distributions, jit_compile=True
        )
        self.critic.chunk_statistics = tf.function(
            self.critic.chunk_statistics, jit_compile=True
        )
        self.critic.chunk_gradients = tf.function(
            self.critic.chunk_gradients, jit_compile=True
        )
        self.critic.candidate_chunk = tf.function(
            self.critic.candidate_chunk, jit_compile=True
        )
        self.critic.supervised_statistics = tf.function(
            self.critic.supervised_statistics
        )
        for block in self.encoder.get_layer("hand_bank").suits:
            block.call = tf.function(block.call, jit_compile=True)
        river = self.encoder.get_layer("river_encoder")
        river.encode = tf.function(river.encode, jit_compile=True)
        self.beliefs.tile_attention.call = tf.function(
            self.beliefs.tile_attention.call, jit_compile=True
        )

    def candidate_context(self, features, encoded):
        state = tf.concat(
            [
                encoded["candidate"],
                tf.gather(encoded["belief_context"], encoded["selected"][:, 0]),
                tf.gather(encoded["board"], encoded["selected"][:, 0]),
                self.context(
                    [features, encoded["selected"], encoded["structure"]]
                ),
                self.public(
                    [features, encoded["selected"], encoded["structure"]]
                ),
            ],
            axis=-1,
        )
        return encoded, tf.concat(
            [
                state,
                tf.sigmoid(encoded["route_affinity_logits"]),
                tf.reshape(
                    tf.gather(
                        tf.sigmoid(encoded["round_completion_yaku_logits"]),
                        encoded["selected"][:, 0],
                    ),
                    (-1, 4 * 2 * 23),
                ),
                tf.reshape(
                    tf.gather(
                        tf.nn.softmax(encoded["round_completion_score_logits"]),
                        encoded["selected"][:, 0],
                    ),
                    (-1, 4 * 2 * len(payment_scoring.SCORES)),
                ),
                tf.reshape(
                    self.player_context(
                        [
                            features,
                            encoded["critic_rivers"],
                            encoded["selected"],
                        ]
                    ),
                    (-1, 4 * self.critic.player_width),
                ),
            ],
            axis=-1,
        )

    def call(self, inputs):
        outputs = self.actor(inputs[0])
        # Reuse the actor encoder output for critic supervision.
        encoded, state = self.candidate_context(inputs[0], outputs)
        return {
            **outputs,
            **self.supervised_outputs(inputs, encoded, state),
        }

    def chosen_inputs(self, features, encoded, state, chosen):
        """One observed action per row, with the shared transition contract."""
        recorded = (
            tf.gather(chosen, encoded["selected"][:, 0])
            == encoded["selected"][:, 1]
        )
        tf.debugging.assert_equal(
            tf.boolean_mask(encoded["selected"][:, 0], recorded),
            tf.range(tf.shape(chosen)[0]),
        )
        selected = tf.boolean_mask(encoded["selected"], recorded)
        return {
            **joint_settlement.public_inputs(features),
            "state": tf.boolean_mask(state, recorded),
            **critic.public_inputs(features, selected),
        }

    def supervised_outputs(self, inputs, encoded, state):
        features, labels, _ = inputs
        recorded_inputs = self.chosen_inputs(
            features, encoded, state, critic.chosen_actions(features, labels)
        )
        if not self.critic.built:
            self.critic(
                {name: value[:1] for name, value in recorded_inputs.items()}
            )
        return {
            "critic_statistics": self.critic.supervised_statistics(
                recorded_inputs, inputs[2]
            )
        }

"""Stable hand payments, score conservation and initial-dealer tie priority."""

import numpy

PAYMENT_TYPES = ("ron", "tsumo", "draw", "bank")
SAINT3_JADE_SOUTH_OFFSETS = (125, 60, -5, -255)
OBJECTIVE_ST3_SCALE = 100.0
PAYMENT_CELLS = numpy.array(
    [
        [
            [
                payer == recipient if kind == "bank" else payer != recipient
                for recipient in range(4)
            ]
            for payer in range(4)
        ]
        for kind in PAYMENT_TYPES
    ]
)


# Scoring states are hand values, never payer-specific point amounts.
# 20/25 fu require at least two han; sub-mangan hands stop at 110 fu.
# Fu-capped mangan (3 han 70+ fu, 4 han 40+ fu) shares the limit tier.
# Limit hands use representative han: mangan, haneman, baiman, sanbaiman,
# kazoe. Named yakuman count once; at most four distinct families can stack
# in the native four-player rules (double-value variants are normalized).
SCORE_STATES = (
    tuple(
        (han, fu)
        for han in range(1, 5)
        for fu in (20, 25, *range(30, 111, 10))
        if (han >= 2 or fu >= 30) and fu * 2 ** (han + 2) < 2000
    )
    + tuple((han, 0) for han in (5, 6, 8, 11, 13))
    + tuple((0, count) for count in range(1, 5))
)


def basic_points(han, fu):
    if han >= 13:
        return 8000
    if han >= 11:
        return 6000
    if han >= 8:
        return 4000
    if han >= 6:
        return 3000
    if han >= 5:
        return 2000
    return min(2000, fu * 2 ** (han + 2))


# Derived monetary alphabet, including exhaustive draws and pao shares.
# Bank awards also have four public-state atoms; records store raw amounts.
PAYMENT_VALUES = numpy.array(
    sorted(
        {-1000, 0, 750, 1000, 1500, 3000}
        | {
            4000 * count * factor
            for count in range(1, 5)
            for factor in (1, 2, 3, 4, 6, 8, 12)
        }
        | {
            100
            * (
                (
                    factor * (8000 * fu if han == 0 else basic_points(han, fu))
                    + 99
                )
                // 100
            )
            for han, fu in SCORE_STATES
            for factor in (1, 2, 4, 6)
        }
    ),
    dtype=numpy.int32,
)


def saint3_jade_south(scores, ranks):
    """Final ST3 return, with one-based ranks and scores in table points."""
    return numpy.ceil(
        (numpy.asarray(scores) - 25000) / 1000
        + numpy.asarray(SAINT3_JADE_SOUTH_OFFSETS)[numpy.asarray(ranks) - 1]
    ).astype(numpy.int32)


def score_ranks(scores, first_dealer=0):
    order = sorted(
        range(4), key=lambda seat: (-scores[seat], (seat - first_dealer) % 4)
    )
    return tuple(order.index(seat) + 1 for seat in range(4))


def normalize_draw_payments(events):
    """Remove native draw deltas' already-paid riichi deposits.

    Nagashi and zero-transfer exhaustive draws can retain the per-seat
    deposit delta. MJAI reach_accepted already accounts for that payment.
    Accept only the observed, conservation-checked native defect.
    """
    for event in events:
        if event["type"] == "start_kyoku":
            deposits = [0] * 4
        elif event["type"] == "reach_accepted":
            deposits[event["actor"]] += 1000
        elif event["type"] == "ryukyoku" and sum(event["deltas"]):
            corrected = [
                delta + deposit
                for delta, deposit in zip(event["deltas"], deposits)
            ]
            if sum(corrected) or not (
                event["reason"] == "nagashimangan"
                or (
                    event["reason"] == "exhaustive_draw"
                    and corrected == [0] * 4
                )
            ):
                raise ValueError(f"Invalid native draw payment: {event}")
            event["deltas"] = corrected


def terminal_payments(events):
    """Typed ron/tsumo/draw/bank transfers, without honba, including pao."""
    result = numpy.zeros((len(PAYMENT_TYPES), 4, 4), dtype=numpy.int32)
    honba = 0
    for event in events:
        if event["type"] == "start_kyoku":
            honba = event.get("honba", 0)
        elif event["type"] == "reach_accepted":
            result[3, event["actor"], event["actor"]] -= 1000
        elif event["type"] == "hora":
            winner = event["actor"]
            delta = event["deltas"]
            payers = [seat for seat in range(4) if delta[seat] < 0]
            for payer in payers:
                if event["target"] == winner:
                    # Tenhou pao tsumo charges one seat all three shares.
                    bonus = 300 * honba // len(payers)
                else:
                    # Split pao ron charges honba only to the liable seat,
                    # which is the payer other than the discarder.
                    bonus = (
                        300
                        * honba
                        * (len(payers) == 1 or payer != event["target"])
                    )
                result[int(event["target"] == winner), payer, winner] += (
                    -delta[payer] - bonus
                )
            result[3, winner, winner] += sum(delta)
            honba = 0
        elif event["type"] == "ryukyoku":
            delta = numpy.array(event["deltas"])
            losers = numpy.flatnonzero(delta < 0)
            winners = numpy.flatnonzero(delta > 0)
            for loser in losers:
                for winner in winners:
                    result[2, loser, winner] += -delta[loser] // len(winners)
    return result


def settlement(payments):
    payments = numpy.asarray(payments).sum(axis=0)
    diagonal = numpy.diag(payments)
    return numpy.r_[
        payments.sum(0) - payments.sum(1) + diagonal, -diagonal.sum()
    ]


def relative_payments(payments, actor, accepted_riichi):
    order = [(actor + offset) % 4 for offset in range(4)]
    result = numpy.asarray(payments)[:, order][:, :, order].copy()
    result[3] += numpy.diag(numpy.asarray(accepted_riichi)[order]) * 1000
    return result


def terminal_scores(events):
    return (
        numpy.asarray(events[0]["scores"])
        + sum(
            (
                numpy.asarray(event["deltas"])
                for event in events
                if "deltas" in event
            ),
            numpy.zeros(4, dtype=int),
        )
        - 1000
        * numpy.bincount(
            [
                event["actor"]
                for event in events
                if event["type"] == "reach_accepted"
            ],
            minlength=4,
        )
    )


def payment_classes(payments):
    values = numpy.asarray(payments)
    matches = values[..., None] == PAYMENT_VALUES
    if not matches.any(-1).all():
        raise ValueError(
            "payment is outside the declared classes: "
            f"{numpy.unique(values[~matches.any(-1)]).tolist()}"
        )
    return matches.argmax(-1)

"""Paired current-hand outcomes at selected frozen-policy decisions."""

import numpy
import tensorflow as tf

from log_dataset import _native_collection, training_data
from model import actor as actor_layers
from model import critic, outcomes
from training import self_play, trainer

CATEGORIES = (
    "disagreement",
    "tenpai",
    "keiten",
    "calls",
    "riichi",
    "threat",
    "sakigiri",
)


def root_scorer(network):
    """Return discard Q values, with illegal choices excluded from max-Q."""
    specs = {
        name: tf.TensorSpec([None, *spec["shape"]], spec["dtype"])
        for name, spec in _native_collection.INPUTS.items()
    }
    packing = training_data.PackedBatch(specs)

    @tf.function(reduce_retracing=True)
    def predict(inputs):
        features = packing.unpack(inputs)
        outputs, state = network.candidate_context(
            features, network.actor(features, training=False)
        )
        selected = critic.active_candidates(features, outputs["selected"])
        values = trainer.action_values(
            network=network,
            features=features,
            selected=tf.boolean_mask(outputs["selected"], selected),
            state=tf.boolean_mask(state, selected),
            chunk_size=32,
        )[:, :37]
        return tf.where(
            tf.cast(features["discard_action_legal"], tf.bool),
            values,
            -float("inf"),
        )

    def evaluate(features):
        # Stable encoder shapes avoid recompiling for each sampled root count.
        packed = packing.pack_numpy(features)
        count = len(features["decision_phase"])
        # Small self-play requests need small buckets, not 64 padded roots.
        chunk_size = min(64, 1 << (count - 1).bit_length())
        outputs = []
        for begin in range(0, count, chunk_size):
            indices = numpy.minimum(
                numpy.arange(begin, begin + chunk_size), count - 1
            )
            with tf.device("/CPU:0"):
                inputs = {
                    name: tf.convert_to_tensor(value[indices])
                    for name, value in packed.items()
                }
            outputs.append(
                predict(inputs).numpy()[: min(chunk_size, count - begin)]
            )
        return numpy.concatenate(outputs)

    return evaluate


def action_pair(features, head, legal, policy, category, preferred):
    """Compare the policy choice with a publicly identifiable alternative."""
    codes = numpy.flatnonzero(legal)
    if category == "calls":
        if head not in (2, 3):
            return None
        improving = self_play.improving_call_choices(features)[head - 2]
        alternatives = codes[improving[codes]]
        if preferred != 0 and not improving[preferred]:
            return None
        if preferred != 0:
            return preferred, 0
    elif head not in (0, 1):
        return None
    elif category == "disagreement":
        # The discard-only critic scorer resolves this proposal after mining.
        return (preferred, -1) if head == 0 else None
    elif category in ("tenpai", "keiten"):
        distance = min(
            int(features[name])
            for name in (
                "normal_self_shanten",
                "chiitoitsu_self_shanten",
                "kokushi_self_shanten",
            )
        )
        if category == "tenpai" and distance > 1:
            return None
        if category == "keiten" and (
            distance > 2 or features["live_wall_count"] > 16
        ):
            return None
        shanten = features["discard_action_all_shanten"][codes % 37]
        keep = shanten == shanten.min()
        alternatives = codes[keep != keep[codes == preferred][0]]
    elif category == "riichi":
        if head != 1:
            return None
        alternatives = codes[(codes >= 37) != (preferred >= 37)]
        counterpart = preferred + (37 if preferred < 37 else -37)
        if counterpart in alternatives:
            return preferred, counterpart
    elif category == "threat":
        threatening = (features["riichi_state"][1:] > 0) | (
            (
                (features["meld_valid"][1:] > 0)
                & (features["meld_type"][1:] != 3)
            ).sum(axis=1)
            >= 2
        )
        if not threatening.any():
            return None
        tiles = numpy.take(numpy.r_[numpy.arange(34), 4, 13, 22], codes % 37)
        safety = features["genbutsu_to_seat"][1:][threatening][:, tiles].sum(0)
        preferred_safety = safety[codes == preferred][0]
        alternatives = codes[
            (
                safety == safety.max()
                if preferred_safety < safety.max()
                else safety < preferred_safety
            )
        ]
    else:
        raise ValueError(f"Unknown correction category: {category}")
    if not len(alternatives):
        return None
    return preferred, int(alternatives[policy[alternatives].argmax()])


def snapshot(collector, batch, row, actions):
    """Own the decision buffers retained beyond the current collector step."""
    return {
        "snapshot": collector.snapshot(row),
        "features": batch["features"][row].copy(),
        "head": int(batch["head"][row]),
        "legal": batch["legal"][row].copy(),
        "actions": actions,
        "source": batch["indices"][row].copy(),
    }


def collect(predict, root_evaluate, games, seed, *, retain, discover):
    """Balance targeted starts with uniform normal starts from the same games.

    A category is assigned before mining. Normal reservoirs include every
    recoverable decision from all four seats, regardless of its category.
    Each targeted root is accompanied by one normal root from that game. Both get
    two continuations, and every rollout decision contributes to MMD.
    """
    generator = numpy.random.default_rng(seed + 1000000000)
    categories = (numpy.arange(games) + seed) % len(CATEGORIES)
    generator.shuffle(categories)
    proposals = {}
    normal = {}
    ordinary_seen = numpy.zeros(games, numpy.int64)
    seen = numpy.zeros(games, numpy.int64)

    def capture(collector, batch):
        with tf.device("/CPU:0"):
            preferred = actor_layers.greedy_choices(
                batch["behavior"], batch["head"]
            ).numpy()
        for row, game in enumerate(batch["indices"][:, 0]):
            ordinary_seen[game] += 1
            if generator.integers(ordinary_seen[game]) == 0:
                legal = numpy.flatnonzero(batch["legal"][row])
                probability = numpy.exp(
                    batch["behavior"][row, legal].astype(numpy.float64)
                )
                normal[int(game)] = snapshot(
                    collector,
                    batch,
                    row,
                    generator.choice(
                        legal, size=2, p=probability / probability.sum()
                    ),
                )
            if CATEGORIES[categories[game]] == "sakigiri":
                pair = batch["sakigiri_pair"][row]
                if batch["head"][row] != 0 or (pair < 0).any():
                    continue
                assert batch["legal"][row, pair].all()
            else:
                pair = action_pair(
                    features=batch["features"][row],
                    head=int(batch["head"][row]),
                    legal=batch["legal"][row],
                    policy=batch["behavior"][row],
                    category=CATEGORIES[categories[game]],
                    preferred=int(preferred[row]),
                )
            if pair is None:
                continue
            seen[game] += 1
            capacity = 8 if categories[game] == 0 else 1
            slot = (
                int(seen[game]) - 1
                if seen[game] <= capacity
                else int(generator.integers(seen[game]))
            )
            if slot >= capacity:
                continue
            root = snapshot(collector, batch, row, pair)
            retained = proposals.setdefault(int(game), [])
            if slot == len(retained):
                retained.append(root)
            else:
                retained[slot] = root

    statistics = discover(capture)
    roots = {
        game: retained[0]
        for game, retained in proposals.items()
        if categories[game] != 0
    }
    disagreement = [
        (game, root)
        for game in sorted(proposals)
        if categories[game] == 0
        for root in proposals[game]
    ]
    qualified = numpy.zeros(games, numpy.int64)
    if disagreement:
        features = numpy.array(
            [root["features"] for _, root in disagreement],
            dtype=self_play.FEATURE_DTYPE,
        )
        values = root_evaluate(
            {name: features[name] for name in features.dtype.names}
        )
        for row, (game, root) in enumerate(disagreement):
            preferred = root["actions"][0]
            best = int(values[row].argmax())
            gap = values[row, best] - values[row, preferred]
            if best == preferred or gap < 0.25 / outcomes.OBJECTIVE_ST3_SCALE:
                continue
            assert root["legal"][[preferred, best]].all()
            qualified[game] += 1
            if generator.integers(qualified[game]) == 0:
                root["actions"] = (preferred, best)
                roots[game] = root
    statistics["disagreement_scored"] = len(disagreement)
    statistics["disagreement_qualifying"] = int(qualified.sum())

    selected = sorted(roots)
    starts = [
        (game, kind, root)
        for game in selected
        for kind, root in (("targeted", roots[game]), ("normal", normal[game]))
    ]
    streams = []
    for game, kind, root in starts:
        for branch, action in enumerate(root["actions"]):
            # Targeted alternatives share a wall. Normal starts are independent
            # policy samples, including when they choose the same root action.
            continuation_seed = (
                seed
                + 1000000000
                + game
                + (games * (branch + 1) if kind == "normal" else 0)
            )
            streams.append(
                self_play.collection_steps(
                    games=1,
                    seed=continuation_seed,
                    collector=root["snapshot"].fork(
                        1, continuation_seed, until_hand_end=True
                    ),
                    forced_root=(
                        root["snapshot"].decision,
                        int(action),
                    ),
                    greedy=False,
                )
            )
    payments = []
    for branch, (batch, _) in enumerate(
        self_play.collect_streams(predict, streams)
    ):
        row = numpy.flatnonzero(batch["paired_root"])
        assert len(row) == 1
        _, kind, root = starts[branch // 2]
        assert batch["chosen"][row[0]] == root["actions"][branch % 2]
        assert batch["head"][row[0]] == root["head"]
        retain(batch, kind)
        payments.append(batch["payment_points"][row[0]])

    features = numpy.array(
        [root["features"] for _, _, root in starts],
        dtype=self_play.FEATURE_DTYPE,
    )
    for category, name in enumerate(CATEGORIES):
        statistics[f"assigned/{name}"] = int((categories == category).sum())
        statistics[f"eligible/{name}"] = int(seen[categories == category].sum())
        statistics[f"selected/{name}"] = int(
            sum(categories[game] == category for game in selected)
        )
    statistics["selected_roots"] = len(starts)
    statistics["targeted_roots"] = len(selected)
    statistics["normal_roots"] = len(selected)
    statistics["root_continuations"] = 2 * len(starts)
    return {
        "features": {name: features[name] for name in features.dtype.names},
        "head": numpy.array(
            [root["head"] for _, _, root in starts], dtype=numpy.int32
        ),
        "legal": numpy.array(
            [root["legal"] for _, _, root in starts], dtype=bool
        ).reshape(-1, 150),
        "actions": numpy.array(
            [root["actions"] for _, _, root in starts], dtype=numpy.int32
        ).reshape(-1, 2),
        "payment_points": numpy.array(payments, dtype=numpy.int32).reshape(
            -1, 2, int(outcomes.PAYMENT_CELLS.sum())
        ),
        "category": numpy.array(
            [
                categories[game] if kind == "targeted" else -1
                for game, kind, _ in starts
            ],
            dtype=numpy.int8,
        ),
        "source": numpy.array(
            [root["source"] for _, _, root in starts], dtype=numpy.int64
        ).reshape(-1, 4),
    }, statistics

"""Persistent synchronized learner replicas with one global row budget."""

import json
import os
import pathlib
import subprocess
import time

import tensorflow as tf

from training import monitor


def publish_stage(args, group, root, stage):
    """Release workers after generated files reach both host-local roots."""
    path = root / f"{stage}-ready.json"
    if group.chief:
        pending = path.with_suffix(".pending.json")
        monitor.write_json(pending, {"stopped": (root / "STOP").exists()})
        if args.sync_command:
            command = json.loads(pathlib.Path(args.sync_command).read_text())
            subprocess.run(
                [
                    value.format(root=str(root), stage=stage)
                    for value in command
                ],
                check=True,
            )
        pending.replace(path)
    else:
        while not path.exists():
            time.sleep(1)
    group.barrier()
    return json.loads(path.read_text())["stopped"]


class LearnerGroup:
    """One process per GPU; chief owns collection and completed artifacts."""

    def __init__(self):
        self.chief = True
        if "TF_CONFIG" in os.environ:
            self.chief = (
                json.loads(os.environ["TF_CONFIG"])["task"]["index"] == 0
            )
            self.strategy = tf.distribute.MultiWorkerMirroredStrategy(
                communication_options=(
                    tf.distribute.experimental.CommunicationOptions(
                        implementation=(
                            tf.distribute.experimental.CommunicationImplementation.NCCL
                        )
                    )
                )
            )
        else:
            self.strategy = tf.distribute.get_strategy()

        @tf.function(input_signature=[tf.TensorSpec([], tf.float32)])
        def synchronize(value):
            values = self.strategy.run(
                lambda: tf.distribute.get_replica_context().all_reduce(
                    tf.distribute.ReduceOp.SUM, tf.identity(value)
                )
            )
            return self.strategy.experimental_local_results(values)[0]

        self._synchronize = synchronize

    @property
    def replicas(self):
        return self.strategy.num_replicas_in_sync

    def barrier(self):
        self._synchronize(tf.constant(0.0)).numpy()

    def stopped(self, root):
        return bool(
            self._synchronize(
                tf.constant(float(self.chief and (root / "STOP").exists()))
            ).numpy()
        )

    def bind(self, learner, critic_learner, batch_size):
        self.local_batch = (batch_size + self.replicas - 1) // self.replicas
        self.packing = critic_learner.feature_packing
        self._pack = tf.function(
            self.packing.pack,
            input_signature=[
                tf.nest.map_structure(
                    lambda spec: tf.TensorSpec((None, *spec.shape), spec.dtype),
                    self.packing.structure,
                )
            ],
        )
        self._updates = {
            "critic": self._make_update(
                critic_learner.critic_update.python_function, actor=False
            ),
            "actor": self._make_update(
                learner.update.python_function, actor=True
            ),
        }

    def _make_update(self, operation, actor):
        def step(batch, count):
            if actor:
                batch = {
                    **batch,
                    "features": self.packing.unpack(batch["features"]),
                }
            return operation(batch, count)

        @tf.function
        def update(batch, count):
            metrics = self.strategy.run(step, args=(batch, count))
            names = tuple(metrics)
            packed = self.strategy.run(
                lambda values: tf.stack([values[name] for name in names]),
                args=(metrics,),
            )
            values = self.strategy.reduce(
                tf.distribute.ReduceOp.MEAN, packed, axis=None
            )
            return dict(zip(names, tf.unstack(values)))

        return update

    def update(self, update, batch):
        with tf.device("/CPU:0"):
            rows = {
                "features": self._pack(batch["features"]),
                **{
                    name: tf.convert_to_tensor(batch[name])
                    for name in ("head", "legal", "chosen", "payment_points")
                },
            }
            count = tf.shape(rows["chosen"])[0]

            def shard(ctx):
                begin = (
                    tf.cast(ctx.replica_id_in_sync_group, tf.int32)
                    * self.local_batch
                )
                indices = tf.minimum(
                    begin + tf.range(self.local_batch), count - 1
                )
                return (
                    tf.nest.map_structure(
                        lambda value: tf.gather(value, indices), rows
                    ),
                    tf.clip_by_value(count - begin, 0, self.local_batch),
                )

            rows, counts = (
                self.strategy.experimental_distribute_values_from_function(
                    shard
                )
            )
        return self._updates[update](rows, counts)

"""Mine all-seat Mortal match trajectories with a frozen scoring policy."""

import gzip
import json
import pathlib

import numpy

from log_dataset import _native_collection, sakigiri_regret
from training import self_play


def sources(directory):
    """Index a complete standard-South Mortal match for all-seat replay."""
    directory = pathlib.Path(directory).resolve()
    manifest = json.loads((directory / "evaluation.json").read_text())
    if (
        manifest["format"] != "riichienv_standard_south"
        or not manifest["mortal"]
    ):
        raise ValueError("Root selection requires a standard Mortal match")
    games = [
        json.loads(line)
        for line in (directory / "games.jsonl").read_text().splitlines()
    ]
    if len(games) != manifest["games"] or len(games) != 10000:
        raise ValueError("Root selection requires all 10,000 match games")
    if len({game["replay"] for game in games}) != len(games):
        raise ValueError("Match contains duplicate replay paths")
    return [
        {
            "path": str(directory / game["replay"]),
            "seed": game["seed"],
            "new_seats": game["new_seats"],
        }
        for game in sorted(games, key=lambda game: game["replay"])
    ]


def discover(predict, games, capture):
    """Replay seeded matches, verifying generated events against every log.

    Recorded choices advance discovery only. Root comparisons and subsequent
    counterfactual continuations use the supplied frozen policy instead.
    """
    collectors = {}
    order_pairs = []
    for game, game_record in enumerate(games):
        with gzip.open(game_record["path"], "rt") as stream:
            events = [json.loads(line) for line in stream]
        collectors[game] = _native_collection.NativeCollector.from_match(
            json.dumps(events), game_record["seed"], False
        )
        starts = [
            index
            for index, event in enumerate(events)
            if event["type"] == "start_kyoku"
        ]
        order_pairs.append(
            {
                (start + index, events[start + index]["actor"]): pair
                for start, end in zip(starts, starts[1:] + [len(events)])
                for index, (pair, _) in sakigiri_regret.round_pairs(
                    str(game), events[start:end]
                ).items()
            }
        )
    statistics = self_play.collection_counts()
    while collectors:
        requests = {}
        for game, collector in list(collectors.items()):
            request = collector.next()
            if request is None:
                for name, value in collector.finish()[1].items():
                    statistics[name] += value
                del collectors[game]
            else:
                requests[game] = request
        if not requests:
            break
        features = numpy.concatenate(
            [
                numpy.frombuffer(request["features"], self_play.FEATURE_DTYPE)
                for request in requests.values()
            ]
        )
        outputs = predict(features)
        start = 0
        for game, request in requests.items():
            count = len(request["head"])
            batch = self_play.request_batch(request)
            batch["indices"][:, 0] = game
            capture(
                collectors[game],
                {
                    **batch,
                    "sakigiri_pair": numpy.array(
                        [
                            order_pairs[game].get((event, seat), (-1, -1))
                            for event, seat in zip(
                                request["event"], request["seat"]
                            )
                        ],
                        dtype=numpy.int32,
                    ),
                    "behavior": self_play.policy_log_probabilities(
                        {
                            name: value[start : start + count]
                            for name, value in outputs.items()
                        },
                        batch["head"],
                        batch["legal"],
                    ),
                },
            )
            collectors[game].submit_recorded()
            start += count
    return {**statistics, "logged_games": len(games)}

"""Collect balanced root reruns and read their packed training shards."""

import numpy
import tensorflow as tf

from model import actions, critic
from training import monitor
from training.corrections import collection, matches


def batches(paths, packing, batch_size, seed):
    """Visit every retained decision once, with a bounded in-memory shard."""
    generator = numpy.random.default_rng(seed)
    for file_index in generator.permutation(len(paths)):
        with numpy.load(paths[file_index]) as archive:
            rows = {
                "features": {
                    name.removeprefix("features/"): archive[name]
                    for name in archive.files
                    if name.startswith("features/")
                },
                **{
                    name: archive[name]
                    for name in archive.files
                    if not name.startswith("features/")
                },
            }
        indices = generator.permutation(len(rows["chosen"]))
        for begin in range(0, len(indices), batch_size):
            selected = indices[begin : begin + batch_size]
            with tf.device("/CPU:0"):
                tensors = tf.nest.map_structure(
                    lambda value: tf.convert_to_tensor(value[selected]), rows
                )
                tensors["features"] = packing.unpack(tensors["features"])
            yield tensors


def collect(
    *,
    root,
    round_number,
    match_directory,
    recorded,
    order,
    seed,
    predict,
    root_evaluate,
    packing,
    report,
):
    """Mine a round in bounded chunks, retaining completed shards on stop."""
    rollout_files = []
    counts = {}
    rollout_positions = {"targeted": 0, "normal": 0}

    def retain(batch, source):
        path = root / (
            f"round-{round_number}-{source}-"
            f"{len(rollout_files):05d}-rollouts.npz"
        )
        pending = path.with_suffix(".partial.npz")
        numpy.savez_compressed(
            file=pending,
            **{
                "features/" + name: value
                for name, value in packing.pack_numpy(batch["features"]).items()
            },
            head=batch["head"],
            legal=batch["legal"],
            chosen=critic.chosen_actions(
                batch["features"],
                {
                    name: numpy.where(
                        batch["head"] == head, batch["chosen"], -1
                    )
                    for head, name in enumerate(actions.TRAIN_POLICY_HEADS)
                },
            ).numpy(),
            payment_points=batch["payment_points"],
            paired_root=batch["paired_root"],
        )
        pending.replace(path)
        rollout_files.append(path)
        rollout_positions[source] += len(batch["head"])

    for begin in range(0, len(order), 32):
        selected = order[begin : begin + 32]
        batch, collected = collection.collect(
            predict=predict,
            root_evaluate=root_evaluate,
            games=len(selected),
            seed=seed + begin * 4,
            retain=retain,
            discover=lambda capture: matches.discover(
                predict=predict,
                games=[recorded[index] for index in selected],
                capture=capture,
            ),
        )
        path = root / f"round-{round_number}-{begin:05d}-roots.npz"
        numpy.savez_compressed(
            file=path,
            **{
                "features/" + name: value
                for name, value in batch["features"].items()
            },
            **{
                name: value
                for name, value in batch.items()
                if name != "features"
            },
            match_index=selected[batch["source"][:, 0]],
        )
        for name, value in collected.items():
            counts[name] = counts.get(name, 0) + value
        report(
            "collecting-roots",
            {
                **counts,
                **{
                    "positions/" + name: value
                    for name, value in rollout_positions.items()
                },
            },
        )
        if (root / "STOP").exists():
            break
    monitor.write_json(
        root / f"round-{round_number}-rollouts.json",
        {
            "positions": rollout_positions,
            "files": [path.name for path in rollout_files],
            "match_source": str(match_directory),
            "games": [
                recorded[index] for index in order[: counts["logged_games"]]
            ],
            "features": "PackedBatch",
            "chosen": "critic-action-index",
        },
    )

"""Magnetic mirror descent at every sampled rollout decision."""

import tensorflow as tf

from model import actions
from model import actor as actor_layers
from model import critic, losses
from training import trainer


def mmd_terms(*, features, current, mirror, magnet, values, count):
    """Expected action value with proximal and fixed-magnet KL penalties."""
    values = tf.stop_gradient(values)
    mirror = tf.stop_gradient(mirror)
    magnet = tf.stop_gradient(magnet)
    probabilities = [
        critic.candidate_probabilities(
            features,
            {
                name: distribution[:, : actions.ACTOR_OUTPUTS[name][0]]
                for name in actions.TRAIN_POLICY_HEADS
            },
        )
        for distribution in (current, mirror)
    ]
    valid = tf.range(tf.shape(current)[0]) < count
    metrics = {
        "policy_gain_objective": losses.mean_valid(
            tf.reduce_sum(
                (probabilities[0] - probabilities[1]) * values, axis=-1
            ),
            valid,
        ),
        **{
            name: losses.mean_valid(
                tf.reduce_sum(tf.exp(current) * (current - reference), axis=-1),
                valid,
            )
            for name, reference in (
                ("mirror_kl", mirror),
                ("magnet_kl", magnet),
            )
        },
        "entropy": losses.mean_valid(
            -tf.reduce_sum(tf.exp(current) * current, axis=-1), valid
        ),
    }
    metrics["mmd_loss"] = (
        -metrics["policy_gain_objective"]
        + 0.3 * metrics["mirror_kl"]
        + 0.3 * metrics["magnet_kl"]
    )
    return metrics


class MMDTrainer:
    """One MMD objective for discovery, forced roots and descendants."""

    def __init__(self, *, network, mirror, magnet, learning_rate):
        self.network = network
        self.mirror = mirror
        self.magnet = magnet
        self.optimizer = trainer.AdamW(
            learning_rate=learning_rate, weight_decay=1e-4, clipnorm=1.0
        )
        self.optimizer.build(network.actor.trainable_variables)

    @tf.function(reduce_retracing=True)
    def update(self, batch, count):
        mirror = actor_layers.distribution(
            self.mirror(batch["features"], training=False),
            batch["head"],
            batch["legal"],
        )
        magnet = actor_layers.distribution(
            self.magnet(**batch["features"]), batch["head"], batch["legal"]
        )
        with tf.GradientTape() as tape:
            outputs, state = self.network.candidate_context(
                batch["features"],
                self.network.actor(batch["features"], training=False),
            )
            selected = critic.active_candidates(
                batch["features"], outputs["selected"]
            ) & (outputs["selected"][:, 0] < count)
            values = trainer.action_values(
                network=self.network,
                features=batch["features"],
                selected=tf.boolean_mask(outputs["selected"], selected),
                state=tf.boolean_mask(state, selected),
            )
            metrics = mmd_terms(
                features=batch["features"],
                current=actor_layers.distribution(
                    outputs, batch["head"], batch["legal"]
                ),
                mirror=mirror,
                magnet=magnet,
                values=values,
                count=count,
            )
            metrics["constraint_loss"] = losses.mean_valid(
                outputs["constraint_loss"],
                tf.range(tf.shape(batch["head"])[0]) < count,
            )
            loss = metrics["mmd_loss"] + 0.01 * metrics["constraint_loss"]
            scaled = loss / tf.distribute.get_strategy().num_replicas_in_sync
        return {
            **metrics,
            **trainer.apply_gradients(
                self.optimizer,
                tape,
                scaled,
                self.network.actor.trainable_variables,
            ),
            "joint_loss": loss,
            "learning_rate": tf.identity(self.optimizer.learning_rate),
        }

"""Native matches and paired estimates over full seat rotations."""

import argparse
import atexit
import concurrent.futures
import gzip
import hashlib
import importlib.util
import itertools
import json
import multiprocessing
import pathlib
import secrets
import shutil
import time

import numpy
import tensorboard.compat.proto.event_pb2 as event_proto
import tensorboard.compat.proto.summary_pb2 as summary_proto
import tensorboard.summary.writer.event_file_writer as event_writer

from model import outcomes

WORKER_POLICIES = {}
MATCH_FORMATS = ("riichienv_duplicate_south", "riichienv_standard_south")


def completed_games(root, requested, match_format):
    root = pathlib.Path(root)
    path = root / "games.jsonl"
    if not path.exists():
        return []
    raw = path.read_bytes()
    complete = raw[: raw.rfind(b"\n") + 1]
    if complete != raw:
        path.write_bytes(complete)
    results = []
    for line in complete.splitlines():
        row = json.loads(line)
        if row["format"] != match_format:
            raise ValueError("Evaluation format mismatch; use a fresh output")
        if (row["seed"], *row["new_seats"]) not in requested:
            continue
        with gzip.open(root / row["replay"], "rt") as stream:
            events = [json.loads(line) for line in stream]
        if events and events[-1]["type"] == "end_game":
            results.append(row)
    return results


def summarize(results, bootstrap_seed=0):
    rotations = {}
    for row in results:
        if (
            row["format"] not in MATCH_FORMATS
            or row["format"] != results[0]["format"]
        ):
            raise ValueError("Cannot combine different evaluation formats")
        rotation = rotations.setdefault(row["seed"], {})
        seat = tuple(row["new_seats"])
        if seat not in ((0,), (1,), (2,), (3,)) or seat in rotation:
            raise ValueError("Expected one distinct candidate seat per game")
        rotation[seat] = row
    complete = [
        row
        for _, rotation in sorted(rotations.items())
        if len(rotation) == 4
        for _, row in sorted(rotation.items())
    ]
    if not complete:
        return None
    grouped = {}
    for row in complete:
        pair = grouped.setdefault(row["seed"], {"new": [], "old": []})
        rank_points = outcomes.saint3_jade_south(row["scores"], row["ranks"])
        for seat in range(4):
            pair["new" if seat in row["new_seats"] else "old"].append(
                [
                    row["ranks"][seat],
                    row["ranks"][seat] == 1,
                    row["ranks"][seat] == 4,
                    rank_points[seat],
                    row["scores"][seat],
                    outcomes.SAINT3_JADE_SOUTH_OFFSETS[row["ranks"][seat] - 1],
                ]
            )
    metrics = (
        "placement",
        "first",
        "fourth",
        "rank_points",
        "score",
        "placement_points",
    )
    clusters = {
        model: numpy.array(
            [numpy.mean(pair[model], 0) for pair in grouped.values()]
        )
        for model in ("new", "old")
    }
    difference = clusters["new"] - clusters["old"]
    generator = numpy.random.default_rng(bootstrap_seed)
    bootstrap = numpy.concatenate(
        [
            difference[
                generator.integers(
                    0, len(grouped), (min(64, 2000 - begin), len(grouped))
                )
            ].mean(1)
            for begin in range(0, 2000, 64)
        ]
    )
    return {
        "format": results[0]["format"],
        "rank_point_formula": "ceil((final_score-25000)/1000 + ST3_offset)",
        "rank_point_offsets": list(outcomes.SAINT3_JADE_SOUTH_OFFSETS),
        "observed_games": len(results),
        "compared_games": len(complete),
        "seed_groups": len(grouped),
        "models": {
            model: dict(zip(metrics, values.mean(0).tolist()))
            for model, values in clusters.items()
        },
        "new_minus_old": dict(zip(metrics, difference.mean(0).tolist())),
        "paired_bounds": dict(
            zip(
                metrics,
                numpy.quantile(bootstrap, [0.025, 0.975], axis=0).T.tolist(),
            )
        ),
    }


def start_worker(root, devices, batch_games):
    from training import frozen_policy

    device = devices.get()
    for name in ("new", "old"):
        if (root / name / "checkpoint").exists():
            from training import mortal_policy

            WORKER_POLICIES[name] = mortal_policy.MortalPolicy(
                root / name, device=device, capacity=batch_games * 3
            )
        else:
            WORKER_POLICIES[name] = frozen_policy.FrozenPolicy(
                model_path=root / name / "saved_model",
                device=device,
                memory_mb=1536,
            )
        atexit.register(WORKER_POLICIES[name].close)


def play_games(tasks):
    import riichienv

    for policy in WORKER_POLICIES.values():
        policy.reset([seed for _, seed, _ in tasks])
    rule = riichienv.GameRule.default_tenhou()
    match_format = json.loads((tasks[0][0] / "evaluation.json").read_text())[
        "format"
    ]
    rule.duplicate = match_format == "riichienv_duplicate_south"
    games = [
        riichienv.RiichiEnv(game_mode=2, seed=seed, rule=rule)
        for _, seed, _ in tasks
    ]
    observations = [env.reset(oya=0) for env in games]
    while any(not env.done() for env in games):
        choices = [{} for _ in games]
        requests = [
            (game * 4 + actor, env, observation)
            for game, env in enumerate(games)
            if not env.done()
            for actor, observation in observations[game].items()
        ]
        pending = []
        for name, policy in WORKER_POLICIES.items():
            policy_requests = [
                request
                for request in requests
                if (request[0] % 4 == tasks[request[0] // 4][2])
                == (name == "new")
            ]
            if policy_requests:
                policy.send_requests(policy_requests)
                pending.append((policy, policy_requests))
        # Both frozen policies can construct features and infer concurrently.
        for policy, policy_requests in pending:
            for request, action in zip(
                policy_requests,
                policy.receive_actions(policy_requests),
                strict=True,
            ):
                game, actor = divmod(request[0], 4)
                choices[game][actor] = action
        for game, env in enumerate(games):
            if not env.done():
                observations[game] = env.step(choices[game])
    results = []
    for env, (root, seed, seat) in zip(games, tasks, strict=True):
        replay_path = f"replays/{seed}-{seat}.jsonl.gz"
        with gzip.open(root / replay_path, "wt") as stream:
            for event in env.mjai_log:
                stream.write(json.dumps(event) + "\n")
        ranks = list(env.ranks())
        results.append(
            {
                "format": match_format,
                "seed": seed,
                "new_seats": [seat],
                "replay": replay_path,
                "ranks": ranks,
                "scores": list(env.scores()),
                "rank_points": outcomes.saint3_jade_south(
                    env.scores(), ranks
                ).tolist(),
            }
        )
    return results


def publish_summary(root, results, bootstrap_seed, writer):
    comparison = summarize(results, bootstrap_seed)
    if comparison is not None:
        summary = root / "summary.json.partial"
        summary.write_text(json.dumps(comparison, indent=2))
        summary.replace(root / "summary.json")
    values = {
        "progress/completed_games": len(results),
        "progress/percent": 100
        * len(results)
        / json.loads((root / "evaluation.json").read_text())["games"],
    }
    if comparison is not None:
        for side, metrics in comparison["models"].items():
            values.update(
                {f"{side}/{key}": value for key, value in metrics.items()}
            )
        for key, value in comparison["new_minus_old"].items():
            values[f"difference/{key}"] = value
            values[f"difference/{key}_lower"] = comparison["paired_bounds"][
                key
            ][0]
            values[f"difference/{key}_upper"] = comparison["paired_bounds"][
                key
            ][1]
    writer.add_event(
        event_proto.Event(
            wall_time=time.time(),
            step=len(results),
            summary=summary_proto.Summary(
                value=[
                    summary_proto.Summary.Value(tag=key, simple_value=value)
                    for key, value in values.items()
                ]
            ),
        )
    )
    writer.flush()


def run(args):
    from training import frozen_policy

    if args.games <= 0 or args.games % 4:
        raise ValueError("Evaluation requires complete four-game seat groups")
    root = pathlib.Path(args.output)
    root.mkdir(parents=True, exist_ok=True)
    (root / "replays").mkdir(exist_ok=True)
    requested = {
        (args.seed + game // 4, game % 4) for game in range(args.games)
    }
    manifest = {
        "format": (
            "riichienv_standard_south"
            if args.mortal_source is not None
            else "riichienv_duplicate_south"
        ),
        "seed": args.seed,
        "games": args.games,
        "frozen_policy_randomness": "wall_actor_event_phase",
        "saved_models": {
            name: {
                str(path.relative_to(model_path)): hashlib.sha256(
                    path.read_bytes()
                ).hexdigest()
                for path in sorted(pathlib.Path(model_path).rglob("*"))
                if path.is_file()
            }
            for name, model_path in (("new", args.new), ("old", args.old))
            if name == "new" or args.mortal_source is None
        },
    }
    if args.mortal_source is not None:
        mortal_files = {
            "checkpoint": pathlib.Path(args.old),
            "source/libriichi.so": pathlib.Path(
                importlib.util.find_spec("libriichi").origin
            ),
            **{
                f"source/{name}": pathlib.Path(args.mortal_source)
                / "mortal"
                / name
                for name in ("model.py", "engine.py")
            },
            **{
                f"adapter/training/{name}": pathlib.Path(__file__).parent / name
                for name in ("mortal_policy.py", "frozen_policy.py")
            },
        }
        manifest["mortal"] = {}
        for name, path in mortal_files.items():
            with path.open("rb") as stream:
                manifest["mortal"][name] = hashlib.file_digest(
                    stream, "sha256"
                ).hexdigest()
    manifest_path = root / "evaluation.json"
    if (
        manifest_path.exists()
        and json.loads(manifest_path.read_text()) != manifest
    ):
        raise ValueError("Evaluation settings changed; use a fresh output")
    results = completed_games(root, requested, manifest["format"])
    manifest_path.write_text(json.dumps(manifest, indent=2) + "\n")
    writer = event_writer.EventFileWriter(
        str(args.tensorboard or root / "tensorboard")
    )
    atexit.register(writer.close)
    publish_summary(root, results, args.seed, writer)
    completed = {(row["seed"], *row["new_seats"]) for row in results}
    tasks = [(root, seed, seat) for seed, seat in sorted(requested - completed)]
    if not tasks:
        writer.close()
        return
    for name, model_path in (("new", args.new), ("old", args.old)):
        path = root / name
        if not path.exists():
            if name == "old" and args.mortal_source is not None:
                for filename, source in mortal_files.items():
                    (path / filename).parent.mkdir(parents=True, exist_ok=True)
                    shutil.copy2(source, path / filename)
                continue
            source = frozen_policy.source_directory(model_path)
            frozen_policy.freeze_source(source.parent, path / "source")
            # Retained production bundles put dataset helpers beside source/.
            if (source.parent.parent / "log_dataset").is_dir():
                frozen_policy.freeze_source(
                    source.parent.parent / "log_dataset",
                    path / "log_dataset",
                )
            frozen_policy.freeze_source(
                pathlib.Path(model_path), path / "saved_model"
            )
    started = time.monotonic()
    context = multiprocessing.get_context("spawn")
    devices = context.Queue()
    for worker in range(args.workers):
        devices.put(
            args.devices.split(",")[worker % len(args.devices.split(","))]
        )
    batches = [
        tasks[begin : begin + args.batch_games]
        for begin in range(0, len(tasks), args.batch_games)
    ]
    with concurrent.futures.ProcessPoolExecutor(
        max_workers=args.workers,
        mp_context=context,
        initializer=start_worker,
        initargs=(root, devices, args.batch_games),
    ) as executor:
        batches = iter(batches)
        pending = {
            executor.submit(play_games, batch)
            for batch in itertools.islice(batches, 2 * args.workers)
        }
        while pending:
            finished, pending = concurrent.futures.wait(
                pending, return_when=concurrent.futures.FIRST_COMPLETED
            )
            for future in finished:
                completed = future.result()
                with (root / "games.jsonl").open("a") as stream:
                    for row in completed:
                        stream.write(json.dumps(row) + "\n")
                results.extend(completed)
                publish_summary(root, results, args.seed, writer)
                print(
                    f"games={len(results)}/{args.games} "
                    f"elapsed_seconds={time.monotonic() - started:.3f}",
                    flush=True,
                )
            pending.update(
                executor.submit(play_games, batch)
                for batch in itertools.islice(batches, len(finished))
            )
    devices.close()
    devices.join_thread()
    writer.close()


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--new", required=True)
    parser.add_argument("--old", required=True)
    parser.add_argument(
        "--mortal-source",
        help="Mortal policy checkout; --old is its .pth or ZIP",
    )
    parser.add_argument("--output", required=True)
    parser.add_argument(
        "--tensorboard", help="Event directory; default OUTPUT/tensorboard"
    )
    parser.add_argument("--games", type=int, default=10000)
    parser.add_argument("--seed", type=int)
    parser.add_argument("--workers", type=int, default=1)
    parser.add_argument(
        "--devices", default="-1", help="Comma-separated GPU UUIDs; -1 uses CPU"
    )
    parser.add_argument("--batch-games", type=int, default=8)
    arguments = parser.parse_args()
    manifest = pathlib.Path(arguments.output) / "evaluation.json"
    if arguments.seed is None:
        arguments.seed = (
            json.loads(manifest.read_text())["seed"]
            if manifest.exists()
            else secrets.randbits(30)
        )
    if arguments.workers < 1 or arguments.batch_games < 1:
        parser.error("workers and batch-games must be positive")
    run(arguments)


if __name__ == "__main__":
    main()

