def improving_call_choices(features):
    """Legal call/discard choices that strictly reduce actual shanten."""
    # Family-category inputs clip high shanten; efficiency retains its value.
    distance = features["self_efficiency"][..., 0] * 8
    chi = features["chi_discard_legal"].astype(bool) & (
        features["chi_discard_shanten"] < distance[..., None, None] + 1
    )
    pon = features["pon_discard_legal"].astype(bool) & (
        features["pon_discard_shanten"] < distance[..., None, None] + 1
    )
    # Kan efficiency stores actual shanten / 8, before the replacement draw.
    kan = features["kan_legal_mask"][..., 1:].astype(bool) & (
        features["kan_efficiency"][..., 0] * 8 < distance[..., None]
    )
    decline = numpy.zeros((*distance.shape, 1), bool)
    response = numpy.concatenate(
        (
            decline,
            chi.reshape(*distance.shape, 111),
            pon.reshape(*distance.shape, 37),
            (kan.any(axis=-1) & (features["response_legal_mask"][..., 3] > 0))[
                ..., None
            ],
        ),
        axis=-1,
    )
    return response, numpy.concatenate((decline, kan), axis=-1)


def policy_log_probabilities(outputs, heads, legal):
    """Normalize active policy heads over their exact legal action masks."""
    scores = numpy.full((len(heads), 150), -1e9, numpy.float32)
    for head, name in enumerate(actions.TRAIN_POLICY_HEADS):
        rows = heads == head
        scores[rows, : actions.ACTOR_OUTPUTS[name][0]] = numpy.asarray(
            outputs[name]
        )[rows]
    scores[~legal] = -1e9
    scores -= scores.max(axis=1, keepdims=True)
    log_probability = scores - numpy.log(
        numpy.exp(scores).sum(axis=1, keepdims=True)
    )
    log_probability[~legal] = -1e9
    return log_probability


def request_batch(request):
    """Decode one native request for simulation or recorded-match discovery."""
    return {
        "features": numpy.frombuffer(request["features"], FEATURE_DTYPE),
        "head": numpy.asarray(request["head"]),
        "legal": numpy.frombuffer(request["legal"], numpy.bool_).reshape(
            len(request["head"]), 150
        ),
        "indices": numpy.asarray(
            [request[name] for name in ("game", "hand", "seat", "event")]
        ).T,
    }


def collect(
    predict,
    games,
    seed,
    *,
    collector=None,
    root_callback=None,
    greedy=False,
):
    return collect_streams(
        predict,
        [
            collection_steps(
                games,
                seed,
                collector=collector,
                root_callback=root_callback,
                greedy=greedy,
            )
        ],
    )[0]


def collect_streams(predict, streams):
    """Batch independent trajectories without merging their RNGs or targets."""
    results = [None] * len(streams)
    active = {index: next(stream) for index, stream in enumerate(streams)}
    while active:
        outputs = predict(
            next(iter(active.values()))
            if len(active) == 1
            else numpy.concatenate(list(active.values()), dtype=FEATURE_DTYPE)
        )
        offset = 0
        for index, features in list(active.items()):
            count = len(features)
            try:
                active[index] = streams[index].send(
                    {
                        name: value[offset : offset + count]
                        for name, value in outputs.items()
                    }
                )
            except StopIteration as finished:
                results[index] = finished.value
                del active[index]
            offset += count
    return results


def collection_steps(
    games,
    seed,
    *,
    collector=None,
    root_callback=None,
    forced_root=None,
    greedy=False,
):
    """Collect fresh games or supplied native continuations, without records."""
    if greedy:
        import tensorflow as tf

        from model import actor as actor_layers

    first = True
    if collector is None:
        collector = _native_collection.NativeCollector(games, seed)
    generator = numpy.random.default_rng(seed)
    batches = []
    while (request := collector.next()) is not None:
        count = len(request["head"])
        batch = request_batch(request)
        outputs = yield batch["features"]
        batch["behavior"] = policy_log_probabilities(
            outputs, batch["head"], batch["legal"]
        )
        if root_callback is not None:
            root_callback(collector, batch)
        if greedy:
            with tf.device("/CPU:0"):
                batch["chosen"] = actor_layers.greedy_choices(
                    batch["behavior"], batch["head"]
                ).numpy()
        else:
            cumulative = numpy.exp(batch["behavior"]).cumsum(
                axis=1, dtype=numpy.float64
            )
            cumulative /= cumulative[:, -1:]
            batch["chosen"] = (
                generator.random((len(cumulative), 1)) >= cumulative
            ).sum(axis=1)
        batch["paired_root"] = numpy.zeros(count, numpy.bool_)
        if first and forced_root is not None:
            decision, action = forced_root
            rows = numpy.arange(games) * (count // games) + decision
            assert batch["legal"][rows, action].all()
            batch["chosen"][rows] = action
            batch["behavior"][rows] = -1e9
            batch["behavior"][rows, action] = 0
            batch["paired_root"][rows] = True
        first = False
        collector.submit(batch["chosen"].tolist())
        batches.append(batch)
    logs, statistics = collector.finish()
    logs = [json.loads(events) for events in logs]
    for events in logs:
        outcomes.normalize_draw_payments(events)
    payments = []
    for events in logs:
        assert events[-1]["type"] in ("end_game", "start_kyoku")
        starts = [
            i
            for i, event in enumerate(events)
            if event["type"] == "start_kyoku"
        ]
        completed = len(starts) - (events[-1]["type"] != "end_game")
        payments.append(
            [
                outcomes.terminal_payments(events[start:end])
                for start, end in zip(
                    starts[:completed], starts[1:] + [len(events)]
                )
            ]
        )
    indices = numpy.concatenate([batch.pop("indices") for batch in batches])
    hand_indices = (
        numpy.concatenate(
            ([0], numpy.cumsum([len(game) for game in payments]))
        )[indices[:, 0]]
        + indices[:, 1]
    )
    batch = {
        **{
            name: numpy.concatenate([batch[name] for batch in batches])
            for name in (
                "head",
                "legal",
                "chosen",
                "behavior",
                "paired_root",
            )
        },
    }
    features = numpy.concatenate(
        [part["features"] for part in batches], dtype=FEATURE_DTYPE
    )
    payment_kind, payer, recipient = numpy.nonzero(outcomes.PAYMENT_CELLS)
    batch["payment_points"] = numpy.concatenate(payments)[
        hand_indices[:, None],
        payment_kind,
        (indices[:, 2, None] + payer) % 4,
        (indices[:, 2, None] + recipient) % 4,
    ] + numpy.int32(1000) * (
        (payment_kind == 3) & (features["riichi_state"][:, recipient] == 2)
    )
    batch["features"] = {name: features[name] for name in FEATURE_DTYPE.names}
    return batch, statistics

"""Shared optimizer, detached action values and observed-payment fitting."""

import tensorflow as tf

from log_dataset import training_data
from model import critic, joint_settlement, losses


class AdamW(tf.keras.optimizers.AdamW):
    """Clip already-reduced gradients; do not sum them a second time."""

    def _all_reduce_sum_gradients(self, grads_and_vars):
        return grads_and_vars


def apply_gradients(optimizer, tape, loss, variables):
    # Sum repeated tile entries locally: each embedding has only 34 rows.
    # Clip and synchronize the actual table gradient, not every occurrence.
    pairs = [
        (tf.convert_to_tensor(gradient), variable)
        for gradient, variable in zip(tape.gradient(loss, variables), variables)
        if gradient is not None
    ]
    gradients = tf.distribute.get_replica_context().all_reduce(
        tf.distribute.ReduceOp.SUM, [gradient for gradient, _ in pairs]
    )
    norm = tf.debugging.check_numerics(
        tf.linalg.global_norm(gradients), "Non-finite global gradient norm"
    )
    with tf.control_dependencies([norm]):
        optimizer.apply_gradients(
            zip(gradients, [variable for _, variable in pairs])
        )
    return {"gradient/global_norm": norm}


def action_values(*, network, features, selected, state, chunk_size=256):
    """Detached settlement forecasts for the MMD actor's legal actions."""
    public = joint_settlement.public_inputs(features)
    inputs = {
        **{
            name: tf.gather(value, selected[:, 0])
            for name, value in public.items()
        },
        **critic.public_inputs(features, selected),
        "state": tf.stop_gradient(state),
    }
    positions, position_indices = tf.unique(selected[:, 0])
    payoffs = joint_settlement.gather_position_payoffs(
        {**public, "dealer": features["dealer_relative_seat"]},
        positions,
    )
    integer_fields = tuple(
        name for name, value in inputs.items() if value.dtype == tf.int32
    )
    inputs = {
        name: (
            tf.bitcast(value, tf.float32) if name in integer_fields else value
        )
        for name, value in inputs.items()
    }
    weights = [
        tf.stop_gradient(value.value.read_value())
        for value in network.critic.trainable_variables
    ]
    chunk_count = (tf.shape(selected)[0] + chunk_size - 1) // chunk_size
    values = tf.TensorArray(
        tf.float32, size=chunk_count, element_shape=[chunk_size]
    )
    for chunk in tf.range(chunk_count):
        indices = tf.minimum(
            chunk * chunk_size + tf.range(chunk_size),
            tf.shape(selected)[0] - 1,
        )
        values = values.write(
            chunk,
            network.critic.candidate_chunk(
                inputs={
                    name: tf.gather(value, indices)
                    for name, value in inputs.items()
                },
                payoff=tf.gather(payoffs, tf.gather(position_indices, indices)),
                weights=weights,
                integer_fields=integer_fields,
            ),
        )
    return tf.stop_gradient(
        tf.scatter_nd(
            selected,
            tf.reshape(values.stack(), [-1])[: tf.shape(selected)[0]],
            [tf.shape(features["decision_phase"])[0], 295],
        )
    )


class CriticTrainer:
    """Observed payment NLL and critic constraints.

    Shared features/beliefs receive indirect gradients. This phase has no
    direct belief-label loss.
    See OBJECTIVE.md for the phase-by-head supervision table.
    """

    def __init__(self, network, features, learning_rate):
        self.network = network
        self.feature_packing = training_data.PackedBatch(features)
        self.optimizer = AdamW(
            learning_rate=learning_rate, weight_decay=1e-4, clipnorm=1.0
        )
        self.optimizer.build(network.trainable_variables)

    @tf.function(reduce_retracing=True)
    def critic_update(self, batch, count):
        features = self.feature_packing.unpack(batch["features"])
        with tf.GradientTape() as tape:
            encoded, state = self.network.candidate_context(
                features, self.network.encoder(features, training=False)
            )
            observed = self.network.chosen_inputs(
                features, encoded, state, batch["chosen"]
            )
            statistics = self.network.critic.supervised_statistics(
                observed,
                joint_settlement.payment_labels(
                    batch["payment_points"], observed
                ),
                valid=tf.range(tf.shape(batch["chosen"])[0]) < count,
            )
            metrics = dict(
                zip(
                    critic.CRITIC_METRICS,
                    tf.unstack(losses.packed_means(statistics)),
                )
            )
            loss = critic.settlement_objective(metrics)
            scaled = loss / tf.distribute.get_strategy().num_replicas_in_sync
        return {
            **{
                name: value
                for name, value in metrics.items()
                if name not in ("score_nll", "bonus_han_nll")
            },
            **apply_gradients(
                self.optimizer, tape, scaled, self.network.trainable_variables
            ),
            "loss": loss,
            "learning_rate": tf.identity(self.optimizer.learning_rate),
        }
